  AvgCommunicate_121372_Option_10 = {Text = "Yoksa?"},
  AvgCommunicate_121372_Option_11 = {Text = "Ee?"},
  AvgCommunicate_121375_Content_1 = {
    Text = "Ne söyleyeceğini biliyorum. Gönüllü oldular."
  },
  AvgCommunicate_121375_Content_10 = {
