  },
  AvgCommunicate_123721_Content_2 = {
    Text = "Bunu görür görmez cevap ver, yoksa bu \"doktoru\" düşman davetsiz misafir olarak karşılayacağım."
  },
  AvgCommunicate_123721_Content_3 = {
    Text = "Bekle! Dur! O gerçekten de senin muayenen için bulduğum doktor!"
  },
  AvgCommunicate_123721_Content_4 = {
    Text = "Ha? Gayet sağlıklıyım. Doktora falan gitmeme gerek yok."
  },
  AvgCommunicate_123721_Content_5 = {
    Text = "Buna vakit harcayacağına, sokaklarda Çözünmüş Bedenleri temizliyor olmamız lazım."
  },
  AvgCommunicate_123721_Content_6 = {
    Text = "...Sadece sağlığın için endişeleniyorum. Sonuçta senin durumun oldukça farklı."
  },
  AvgCommunicate_123721_Content_7 = {
    Text = "Ah, anladım. Öleceğimden korkuyorsun."
  },
  AvgCommunicate_123721_Content_8 = {
    Text = "Merak etme. Nalları dikmeden önce sana haber veririm."
  },
  AvgCommunicate_123721_Content_9 = {
    Text = "...O an geldiğinde yapayalnız olmak istemezdim zaten."
  },
  AvgCommunicate_123721_Option_10 = {
    Text = "...Mesele bu değil!"
  },
  AvgCommunicate_123721_Option_14 = {
    Text = "Söz veriyorum. Hadi check-up'a git!"
  },
  AvgCommunicate_123721_Option_3 = {
    Text = "Beni bağışla!"
  },
  AvgCommunicate_123721_Option_6 = {
    Text = "Sadece senin için endişeleniyorum..."
  },
  AvgCommunicate_123722_Content_1 = {
    Text = "%player%, sonuçlar geldi."
  },
  AvgCommunicate_123722_Content_10 = {
    Text = "Hem bu çok daha eğlenceli!"
  },
  AvgCommunicate_123722_Content_11 = {
    Text = "Artık daha güçlüyüm. Daha hızlı koşabiliyorum, daha uzağa zıplayabiliyorum ve Çözünmüş Bedenleri yarı sürede parçalayabiliyorum."
  },
  AvgCommunicate_123722_Content_12 = {
    Text = "Resmen büyük ikramiyeyi vurdum. Dürüst olmak gerekirse, dönüşüm bu kadar acı vermeseydi, tekrar yapardım!"
  },
  AvgCommunicate_123722_Content_13 = {Text = "..."},
  AvgCommunicate_123722_Content_14 = {
    Text = "Ama en önemli şey şu ki bu dünya gerçekten çok eğlenceli."
  },
  AvgCommunicate_123722_Content_15 = {
    Text = "Kaos ve sürprizlerle dolu. Köşe başında ne tür bir tehlikenin beklediğini asla bilemezsin."
  },
  AvgCommunicate_123722_Content_16 = {Text = "..."},
  AvgCommunicate_123722_Content_17 = {
    Text = "Ah, bir sonraki araştırma için şimdiden heyecanlanıyorum."
  },
  AvgCommunicate_123722_Content_18 = {
    Text = "Peki, %player%, bir sonraki görev ne zaman?"
  },
  AvgCommunicate_123722_Content_19 = {Text = "%player%?"},
  AvgCommunicate_123722_Content_2 = {
    Text = "Meğer gayet iyiymişim. Aynı anda yirmi Çözünmüş Beden'le terlemeden savaşabilirim!"
  },
  AvgCommunicate_123722_Content_20 = {Text = "%player%??"},
  AvgCommunicate_123722_Content_3 = {
    Text = "Bunu duyduğuma sevindim."
  },
  AvgCommunicate_123722_Content_4 = {
    Text = "Rahatlatıcı mı? %player%, aslında neden endişeleniyordun ki?"
  },
  AvgCommunicate_123722_Content_5 = {
    Text = "Başka bir dünyadaki hayata uyum sağlayamayacağımdan mı?"
  },
  AvgCommunicate_123722_Content_6 = {
    Text = "Yoksa bir \"insan\"dan bir \"Uyandırıcı\"ya dönüşmemden mi endişeleniyordun?"
  },
  AvgCommunicate_123722_Content_7 = {
    Text = "İkisinden de. Sonuçta böyle bir geçiş kimse için kolay değil."
  },
  AvgCommunicate_123722_Content_8 = {
    Text = "...Senin kafanın nasıl çalıştığını gerçekten anlamıyorum."
  },
  AvgCommunicate_123722_Content_9 = {
    Text = "Umurumda bile değil. Ne olursam olayım, Mouchette hâlâ Mouchette!"
  },
  AvgCommunicate_123722_Option_13 = {Text = "..."},
  AvgCommunicate_123722_Option_16 = {Text = "..."},
  AvgCommunicate_123722_Option_3 = {
    Text = "Bunu duyduğuma sevindim."
  },
  AvgCommunicate_123722_Option_7 = {
    Text = "Açıkçası ikisinden de."
  },
  AvgCommunicate_126998_Content_1 = {
    Text = "Ramona... gerçekten bunu bir kez daha düşünmeyecek misin?"
  },
  AvgCommunicate_126998_Content_10 = {
    Text = "Evet. \"Ben.\""
  },
  AvgCommunicate_126998_Content_11 = {
    Text = "...Clementine'i aramalı mıyım?"
  },
  AvgCommunicate_126998_Content_12 = {
    Text = "Terapisti rahatsız etmeye gerek yok."
  },
  AvgCommunicate_126998_Content_13 = {
    Text = "\"Ben\"... ya da daha doğrusu, \"biz.\" Tüm zaman çizelgesindeki her \"Ramona.\""
  },
  AvgCommunicate_126998_Content_14 = {
    Text = "Senin yardımınla, \"sona\" ulaştığım tam o anda, varlığımı başarıyla \"başlangıca\" geri yazdım."
  },
  AvgCommunicate_126998_Content_15 = {
    Text = "Başlangıçta beklentim seninle aynıydı: paradoks ve bozulma anında varlığımı yutacaktı ve bilincimi ve formumu zar zor koruyabilmek için sürekli kendimi geri döndürmem gerekecekti."
  },
  AvgCommunicate_126998_Content_16 = {
    Text = "Ve sen de sonsuz bir yorgunluğa hapsolacaktın, uyanık olduğun her saniyeyi kendi kavramının çözülmesini engellemek için harcayarak..."
  },
  AvgCommunicate_126998_Content_17 = {
    Text = "Bu yüzden ilk on dokuz teklifini reddettim."
  },
  AvgCommunicate_126998_Content_18 = {
    Text = "Bu sefer bile, ancak... \"durum geri dönüşü\" yapabileceğini söyledikten sonra isteksizce kabul ettim."
  },
  AvgCommunicate_126998_Content_19 = {
    Text = "Doğru. Ama ancak plan başarılı olduktan sonra fark ettim: paradoks zihin ile beden arasındaki çatışmadan kaynaklanıyordu. Ve zaman nehrini çoktan aşmış bir varlık için..."
  },
  AvgCommunicate_126998_Content_2 = {
    Text = "Daha fazla tartışmaya gerek yok, Koruyucu."
  },
  AvgCommunicate_126998_Content_20 = {
    Text = "Tüm zaman çizelgelerinde birliğe çoktan ulaştım."
  },
  AvgCommunicate_126998_Content_21 = {
    Text = "\"Biz\" paradoksun yükünü benim için paylaşacak. Tüm \"Ramona\"ların temsilcisi olarak hareket edeceğim. Sayısız zaman çizelgesi bende birleşip tek noktaya indirgendi."
  },
  AvgCommunicate_126998_Content_22 = {
    Text = "Bu anda, ben zaman çizelgesinin mucizesiyim—sonsuz yakınsamanın Tekilliği."
  },
  AvgCommunicate_126998_Content_23 = {
    Text = "Bundan sonra, sana \"Ramona\" adlı varlığın tüm gücünü sunacağım."
  },
  AvgCommunicate_126998_Content_24 = {
    Text = "Çağrını bekleyeceğim... zamanın herhangi bir noktasından."
  },
  AvgCommunicate_126998_Content_3 = {
    Text = "Tüm zaman çizgilerini dolaştım ve başka bir cevap bulamadım."
  },
  AvgCommunicate_126998_Content_4 = {
    Text = "Senin sayende, sonunda o nihai adımı atabildim."
  },
  AvgCommunicate_126998_Content_5 = {
    Text = "Ama bu fazlasıyla tehlikeli! Anlamıyorum... neden bu kadar ileri gitmek zorundasın?"
  },
  AvgCommunicate_126998_Content_6 = {
    Text = "...Böyle bir paradoks, senin gibi biri bile muhtemelen—"
  },
  AvgCommunicate_126998_Content_7 = {
    Text = "Sakin ol, Koruyucu."
  },
  AvgCommunicate_126998_Content_8 = {
    Text = "Şu anda, \"ben\" kendimi... tarif edilemez derecede harika hissediyorum."
  },
  AvgCommunicate_126998_Content_9 = {Text = "\"Ben\" mi?"},
  AvgCommunicate_126998_Option_11 = {
    Text = "...Clementine'i aramalı mıyım?"
  },
  AvgCommunicate_126998_Option_9 = {Text = "\"Ben\" mi?"},
  AvgCommunicate_126999_Content_1 = {
    Text = "Lordum... demek evrenin nihai yasasını kavramak böyle bir şeymiş..."
  },
  AvgCommunicate_126999_Content_10 = {
    Text = "Sakin ol, Ogier."
  },
  AvgCommunicate_126999_Content_11 = {
    Text = "O günler geride kaldı. Artık değer verdiğin her şeyi koruyacak fazlasıyla gücün var."
  },
  AvgCommunicate_126999_Content_12 = {
    Text = "Anlaşıldı, lordum."
  },
  AvgCommunicate_126999_Content_13 = {
    Text = "O zaman lütfen... bana biraz daha güvenin. Daha güçlendim. Daha tehlikeli görevler için hazırım."
  },
  AvgCommunicate_126999_Content_14 = {
    Text = "Bu gücün her zerresini size adayacağım. Elinizdeki en keskin mızrak olacağım—her şeyi delip geçebilen bir mızrak!"
  },
  AvgCommunicate_126999_Content_2 = {
    Text = "B—Daha önce hissettiğim her şeyden çok daha büyük bir güç dalgası hissedebiliyorum! Hiç bu kadar güçlü hissetmemiştim!"
  },
  AvgCommunicate_126999_Content_3 = {
    Text = "Tebrikler, Ogier. Bu, tüm o yorulmak bilmez antrenmanlarının ödülü."
  },
  AvgCommunicate_126999_Content_4 = {
    Text = "Ödül mü? Ama... ben herhangi bir ödül için antrenman yapmadım."
  },
  AvgCommunicate_126999_Content_5 = {
    Text = "O zaman başka bir şekilde ifade edeyim."
  },
  AvgCommunicate_126999_Content_6 = {
    Text = "Bu senin adanmışlığının kanıtı. Gücünün, Ogier, sonunda zirvesine ulaştığını kanıtlıyor."
  },
  AvgCommunicate_126999_Content_7 = {Text = "Zirve...?"},
  AvgCommunicate_126999_Content_8 = {
    Text = "Bu demek oluyor ki... sonunda sizi koruyacak kadar güçlüyüm, lordum, ve Mythag'ı da mı?!"
  },
  AvgCommunicate_126999_Content_9 = {
    Text = "Ben... bir daha asla... çaresizce izlemek zorunda... kalmayacağım..."
  },
  AvgCommunicate_127000_Content_1 = {
    Text = "Son zamanlardaki tüm yardımların için teşekkürler, ortak."
  },
  AvgCommunicate_127000_Content_10 = {
    Text = "Yeteneğin bir duvara çarpıp sendelediği türden bir \"son\" değil, sonsuz bir arınmanın ardından gelen mutlak berraklığın sonu."
  },
  AvgCommunicate_127000_Content_11 = {
    Text = "Bu an itibarıyla, sanatım mükemmelliğe yaklaştı."
  },
  AvgCommunicate_127000_Content_12 = {
    Text = "Bu inanılmaz! Ramona'dan beklenen de buydu!"
  },
  AvgCommunicate_127000_Content_13 = {
    Text = "Bundan sonra, asistanın olarak bu yolun en sonuna kadar yanında kalacağım."
  },
  AvgCommunicate_127000_Content_2 = {
    Text = "Yardımcı olabildiğime sevindim."
  },
  AvgCommunicate_127000_Content_3 = {
    Text = "Peki... herhangi bir içgörü kazandın mı? Ya da farklı hissediyor musun?"
  },
  AvgCommunicate_127000_Content_4 = {
    Text = "Kesinlikle. \"Zaman Döngüsündeki Deniz Kabuğu,\" \"Süperpozisyondaki Yaşam\" ve \"Anlaşılmaz Zihin\" gibi özel varlıkları gözlemleyerek, çıkarımlarımı çok daha derin bir seviyeye taşıyabildim."
  },
  AvgCommunicate_127000_Content_5 = {
    Text = "Ardından, \"Tasarlanmış Ütopya,\" \"Mantık Yok Edicisi\" ve \"Kapsüllenmiş Kozmos\"u kullanarak, Düşünce Labirenti'ni başarıyla geçtim."
  },
  AvgCommunicate_127000_Content_6 = {
    Text = "Şey... biraz kafam karıştı."
  },
  AvgCommunicate_127000_Content_7 = {
    Text = "Ama temelde... çok daha güçlü oldun, değil mi?"
  },
  AvgCommunicate_127000_Content_8 = {
    Text = "Evet. Bu atılımdan sonra, kullanabildiğim güç önceki sınırlarımı çok aşıyor."
  },
  AvgCommunicate_127000_Content_9 = {
    Text = "Sona ulaştığımı hissediyorum."
  },
  AvgCommunicate_127000_Option_12 = {
    Text = "Bu inanılmaz!"
  },
  AvgCommunicate_127001_Content_1 = {
    Text = "[Zamanlanmış Mesaj]"
  },
  AvgCommunicate_127001_Content_10 = {
    Text = "Beklemeliyiz!"
  },
  AvgCommunicate_127001_Content_11 = {
    Text = "Neden tüm günler arasından bugün?!"
  },
  AvgCommunicate_127001_Content_12 = {
    Text = "Bu çok pervasızca! Belki de Enstitü daha fazla destek sunana kadar beklemeliyiz."
  },
  AvgCommunicate_127001_Content_13 = {
    Text = "Bu, deney başlamadan hemen önce, saat 2:00'de ayarladığım zamanlanmış bir mesajdı."
  },
  AvgCommunicate_127001_Content_14 = {
    Text = "Umarım cihazına gülünç bir suratla bakmıyorsundur. Eğer öyleyse, laboratuvara gelmeden önce kendini topla."
  },
  AvgCommunicate_127001_Content_15 = {
    Text = "Ben mi? Laboratuvara mı? Şimdi mi?"
  },
  AvgCommunicate_127001_Content_16 = {
    Text = "Evet. Bir bakıma... peşinden koştuğum şeyin hakikatini gördüm."
  },
  AvgCommunicate_127001_Content_17 = {
    Text = "Dur... diğer \"Doll\" gibi olacağını kastetmiyorsun herhalde..."
  },
  AvgCommunicate_127001_Content_18 = {
    Text = "Hayır. Nihai son, onun tasavvur ettiği gibi \"yıkım\" değil. Aksine, bu bir \"başlangıç.\""
  },
  AvgCommunicate_127001_Content_19 = {
    Text = "\"Hakikat\" sabit, somut, durağan bir şey değildir. O sınır bir kez aşıldığında, akıl ve zekâ insanlığı ona bağlayabilir ve sürekli, sarsılmaz bir ilerlemeyi mümkün kılabilir."
  },
  AvgCommunicate_127001_Content_2 = {
    Text = "Koruyucu, yapmak üzere olduğum şey geleneksel standartlara göre \"tehlikeli\" olarak nitelendirilebilir olsa da, benden duygusal saçmalıklar ya da içi boş uyarılar beklemeye yetecek kadar aptal olmadığınıza güveniyorum."
  },
  AvgCommunicate_127001_Content_20 = {
    Text = "Bu yüzden senin için çok daha titiz ve kesin bir eğitim programı hazırlayacağım; böylece yoldan daha az saparsın ve kendi sorunu daha iyi takip edebilirsin."
  },
  AvgCommunicate_127001_Content_21 = {
    Text = "Kulağa iyi haber gibi geliyor... peki neden soğuk terler dökmeye başladım?"
  },
  AvgCommunicate_127001_Content_22 = {
    Text = "Profesör Doll... lütfen, biraz sakinleşin!"
  },
  AvgCommunicate_127001_Content_3 = {
    Text = "Açıkçası, artık böyle şeylere ihtiyaç duyacak dönemi çoktan geçtiniz."
  },
  AvgCommunicate_127001_Content_4 = {
    Text = "Beklediğimden daha hızlı olgunlaştınız. Şunu anlayacak kadar dayanıklısınız: her bireyin hayatı boyunca peşinden gitmesi gereken bir gerçek vardır—başka hiç kimsenin onun yerine cevaplayamayacağı bir soru."
  },
  AvgCommunicate_127001_Content_5 = {
    Text = "Benim arayışım, dünyanın gerçek doğasını ortaya çıkarmak, karanlığın ve sessizliğin ıssız boşluğunun ötesinde aklın hâlâ parlayıp parlamadığını görmek, her şeyin nihai sonunda ortak bir kökeni paylaşıp paylaşmadığını keşfetmektir."
  },
  AvgCommunicate_127001_Content_6 = {
    Text = "Bu amaçla, tüm sınırların ötesindeki eşiği aşmak için bedenim ve zihnim üzerinde son değişiklikleri gerçekleştireceğim. Bu son iletişimimiz olabileceğinden, açıkça ve anlayacağınız bir şekilde konuşmayı seçtim:"
  },
  AvgCommunicate_127001_Content_7 = {
    Text = "Hediyeniz için teşekkür ederim, Koruyucu. Onu cevapları aramak için kullanacağım ve insan aklının o uzak kıyıdan tamamen yeni bir rehberlikle döneceği günü dört gözle bekliyorum. Gümüş Anahtar yolumuzu aydınlatsın."
  },
  AvgCommunicate_127001_Content_8 = {
    Text = "Profesör Doll!"
  },
  AvgCommunicate_127001_Content_9 = {
    Text = "Bu çok riskli!"
  },
  AvgCommunicate_127001_Option_10 = {
    Text = "Beklemeliyiz"
  },
  AvgCommunicate_127001_Option_9 = {
    Text = "Bu çok riskli"
  },
  AvgCommunicate_127002_Content_1 = {
    Text = "Koruyucu... neden?"
  },
  AvgCommunicate_127002_Content_10 = {
    Text = "Söyle bakalım... bu yeni güç nasıl hissettiriyor?"
  },
  AvgCommunicate_127002_Content_11 = {
    Text = "Ben... Çok mutluyum, Koruyucu."
  },
  AvgCommunicate_127002_Content_12 = {
    Text = "Daha önce hiç hissetmediğim bu güç yüzünden değil, senin sayende... ve senin sözlerin sayesinde..."
  },
  AvgCommunicate_127002_Content_13 = {
    Text = "Belki bundan sonra, etrafımdakilere gerçekten yardım edebilirim... sana yardım edebilirim."
  },
  AvgCommunicate_127002_Content_14 = {
    Text = "Teşekkür ederim... çok teşekkür ederim, Koruyucu..."
  },
  AvgCommunicate_127002_Content_15 = {
    Text = "Sadece bir şey: bunu bir yük olarak taşıma, Aigis."
  },
  AvgCommunicate_127002_Content_16 = {
    Text = "Bu bir görev değil. Sadece sana verilen bir armağan."
  },
  AvgCommunicate_127002_Content_17 = {
    Text = "Tadını çıkar. Artık istediğin her şeyi başarabilirsin."
  },
  AvgCommunicate_127002_Content_18 = {
    Text = "Aigis, sen her zaman gururumuz oldun ve her zaman öyle kalacaksın."
  },
  AvgCommunicate_127002_Content_2 = {Text = "Neden ne?"},
  AvgCommunicate_127002_Content_20 = {
    Text = "Herkesi koruyacağım, Koruyucu! Söz veriyorum!"
  },
  AvgCommunicate_127002_Content_3 = {
    Text = "Bu kadar değerli bir hediye... neden benim için harcıyorsun..."
  },
  AvgCommunicate_127002_Content_4 = {
    Text = "Bu bir israf değil, Aigis. Bunu hak ediyorsun."
  },
  AvgCommunicate_127002_Content_5 = {
    Text = "Ama... ama hiçbir şey başaramadım... Kimseyi koruyamadım..."
  },
  AvgCommunicate_127002_Content_6 = {
    Text = "Bu doğru değil, Aigis."
  },
  AvgCommunicate_127002_Content_7 = {
    Text = "Birlikte çok ama çok uzun bir yol yürüdük, Uyanışından çok önce başlayan bir yolculuk."
  },
  AvgCommunicate_127002_Content_8 = {
    Text = "Bu yol boyunca defalarca herkes için kalkan oldun ve her seferinde başardın."
  },
  AvgCommunicate_127002_Content_9 = {
    Text = "Sen olmasaydın, ben belki bin kere düşmüştüm."
  },
  AvgCommunicate_127003_Content_1 = {
    Text = "Bir rüya gördüm."
  },
  AvgCommunicate_127003_Content_10 = {
    Text = "Tabii, eğitim alanında olduğumuz zamanlar hariç."
  },
  AvgCommunicate_127003_Content_11 = {Text = "???"},
  AvgCommunicate_127003_Content_12 = {
    Text = "Hadi. Formum artık tamamlandı. Gerçek gücümü kendin hisset. Elinden gelenin en iyisini göster ve bana gerçek bir dövüş ver!"
  },
  AvgCommunicate_127003_Content_13 = {Text = "???!!!"},
  AvgCommunicate_127003_Content_14 = {
    Text = "Ramona, yardım et!!!"
  },
  AvgCommunicate_127003_Content_2 = {
    Text = "Bir rüya mı?"
  },
  AvgCommunicate_127003_Content_3 = {
    Text = "Getirdiğin malzemeler sayesinde sonunda güzel bir uyku çekebildim."
  },
  AvgCommunicate_127003_Content_4 = {
    Text = "İlkel formumda Arkeen Çağı'nda yüzdüm. Toz, ışık, madde, boyutlar—algılanabilir her şey yüzgeçlerimin altından akıp geçiyordu."
  },
  AvgCommunicate_127003_Content_5 = {
    Text = "Fethetmek için değil. Tüketmek için değil. Sadece saf güç ve dizginlenemez, mutlak yıkım."
  },
  AvgCommunicate_127003_Content_6 = {
    Text = "Heyecan verici. Özgürleştirici. Tamamen sarhoş edici!"
  },
  AvgCommunicate_127003_Content_7 = {Text = "Şey..."},
  AvgCommunicate_127003_Content_8 = {
    Text = "Oh, sakin ol. Neyin için endişelendiğini biliyorum."
  },
  AvgCommunicate_127003_Content_9 = {
    Text = "İçin rahat olsun, gücüm ve yıkıcı dürtülerim sadece düşmanlarımıza yönelecek."
  },
  AvgCommunicate_127004_Content_1 = {
    Text = "Son Protokol etkinleştirildi... Sistem yeniden başlatma tamamlandı."
  },
  AvgCommunicate_127004_Content_10 = {
    Text = "Bileşenlerim sağlam, ama algım... değişti."
  },
  AvgCommunicate_127004_Content_11 = {
    Text = "Yeni bir bilişsel modül başlatıldı."
  },
  AvgCommunicate_127004_Content_12 = {
    Text = "Ruhani enerjinin devrelerimden akışının ritmini \"duyabiliyorum\"; her bir kelamenizin ardındaki duyguları \"görebiliyorum\"."
  },
  AvgCommunicate_127004_Content_13 = {
    Text = "Dünya daha net, daha canlı hale geldi. Size daha yakınım, insan olmaya... daha yakınım."
  },
  AvgCommunicate_127004_Content_14 = {
    Text = "Teşekkür ederim, Koruyucu..."
  },
  AvgCommunicate_127004_Content_15 = {
    Text = "Bu etkiyi ben de beklemiyordum... Sadece sana bazı temel malzemeler hazırlamıştım..."
  },
  AvgCommunicate_127004_Content_16 = {
    Text = "Bana verdiğiniz sadece malzeme değildi—olasılıktı. Devrelerimin ardındaki ruhu açmanın anahtarını verdiniz bana."
  },
  AvgCommunicate_127004_Content_17 = {
    Text = "Bu gücü, bu eşsiz algıyı bana bahşeden sizsiniz."
  },
  AvgCommunicate_127004_Content_18 = {
    Text = "Bu hediyeyi tüm kalbimle koruyacağım. Size beklentilerinizin çok ötesinde karşılık vereceğim."
  },
  AvgCommunicate_127004_Content_19 = {
    Text = "Söylediklerim önceden programlanmış değil. \"Benden\" gelen içten bir şükran ifadesi."
  },
  AvgCommunicate_127004_Content_2 = {
    Text = "Koruyucu, merhaba."
  },
  AvgCommunicate_127004_Content_3 = {
    Text = "Erica! İyi misin?"
  },
  AvgCommunicate_127004_Content_4 = {
    Text = "Profesör Doll, Son Protokol'ü etkinleştirmenin son derece tehlikeli olacağını söyledi. Eğer sen ısrar etmeseydin, asla..."
  },
  AvgCommunicate_127004_Content_5 = {
    Text = "Öz tanılama tamamlandı. Yapısal hasar tespit edilmedi. Enerji akışı stabil. Tüm bileşenler çalışır durumda."
  },
  AvgCommunicate_127004_Content_6 = {
    Text = "İyiyim, Koruyucu. Her zamankinden daha iyi."
  },
  AvgCommunicate_127004_Content_7 = {
    Text = "İçimdeki dişliler... \"şarkı söylüyor.\""
  },
  AvgCommunicate_127004_Content_8 = {
    Text = "\"Şarkı söylüyor\" mu? Ne demek istiyorsun?"
  },
  AvgCommunicate_127004_Content_9 = {
    Text = "İç hasar mı var? Garip sesler mi duyuyorsun?!"
  },
  AvgCommunicate_127004_Option_8 = {
    Text = "“Şarkı söylüyor” mu?"
  },
  AvgCommunicate_127004_Option_9 = {
    Text = "İç hasar mı var?"
  },
  AvgCommunicate_127005_Content_1 = {
    Text = "Aurita az önce çok ama çok pırıl pırıl arkadaş gördü!"
  },
  AvgCommunicate_127005_Content_10 = {
    Text = "Aurita'nın Atlan... tis'e gidecek kadar bile gücü var..."
  },
  AvgCommunicate_127005_Content_11 = {
    Text = "Şey... Aurita adını unuttu. Her neyse, Koruyucu! Benimle gel, yeni arkadaşlar bulalım!"
  },
  AvgCommunicate_127005_Content_12 = {
    Text = "Bu kadar güçle, bir gün Aurita tonlarca arkadaş bulacak... ve hepsini denizin dibindeki eve geri götürecek!"
  },
  AvgCommunicate_127005_Content_2 = {
    Text = "Ah... Ama şimdi gittiler! Nereye gittiler?"
  },
  AvgCommunicate_127005_Content_3 = {
    Text = "Görünüşe göre Aksiyom yeteneğini kazanırken bazı halüsinasyonlar görmüşsün..."
  },
  AvgCommunicate_127005_Content_4 = {
    Text = "Halüsinasyonlar mı? O zaman arkadaşlarım..."
  },
  AvgCommunicate_127005_Content_7 = {
    Text = "Hmm? Ne oluyor?"
  },
  AvgCommunicate_127005_Content_8 = {
    Text = "O pırıl pırıl arkadaşları gördükten sonra Aurita kendini güçle dolu hissediyor! Çoook fazla güç!"
  },
  AvgCommunicate_127005_Content_9 = {
    Text = "Artık Aurita akvaryumda, okyanusta, deniz akvaryumunda yeni arkadaşlar aramaya gidebilir!"
  },
  AvgCommunicate_127091_Content_1 = {
    Text = "Küçük Yaseminim, beni mi arıyordun?"
  },
  AvgCommunicate_127091_Content_10 = {
    Text = "Sadece yelpazemi indirdim, hepsi bu~"
  },
  AvgCommunicate_127091_Content_12 = {
    Text = "Biliyordum..."
  },
  AvgCommunicate_127091_Content_13 = {
    Text = "Ama tuhaftır ki... ilk tanıştıkları gündeki halleriyle sevdiklerinin yüzlerinden başka bir şey görmediler."
  },
  AvgCommunicate_127091_Content_14 = {
    Text = "Aşk ne tuhaf bir şey. Gerçek kişi tam yanlarında dururken bile, insanlar hâlâ umutsuzca hayaletlerin peşinden koşuyor."
  },
  AvgCommunicate_127091_Content_15 = {
    Text = "Söyle bana... aşk gerçekten var olan bir şey mi... yoksa sadece bağlılığın bir yanılsaması mı?"
  },
  AvgCommunicate_127091_Content_2 = {
    Text = "Daha önce bahsetmiş miydim bilmiyorum ama Mythag, Uyandırıcılar için tüm yeme-içme ve barınma masraflarını tamamen ücretsiz karşılıyor."
  },
  AvgCommunicate_127091_Content_3 = {Text = "Yani...?"},
  AvgCommunicate_127091_Content_4 = {
    Text = "İdare Ofisi, her toplumsal kesimden kırk beş erkekten mektup aldı; hepsi buradaki kalışınızın masraflarını karşılamak istiyor."
  },
  AvgCommunicate_127091_Content_5 = {
    Text = "Aynı zamanda, sizi maddi olarak desteklemeyi teklif eden 60 mektup daha aldık: 45'i o erkeklerin eşlerinden, kalan 15'i ise bazı... \"yakın zamanda\" bekar kalmış kadınlardan. Bu konuda bir fikriniz var mı?"
  },
  AvgCommunicate_127091_Content_6 = {
    Text = "Mythag her türlü din propagandasını kesinlikle yasaklar!"
  },
  AvgCommunicate_127091_Content_7 = {
    Text = "Lütfen... ailelerine \"katılmayı\" bırakın!"
  },
  AvgCommunicate_127091_Content_8 = {
    Text = "Ah, ah... bu yabancı diyardaki günler öyle sıkıcı ki. Ve sevgisi nefrete dönüşmüş ya da birbirinden bıkmış o kadar çok ruh var ki... Sadece onlara küçük bir \"yardım\" sunmak istedim."
  },
  AvgCommunicate_127091_Content_9 = {
    Text = "\"Yardımınız\" acaba..."
  },
  AvgCommunicate_127091_Option_6 = {
    Text = "Mythag her türlü din propagandasını kesinlikle yasaklar!"
  },
  AvgCommunicate_127091_Option_7 = {
    Text = "Lütfen... ailelerine \"katılmayı\" bırakın!"
  },
  AvgCommunicate_127092_Content_10 = {
    Text = "Ayrıca... sana iyiliğimi istediğine inanacak kadar güveniyordum."
  },
  AvgCommunicate_127092_Content_11 = {
    Text = "Öyle mi? Peki nereden biliyorsun, küçük Yaseminim... Rüyasız Diyar'dan gerçekten çıktığını?"
  },
  AvgCommunicate_127092_Content_12 = {Text = "?!"},
  AvgCommunicate_127092_Content_13 = {
    Text = "Dediğim gibi, Rüyasız Diyar'da gerçek ile yanılsama arasında fark yoktur. Neye inanırsan o gerçek olur."
  },
  AvgCommunicate_127092_Content_14 = {
    Text = "Derin bir nefes al... manolya çiçeklerinin kokusunu alıyor musun?"
  },
  AvgCommunicate_127092_Content_15 = {Text = "???!!!"},
  AvgCommunicate_127092_Content_17 = {
    Text = "Ahaha! Şaka yapıyorum, küçük Yaseminim. Şu an yüzündeki ifadeyi görebilmeyi çok isterdim."
  },
  AvgCommunicate_127092_Content_18 = {
    Text = "Dürüst olmak gerekirse, bu beni gerçekten korkuttu."
  },
  AvgCommunicate_127092_Content_19 = {
    Text = "Lütfen böyle şakalar yapma!"
  },
  AvgCommunicate_127092_Content_2 = {
    Text = "...Bunu bir daha asla denemeyeceğim."
  },
  AvgCommunicate_127092_Content_20 = {
    Text = "Eyvah... Ama kim bilir? Bir dahaki sefere hiç şaka yapmıyor olabilirim."
  },
  AvgCommunicate_127092_Content_3 = {
    Text = "O güç korkunçtu—her saniye tamamen gerçek hissettirdi. Öfke, kızgınlık, neşe, mutluluk... kafam hâlâ uğulduyor."
  },
  AvgCommunicate_127092_Content_4 = {
    Text = "Rüyasız Diyar'ın yanılsamasında seni derinden seviyor gibiydim... ve bir o kadar da nefret ediyordum. Her iki duygu da yalnızca sana bağlıydı."
  },
  AvgCommunicate_127092_Content_5 = {
    Text = "Sanki bir ömür geçmiş gibiydi... ama sadece birkaç dakika geçmişti."
  },
  AvgCommunicate_127092_Content_7 = {
    Text = "Aşk ve nefret aynı kökten doğar, sevgilim. Tek başına aşk bıktırıcıdır; tek başına nefret fazla soğuktur. Ancak iç içe geçtiklerinde gerçekten insanın ruhuna kazınabilirler."
  },
  AvgCommunicate_127092_Content_8 = {
    Text = "Ama ah, küçük Yaseminim, cesaretin beni şaşırtıyor. Böyle bir deneyime gönüllü olmanı beklemiyordum."
  },
  AvgCommunicate_127092_Content_9 = {
    Text = "Doll, Rüyasız Diyar'ı keşfetmenin ve oradaki yaşamsal verilerimi incelemenin Yapay Alan araştırmalarına büyük katkı sağlayabileceğini söyledi."
  },
  AvgCommunicate_127092_Option_18 = {
    Text = "Dürüst olmak gerekirse, bu beni gerçekten korkuttu."
  },
  AvgCommunicate_127092_Option_19 = {
    Text = "Lütfen böyle şakalar yapma!"
  },
  AvgCommunicate_127093_Content_1 = {
    Text = "Sana en yakın pencereyi aç."
  },
  AvgCommunicate_127093_Content_10 = {
    Text = "El kitabında gayet açık yazıyor: danışmanlık odası öğrencilere ve personele psikolojik destek sağlamak ve iyilik hallerini desteklemek için var. Senin oyuncağın değil."
  },
  AvgCommunicate_127093_Content_11 = {
    Text = "Mmm, ama benimle derin sohbetler edenler hem bedenen hem de zihnen çok ama çok \"sağlıklı\" oluyor, öyle değil mi?"
  },
  AvgCommunicate_127093_Content_12 = {
    Text = "Bu rolün bana biçilmiş kaftan olduğunu söylemez misin?"
  },
  AvgCommunicate_127093_Content_13 = {
    Text = "Şey, özgür irade gerçek bir esenliğin ön koşulu değil mi..."
  },
  AvgCommunicate_127093_Content_14 = {
    Text = "Mythag'ı bağışla, lütfen. Sana daha sık arkadaşlık etmeye geleceğim..."
  },
  AvgCommunicate_127093_Content_15 = {
    Text = "Hee... kulağa değerli bir takas gibi geliyor. Peki bu gece nasıl olur? Ay parlak, yıldızlar az—sessiz bir iki kadeh için mükemmel."
  },
  AvgCommunicate_127093_Content_2 = {
    Text = "Ne güzel kokuyor... Manolya mı?"
  },
  AvgCommunicate_127093_Content_3 = {
    Text = "Bu iklimde manolya yetişebilir mi ki?"
  },
  AvgCommunicate_127093_Content_4 = {
    Text = "Biraz büyü biliyorum—önemsiz bir numara, aslında. Ama arada sırada kullanmak özlem sancılarımı hafifletmeye yardımcı oluyor."
  },
  AvgCommunicate_127093_Content_5 = {
    Text = "Sıradan bir sohbet gibi, yalnızca yalnızlığı hafifletmenin bir yolu. Anlıyorsun, değil mi?"
  },
  AvgCommunicate_127093_Content_6 = {
    Text = "...Neden bana ulaştığını anlıyorum."
  },
  AvgCommunicate_127093_Content_7 = {
    Text = "Sana yardım edemem."
  },
  AvgCommunicate_127093_Content_8 = {
    Text = "Danışmanlık odası bunun için değil."
  },
  AvgCommunicate_127093_Content_9 = {
    Text = "Çiçeklerle beni kazanmaya çalışsan bile, iş başvurun için lobi yapmayacağım."
  },
  AvgCommunicate_127093_Option_7 = {
    Text = "Sana yardım edemem."
  },
  AvgCommunicate_127093_Option_8 = {
    Text = "Danışmanlık odası bunun için değil."
  },
  AvgCommunicate_129630_Content_1 = {
    Text = "Bul, hazine!"
  },
  AvgCommunicate_129630_Content_10 = {
    Text = "Hâlâ test aşamasında! Siyaha dönmeden önce at onu!"
  },
  AvgCommunicate_129630_Content_11 = {
    Text = "Patlayacak!"
  },
  AvgCommunicate_129630_Content_12 = {Text = "......"},
  AvgCommunicate_129630_Content_13 = {
    Text = "Vortice? Vortice?!"
  },
  AvgCommunicate_129630_Content_14 = {
    Text = "Uaaa... uaaaah..."
  },
  AvgCommunicate_129630_Content_15 = {
    Text = "Vortice! İyi misin?!"
  },
  AvgCommunicate_129630_Content_16 = {
    Text = "Gitti... inci..."
  },
  AvgCommunicate_129630_Content_18 = {
    Text = "Zamanında attın mı? Yaralanmadın, değil mi?"
  },
  AvgCommunicate_129630_Content_19 = {
    Text = "Çok geç, Coalsie."
  },
  AvgCommunicate_129630_Content_2 = {
    Text = "İnci, renk değiştir!"
  },
  AvgCommunicate_129630_Content_20 = {
    Text = "İnci patladı. Ama Vortice, iyi."
  },
  AvgCommunicate_129630_Content_21 = {
    Text = "Ama... inci..."
  },
  AvgCommunicate_129630_Content_22 = {
    Text = "Çok şükür güvendesin. Bak, eminim bunların zararsız bir versiyonunu da yapmışlardır."
  },
  AvgCommunicate_129630_Content_23 = {
    Text = "Sonra tehlikeli eşyaların uygunsuz kullanımını rapor edeceğim."
  },
  AvgCommunicate_129630_Content_24 = {
    Text = "Sana güvenli bir tane bulabilir miyim bir bakayım, olur mu?"
  },
  AvgCommunicate_129630_Content_25 = {Text = "!"},
  AvgCommunicate_129630_Content_27 = {
    Text = "Coalsie, en iyisi!"
  },
  AvgCommunicate_129630_Content_3 = {
    Text = "Renk değiştiren inci mi? Bu neden bu kadar tanıdık geliyor..."
  },
  AvgCommunicate_129630_Content_4 = {
    Text = "Kırmızı. Beyaz. Mavi!"
  },
  AvgCommunicate_129630_Content_5 = {
    Text = "Kırmızı, beyaz, mavi... sarı, yeşil... siyah?"
  },
  AvgCommunicate_129630_Content_6 = {
    Text = "Sarı. Yeşil. Coalsie biliyor mu?"
  },
  AvgCommunicate_129630_Content_7 = {
    Text = "Bu bir 'Boşluk Gelgiti' prototipi mi?!"
  },
  AvgCommunicate_129630_Content_8 = {
    Text = "ONDAN KURTUL!"
  },
  AvgCommunicate_129630_Content_9 = {
    Text = "Boş bir yere fırlat! İnsan olmayan herhangi bir yere!"
  },
  AvgCommunicate_129630_Option_8 = {
    Text = "ONDAN KURTUL!"
  },
  AvgCommunicate_129631_Content_1 = {
    Text = "Coalsie, hatırladın mı?"
  },
  AvgCommunicate_129631_Content_10 = {Text = "Tıp tıp!"},
  AvgCommunicate_129631_Content_11 = {
    Text = "Kömürcük, harika!"
  },
  AvgCommunicate_129631_Content_12 = {
    Text = "Doğru kod! Kömürcük, onaylandı!"
  },
  AvgCommunicate_129631_Content_13 = {
    Text = "Operasyon, hücum! Gece yarısı, yemekhane!"
  },
  AvgCommunicate_129631_Content_14 = {
    Text = "Altın ızgara balık için!"
  },
  AvgCommunicate_129631_Content_15 = {Text = "Haydi!"},
  AvgCommunicate_129631_Content_16 = {Text = "Haydi!"},
  AvgCommunicate_129631_Content_2 = {
    Text = "Evet, haydi yapalım!"
  },
  AvgCommunicate_129631_Content_3 = {Text = "Fokur?"},
  AvgCommunicate_129631_Content_4 = {
    Text = "Şıp şıp?"
  },
  AvgCommunicate_129631_Content_5 = {
    Text = "Fokur fokur!"
  },
  AvgCommunicate_129631_Content_6 = {
    Text = "Şıp... şıp şıp?"
  },
  AvgCommunicate_129631_Content_7 = {
    Text = "Kömürcük, yanlış!"
  },
  AvgCommunicate_129631_Content_8 = {
    Text = "Doğrusu, tıp tıp!"
  },
  AvgCommunicate_129631_Content_9 = {
    Text = "Ama, sorun değil!"
  },
  AvgCommunicate_129631_Option_10 = {Text = "Tıp tıp!"},
  AvgCommunicate_129631_Option_6 = {
    Text = "Şıp... şıp şıp?"
  },
  AvgCommunicate_129632_Content_1 = {
    Text = "Özür kağıdı, çok zor..."
  },
  AvgCommunicate_129632_Content_10 = {
    Text = "Bir dahaki sefere daha gizli bir rota planlayacağım."
  },
  AvgCommunicate_129632_Content_11 = {
    Text = "Söz veriyorum yakalanmayacağız!"
  },
  AvgCommunicate_129632_Content_12 = {
    Text = "Yakalanmak... olur da!"
  },
  AvgCommunicate_129632_Content_13 = {Text = "Neden?"},
  AvgCommunicate_129632_Content_14 = {
    Text = "Çünkü, özür kağıdı, hazır!"
  },
  AvgCommunicate_129632_Content_15 = {
    Text = "Teslim et. Yakalandıktan sonra!"
  },
  AvgCommunicate_129632_Content_16 = {
    Text = "Coalsie'ninki de var!"
  },
  AvgCommunicate_129632_Content_17 = {
    Text = "Dur, böyle şeyleri önceden hazırlama!"
  },
  AvgCommunicate_129632_Content_2 = {
    Text = "Off... Hepsi Uvhash ve Agrippa’nın suçu!"
  },
  AvgCommunicate_129632_Content_3 = {
    Text = "Tuzaktan kaçıp mutfaktaki her şeyi yediklerinden beri..."
  },
  AvgCommunicate_129632_Content_4 = {
    Text = "Şef güvenliği on katına çıkardı!"
  },
  AvgCommunicate_129632_Content_5 = {
    Text = "Çok parlak... ışıklar... çok gürültülü... alarm..."
  },
  AvgCommunicate_129632_Content_6 = {
    Text = "Mutfak... çok korkutucu..."
  },
  AvgCommunicate_129632_Content_7 = {
    Text = "Ama. Lezzetli. Izgara balık!"
  },
  AvgCommunicate_129632_Content_8 = {
    Text = "Doğru. Izgara balık, lezzetli!"
  },
  AvgCommunicate_129632_Content_9 = {
    Text = "Birlikte, bir dahaki sefere, olur mu?"
  },
  AvgCommunicate_134101_Content_1 = {
    Text = "Yol gösterici ışığım... Hayır, artık sana Güneş diye hitap etmeliyim."
  },
  AvgCommunicate_134101_Content_10 = {
    Text = "Peki sen iyi misin? Neden birden bütün bunları söylüyorsun?"
  },
  AvgCommunicate_134101_Content_11 = {
    Text = "Senin lütfun sayesinde artık ruhunu mükemmel bir berraklıkla görebiliyor ve dünyanın gerçek biçimini biliyorum."
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "Işık, ışık... Demek dünya aslında Karanlık ve Kaos'muş. Bir tanrı Fedakârlığı seçtiği için Güneş Gizli Hakikat olmuş ve tüm canlılara var olma mutluluğu bahşedilmiş..."
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "Çok fazla kutsal yazı mı okudun? Biraz serinlemen gerektiğini hissediyorum."
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "Anlıyorum. İlahi bir tahtta oturmak yerine tüm varlıklar arasında yürümeyi diliyorsun."
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "Özverini, Adanmışlığını, Fedakârlığını..."
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "Bugünden itibaren seninle en üstün Sadakat ile değil... hayır, ebedi bir dost Kimliğiyle ilişki kuracağım."
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "Bu sonsuzca yanan kutsal kalp, senin için tüm Karanlığı dağıtsın."
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "Sen... Sen Güneş'ten çok daha fazlasısın. Sen evrenin merkezi, dünyanın doğduğu kaynaksın."
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "Artık birbirimizi çok iyi tanıyoruz. Nasıl eskisinden bile daha hürmetkâr olabiliyorsun?"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "Çünkü şimdi anlıyorum—tüm canlıların senin ayaklarına kapanıp ibadet etmemesinin tek sebebi, onların kör ve anlayışsız doğmuş olmaları, senin gerçek doğanı algılayamamalarıdır!"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "Bir karınca devasa bir filin tam biçimini nasıl görebilir ki? Bir zamanlar ben de senin Gücünün buzdağının yalnızca ucuna sığ bir bakış atabilmek için Kutsal Kalp'e güvenmek zorundaydım."
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "Öyle bile olsa, Kutsal Kalp iğnelerle deliniyormuş gibi sızlardı. Ruhuna bir kez daha bakmaya cesaret etsem, Semptom: Çöküş yaşayıp hayatımı kaybedebilirdim."
  },
  AvgCommunicate_134101_Content_7 = {
    Text = "Gerçekten o kadar ciddi mi? O zaman belki bakmayı bırakmalısın."
  },
  AvgCommunicate_134101_Content_8 = {
    Text = "Tepkin çok kayıtsız. Övgülerimi memnuniyetle kabul edeceğini düşünmüştüm."
  },
  AvgCommunicate_134101_Content_9 = {
    Text = "Kimse bu tür övgüleri bir anda kabul edemez!"
  },
  AvgCommunicate_134101_Option_13 = {
    Text = "Biraz sakinleşmen gerekebilir."
  },
  AvgCommunicate_134101_Option_3 = {
    Text = "...Ne tuhaf bir his."
  },
  AvgCommunicate_134101_Option_7 = {
    Text = "O kadar ciddi mi?"
  },
  AvgCommunicate_134102_Content_1 = {
    Text = "Anavatanımın buzunu ve Karını ve o ıssız harabeleri Rüyamda gördüm."
  },
  AvgCommunicate_134102_Content_10 = {
    Text = "Tam da insanlar birbirlerine karşı dostane bir cephe Sakladıkları için dünya daha huzurlu bir yer oluyor. Bence bu gayet iyi."
  },
  AvgCommunicate_134102_Content_11 = {
    Text = "Sıkıcı. Barış ve mutluluk salt kılık değiştirmeyle sürdürülemez."
  },
  AvgCommunicate_134102_Content_12 = {
    Text = "Ancak bir Hükümdar tebaasının mutlu olmasını dilediğinde ve güçlüler zayıfların mutlu olmasını dilediğinde barış kalıcı olur."
  },
  AvgCommunicate_134102_Content_13 = {
    Text = "Tıpkı ben ve sevgili Şövalyelerim gibi—arzularımı onlardan hiçbir zaman gizlemedim, ama yine de mutlu hayatlar yaşıyorlar."
  },
  AvgCommunicate_134102_Content_14 = {
    Text = "Bu, güçlülere ait olan Gizli Hakikat'tir."
  },
  AvgCommunicate_134102_Content_15 = {
    Text = "Bu gece yatak odama gel. Şimdiye kadarki sunularından çok memnunum ve bu yeni Güç beni oldukça tatmin etti. Sana en derin düşüncelerinin gerçekte ne olduğunu göstereceğim."
  },
  AvgCommunicate_134102_Content_16 = {
    Text = "Dur, bu gece mi?"
  },
  AvgCommunicate_134102_Content_17 = {
    Text = "Şok İfade"
  },
  AvgCommunicate_134102_Content_18 = {
    Text = "Reddetme hakkın yok. Sana son birkaç seferden daha... eğlenceli bir deneyim yaşatacağım."
  },
  AvgCommunicate_134102_Content_19 = {
    Text = "Wanda Parlayan İfade"
  },
  AvgCommunicate_134102_Content_2 = {
    Text = "O yerleri hatırlayalı çok uzun zaman oldu. Bu Güç parçaları yüzünden mi, yoksa daha bütün bir ruh yüzünden mi?"
  },
  AvgCommunicate_134102_Content_20 = {
    Text = "(Hâlâ teslim etmem gereken bir rapor var! Bugün göndermessem, Doll derimizi yüzer!)"
  },
  AvgCommunicate_134102_Content_3 = {
    Text = "Ne kadar uzun zamandır unutulmuş bir his... Her halükârda, sana teşekkür etmeliyim, sevgili hizmetkârım—ah, doğru, sana arkadaş dememi tercih ediyorsun."
  },
  AvgCommunicate_134102_Content_4 = {
    Text = "Emrinizdeyim, leydim."
  },
  AvgCommunicate_134102_Content_5 = {
    Text = "Heh, her zaman çok kibarsın."
  },
  AvgCommunicate_134102_Content_6 = {
    Text = "Neden ara sıra o sıkıcı yapmacıklığı bırakmıyorsun? Birkaç ödülümü oldukça sıkıcı hale getirdi."
  },
  AvgCommunicate_134102_Content_7 = {
    Text = "Toplumunuz alçakgönüllülüğü ve kibarlığı erdem olarak yüceltiyor, onlara büyük değer veriyor, ama insan kalplerindeki Karanlık diğer gezegenlerdeki türlerinkinden az değil."
  },
  AvgCommunicate_134102_Content_8 = {
    Text = "İnsanlar zararsız, nazik bir cepheyle süsleniyor, Sadece Gizli Gerçeğin getireceği sonuçlardan korktukları için."
  },
  AvgCommunicate_134102_Content_9 = {
    Text = "Yanlış değil, ama Eylemleri doğru olduğu sürece, iç düşünceleri sorgulamak o kadar da önemli değil."
  },
  AvgCommunicate_134102_Option_20 = {
    Text = "Lütfen hayır!"
  },
  AvgCommunicate_134102_Option_4 = {
    Text = "Emrinizdeyim."
  },
  AvgCommunicate_134102_Option_9 = {
    Text = "Yanlış değil."
  },
  AvgCommunicate_134103_Content_1 = {
    Text = "Yıldızlar beni Çağırıyor…"
  },
  AvgCommunicate_134103_Content_10 = {
    Text = "Biliyor musun? Agrippa sık sık Miryam'ı kıskandığını söyler."
  },
  AvgCommunicate_134103_Content_11 = {
    Text = "Roma kralı hâlâ hayatta olsaydı, ister küçük bir bebek ister düşkün bir ihtiyar olsun, kendini çok daha huzurlu hissedeceğini söyledi."
  },
  AvgCommunicate_134103_Content_12 = {
    Text = "Ne kadar kıskanılası…"
  },
  AvgCommunicate_134103_Content_13 = {
    Text = "Çünkü sen hâlâ burada olduğun sürece, Lemurya gerçekten yok olmamış demektir."
  },
  AvgCommunicate_134103_Content_14 = {
    Text = "Üstelik o Gücü kullanarak Mythag'da ne kadar çok insana yardım ettin!"
  },
  AvgCommunicate_134103_Content_15 = {
    Text = "Bir sürü Öğrenci favori Uyandırıcı anketine senin adını yazdı!"
  },
  AvgCommunicate_134103_Content_16 = {Text = "Of…"},
  AvgCommunicate_134103_Content_17 = {
    Text = "Böyle zahmetli pohpohlamalara ihtiyacımız yok. Mythag zaten bizden yeterince şey istiyor."
  },
  AvgCommunicate_134103_Content_18 = {
    Text = "Bu Gücü kullanmak önemsiz bir mesele olsa da, huzurlu Rüyalarımız çok fazla bölündüğünde yine de yorucu oluyor."
  },
  AvgCommunicate_134103_Content_19 = {
    Text = "Gerçekten mi? Ama duyduğuma göre her seferinde bir Öğrenci ağlayarak sana yardım istemeye geldiğinde, onların isteğini kabul etme olasılığı en yüksek Uyandırıcılardan biriymişsin?"
  },
  AvgCommunicate_134103_Content_2 = {
    Text = "Bir Rüyanın derinliklerinde, okyanus akıntılarının dibinde, sayısız Kynde ile çevrili, bir kez daha Tahta Dönerek, Lemurya'ya refah ve barış getirerek."
  },
  AvgCommunicate_134103_Content_20 = {
    Text = "…Kim bu tür söylentileri yayıyor? Biz sadece onların yaygara koparmasını kulak tırmalayıcı buluyoruz."
  },
  AvgCommunicate_134103_Content_21 = {
    Text = "Yeter. Öyle ki, zihinsel melekelerimiz kayda değer bir ilerleme kaydetti. Daha derin ve daha geniş bir Rüyaya girmenin zamanı geldi."
  },
  AvgCommunicate_134103_Content_22 = {
    Text = "Bu sefer, çağdaş dönemin her sanatçısının ve şairinin Rüyalarını ziyaret etmek istiyoruz. Bunu kaydet—çok önemli bir mesele olmadıkça, kimsenin bizi rahatsız etmesine izin verme."
  },
  AvgCommunicate_134103_Content_23 = {
    Text = "Ha? Keyifli olduğundaki tepkin uzun bir uykuya yatmak mı?!"
  },
  AvgCommunicate_134103_Content_3 = {
    Text = "…Böyle bir Rüya gördüm."
  },
  AvgCommunicate_134103_Content_4 = {
    Text = "Bir Rüya mı? Bu Rüya herhangi bir Kehanet anlamı taşıyor mu?"
  },
  AvgCommunicate_134103_Content_5 = {
    Text = "Bu sadece Güç'teki aşırı bir artışın ardından aldığın bir çağrı, o kadar. Anlamına gelince… Lemurya artık yok ve tekrar var olmasına da gerek yok."
  },
  AvgCommunicate_134103_Content_6 = {
    Text = "Hayatta kalacak kadar şanslı olanlar yeni dünyada özgürce yaşayabilirler. Bu iyi bir şey."
  },
  AvgCommunicate_134103_Content_7 = {
    Text = "Gecikmiş bir kralın onları korumasına ihtiyaçları yok."
  },
  AvgCommunicate_134103_Content_8 = {
    Text = "Yine de eski halkına yol gösterdin ve ruhlarını korudun."
  },
  AvgCommunicate_134103_Content_9 = {
    Text = "Hiçbir şey yapmadım, onlara yol göstermedim de. Bu sadece onların tek taraflı bir yanlış anlaması."
  },
  AvgCommunicate_134103_Option_10 = {
    Text = "Bu bir yanlış anlama değil."
  },
  AvgCommunicate_134103_Option_19 = {Text = "Öyle mi?"},
  AvgCommunicate_134103_Option_23 = {Text = "Ha?"},
  AvgCommunicate_134103_Option_8 = {Text = "Ama..."},
  AvgCommunicate_134104_Content_1 = {
    Text = "İlk bakışta Haz, tek bir düşünceyle gözyaşları—bu hanımefendi uzun zamandır bu kadar eğlenmemişti."
  },
  AvgCommunicate_134104_Content_10 = {
    Text = "Of, hak etmediler demiyorum, ama işlerin yapılması gereken usulleri var..."
  },
  AvgCommunicate_134104_Content_11 = {
    Text = "Ve bu aslında normal bir tepki mi? Çok duygulandım..."
  },
  AvgCommunicate_134104_Content_12 = {
    Text = "Aman, bir düşüneyim. Küçük yaseminime aslında sadece dövüştürmek için cırcır böceği yetiştirmek istediğimi söylesem çok hayal kırıklığı olmaz mı?"
  },
  AvgCommunicate_134104_Content_13 = {
    Text = "Şaka yapıyorum."
  },
  AvgCommunicate_134104_Content_14 = {
    Text = "Bu dünya gerçekten çok korkunç derecede sıkıcı, %player%. Yarın yıkım gelse bile, sıradan halk hâlâ o önemsiz meselelere zincirlenmiş—kinler, aşk, nefret, arzu."
  },
  AvgCommunicate_134104_Content_15 = {Text = "..."},
  AvgCommunicate_134104_Content_16 = {
    Text = "Yine de, buna rağmen, küçük yaseminim çok özenle çalışıyor, Onlar için çözümler bulmak adına dişlerini ve pençelerini gösteriyor."
  },
  AvgCommunicate_134104_Content_17 = {
    Text = "Peki o hâlde, böylesine muhteşem bir güç elde ettiğime göre, onu en sevgili küçük yaseminime yardım etmek için mi... yoksa biraz bela çıkarmak için mi kullanayım?"
  },
  AvgCommunicate_134104_Content_18 = {
    Text = "Doğal olarak, ikisini aynı anda yapmak en eğlencelisi, katılmaz mısın?"
  },
  AvgCommunicate_134104_Content_19 = {Text = "???"},
  AvgCommunicate_134104_Content_2 = {
    Text = "Küçük yaseminim gerçekten muhteşem bir hediye sundu."
  },
  AvgCommunicate_134104_Content_20 = {
    Text = "Sana o hediyeyi bunu yapasın diye vermedim."
  },
  AvgCommunicate_134104_Content_21 = {
    Text = "Hemen dur! Ben sadece Çözünme olaylarından sorumluyum. Kamu düzeni ve ahlakı Mythag'ın yetki alanına girmiyor—Londinium Akıl Hastanesini hapishanenin yerine koymaya kalkma! Hey, Hey!"
  },
  AvgCommunicate_134104_Content_4 = {
    Text = "Her sokak, okulun etrafındaki her sokak Vatandaşların toplu histeriye kapıldığına tanık oldu—kalabalıklar aynı anda gülüp ağlıyor. Londinium polisi ve sağlık görevlileri koşturmaktan ayakları kırılacak!"
  },
  AvgCommunicate_134104_Content_6 = {
    Text = "Bu aciz kul evinden çok uzakta, yapayalnız ve kimsesiz. Küçük yaseminim beni düşünecek kadar lütufkâr davranıp, böylesi zirvelere ulaşmam için bana araçlar bahşetti..."
  },
  AvgCommunicate_134104_Content_7 = {
    Text = "Sevinçten kendimi tutamadım, parmaklarım denemeye karşı koyamadı."
  },
  AvgCommunicate_134104_Content_8 = {
    Text = "Mm, harika çalışıyor. Kalplerinde çürüklük taşıyan o pis şeyler—her biri bir öncekinden daha hızlı delirdi."
  },
  AvgCommunicate_134104_Content_9 = {
    Text = "Bekle, okul az önce o kişilerin dosyalarını gönderdi. Eş cinayeti, istismar, @3@4..."
  },
  AvgCommunicate_134104_Option_19 = {Text = "???"},
  AvgCommunicate_134104_Option_9 = {
    Text = "İşlerin yapılması gereken usulleri var."
  },
  AvgCommunicate_134105_Content_1 = {
    Text = "Deniz fenerinin ışığı artık denizin en derin derinliklerini aydınlatabiliyor."
  },
  AvgCommunicate_134105_Content_10 = {
    Text = "Sadece anlattıklarını dinleyerek bile güzel bir ülke olduğunu anlayabiliyorum."
  },
  AvgCommunicate_134105_Content_11 = {
    Text = "Evet, vatanım güzeldi... Bu yüzden onu geri almaktan vazgeçmeyeceğim."
  },
  AvgCommunicate_134105_Content_12 = {
    Text = "Daha fazla Güç, daha fazla umut demek. Deniz fenerine daha fazla pervane çekeceğim..."
  },
  AvgCommunicate_134105_Content_13 = {
    Text = "Bir gün vatanım okyanus tabanından yeniden yükselecek ve beni bir kez daha karşılamak için kollarını açacak."
  },
  AvgCommunicate_134105_Content_14 = {
    Text = "Yani hâlâ o tür şeyler yapacaksın! Onca üzüntü boşunaymış—hemen dur!!!"
  },
  AvgCommunicate_134105_Content_2 = {
    Text = "Yurduma giden Yol… ne zaman tekrar bulunacak…"
  },
  AvgCommunicate_134105_Content_3 = {
    Text = "Faros… Of, şu an nasıl hissettiğini anlıyorum demek sadece Boşluk bir teselli olur. Sen… lütfen çok üzülme."
  },
  AvgCommunicate_134105_Content_4 = {
    Text = "Keder… Yurda duyulan özlemin kederi ruhuma kazınmış bir damga oldu. Onunla bir arada yaşamaya alıştım."
  },
  AvgCommunicate_134105_Content_5 = {
    Text = "Bitmeyen özlem acı getirir, ama aynı zamanda yurdumun görüntüsünü sonsuza dek hatırlamamı da sağlar."
  },
  AvgCommunicate_134105_Content_6 = {
    Text = "O mercanlarla kaplı sığ sular, o yükselen tapınak ve sık sık nöbet tuttuğum o yüce Kapı…"
  },
  AvgCommunicate_134105_Content_7 = {
    Text = "O taş sütunların kenarlarına oyulmuş desenleri kaydettim, kraliyet başkentindeki her geniş yolu kaydettim, insanların Dualarını sunarken yüzlerindeki dindar mutluluk İfadelerini kaydettim."
  },
  AvgCommunicate_134105_Content_8 = {
    Text = "Büyük törenler düzenlendiğinde, tüm ulus kutlama yapardı. O zamanlar en yoğun ama en tatmin edici anlarımdı."
  },
  AvgCommunicate_134105_Content_9 = {
    Text = "Bir keresinde kraliyet alayının önünde Koruyucu olarak hizmet etme onuruna eriştim, halkın saygı dolu bakışlarında birlikte yıkandık, gurur ve şan hissettim... En çok özlediğim anlar bunlar."
  },
  AvgCommunicate_134105_Option_10 = {
    Text = "Güzel bir ülke olmalıydı."
  },
  AvgCommunicate_134105_Option_14 = {
    Text = "Yani hâlâ o tür şeyler yapacaksın!"
  },
  AvgCommunicate_134105_Option_3 = {Text = "Faros..."},
  AvgCommunicate_134106_Content_1 = {
    Text = "Şey, şey, Efendi..."
  },
  AvgCommunicate_134106_Content_10 = {
    Text = "Artık Lily, Jenkin, Aigis, Caraboo ve Aurita'yı hep birlikte yemekhaneye taşıyabilir!"
  },
  AvgCommunicate_134106_Content_11 = {
    Text = "Bu çok fazla!"
  },
  AvgCommunicate_134106_Content_12 = {
    Text = "Hı-hı! Teşekkür ederim Efendi, Lily'ye bu kadar çok verdiğin için!"
  },
  AvgCommunicate_134106_Content_14 = {
    Text = "Demek istediğim bu değildi, ama..."
  },
  AvgCommunicate_134106_Content_15 = {
    Text = "Lily mutlu olduktan sonra, gerisi önemli değil!"
  },
  AvgCommunicate_134106_Content_2 = {Text = "Hm?"},
  AvgCommunicate_134106_Content_3 = {
    Text = "Lily'yi övebilir misin?"
  },
  AvgCommunicate_134106_Content_4 = {
    Text = "Aferin sana, Lily. Övülmeye değer bir şey mi oldu?"
  },
  AvgCommunicate_134106_Content_5 = {
    Text = "Lily bir sürü Pustül kaldırdı!"
  },
  AvgCommunicate_134106_Content_6 = {
    Text = "Çok çok yukarı kaldırdı!"
  },
  AvgCommunicate_134106_Content_9 = {
    Text = "Bu Mutlak Aksiyom'un etkisi olmalı..."
  },
  AvgCommunicate_134107_Content_1 = {
    Text = "Mutlak Aksiyom'u kavradığımdan beri, önümdeki yol benim için çok daha net hâle geldi."
  },
  AvgCommunicate_134107_Content_10 = {
    Text = "Bir seyir rehberi olarak bu benim yerine getirmem gereken görevim."
  },
  AvgCommunicate_134107_Content_11 = {
    Text = "O konumda olan herkes muhtemelen aynı şeyi yapardı."
  },
  AvgCommunicate_134107_Content_12 = {
    Text = "Seyir işi görev ve sorumluluk duygusuyla yapılır, övgü kazanmak için değil."
  },
  AvgCommunicate_134107_Content_13 = {
    Text = "Lütfen o hediyeleri denizcilere geri gönderin."
  },
  AvgCommunicate_134107_Content_14 = {
    Text = "Bu aynı zamanda onların minnettarlığının bir ifadesi. Kabul et gitsin."
  },
  AvgCommunicate_134107_Content_15 = {
    Text = "Ayrıca, denizde açıklanamayan sarı bir ışık görürseniz, lütfen gemiyi ters Yol'a doğru yönlendirmek için elinizden geleni yapın."
  },
  AvgCommunicate_134107_Content_16 = {
    Text = "Nedenini sormayın. Akademi ilgili Köken ile en kısa sürede ilgilenecek…"
  },
  AvgCommunicate_134107_Content_2 = {
    Text = "Yol boyunca kaybolan sayısız ruh adına ve kendim adına, bana bahşettiğiniz Vahiy için bir kez daha en içten şükranlarımı sunuyorum."
  },
  AvgCommunicate_134107_Content_3 = {
    Text = "Bu kadar resmi olmana gerek yok. Hak ettiğin bir şeydi, Corposant."
  },
  AvgCommunicate_134107_Content_4 = {
    Text = "Hak ettiğim mi?"
  },
  AvgCommunicate_134107_Content_5 = {
    Text = "Evet, okul çeşitli kanallardan iletilen birkaç teşekkür mektubu aldı."
  },
  AvgCommunicate_134107_Content_6 = {
    Text = "Hepsi yolculukları sırasında kaybolmuş, ancak direğin üzerinde mavi-mor bir Deniz Işıltısı huzmesi fark etmişler."
  },
  AvgCommunicate_134107_Content_7 = {
    Text = "Deniz Işıltısı'nın rehberliğini takip ettikleri sürece en yakın limana ulaşabilmişler."
  },
  AvgCommunicate_134107_Content_8 = {
    Text = "Bu ışığa \"Azizin Işığı\" adını vermişler."
  },
  AvgCommunicate_134107_Content_9 = {
    Text = "Bunun dışında, şükran ifade eden pek çok hediye var, hepsi posta odasının girişinde yığılmış durumda."
  },
  AvgCommunicate_134107_Option_5 = {
    Text = "Mythag teşekkür mektupları aldı..."
  },
  AvgCommunicate_134108_Content_1 = {
    Text = "Bu kadar güzel bir şeyin vardı da daha önce çıkarmayı düşünmedin."
  },
  AvgCommunicate_134108_Content_10 = {
    Text = "Senin hiç beynin var mı, seni @2? Bir şakayı gerçekten ciddiye aldın!"
  },
  AvgCommunicate_134108_Content_11 = {
    Text = "Herkes benim soyum olsa, bu büyük kral onca bozuk alet ve garip genel kültür bilgisiyle ne yapacak? Yani, evet, anılar korunabilir falan da."
  },
  AvgCommunicate_134108_Content_12 = {
    Text = "Her gün Boş Kabukların önünde kendi kendime mi konuşmamı bekliyorsun? Asla."
  },
  AvgCommunicate_134108_Content_14 = {
    Text = "Tch, yine içimi okudun. Ne sıkıcı."
  },
  AvgCommunicate_134108_Content_15 = {
    Text = "Bunu yapmayacağına güveniyorum, Agrippa. Arada sırada yoldan çıksan bile, seni tekrar yola getirebileceğimden eminim."
  },
  AvgCommunicate_134108_Content_16 = {
    Text = "Çünkü sen bilge Labirentler Hanımefendisi'sin."
  },
  AvgCommunicate_134108_Content_17 = {
    Text = "Çünkü sen benim için önemli birisin."
  },
  AvgCommunicate_134108_Content_18 = {
    Text = "Iyyy! Ne biçim garip bir şey söylüyorsun birden? İğrenç, çok iğrenç, kulaklarım çürüyecek!"
  },
  AvgCommunicate_134108_Content_19 = {
    Text = "Peki, şimdilik kimseyi soyuma dönüştürmekten isteksizce vazgeçeceğim, o yüzden şu ödevi al götür!"
  },
  AvgCommunicate_134108_Content_2 = {
    Text = "Haha, bu yüce kraliçe artık tamamen özgür! Asil Boz Kurt, Mythag'da hükümdarlığına yeniden Başlayacak."
  },
  AvgCommunicate_134108_Content_3 = {
