  AvgCommunicate_134109_Content_12 = {
    Text = "Evet, bir anda kendimi çok ama çok fazla parçaya dağılmış hissettim; kıvrımlı borularda, dağınık eşyaların arasında, alçak mobilyaların altında koşturuyordum..."
  },
  AvgCommunicate_134109_Content_13 = {
