  },
  AvgCommunicate_134109_Content_14 = {
    Text = "Ve sonra—onları kontrol ederek her türlü şeyi kolayca çalabiliyordum!"
  },
  AvgCommunicate_134109_Content_15 = {
    Text = "O zamanlar böyle bir yeteneğim olsaydı, Batı Bölgesi'ndeki en büyük bankayı bile soyabilirdim! Hahaha, artık ülkedeki tüm hırsızların kralıyım... hayır, tüm dünyanın! Artık kimse beni durduramaz!"
  },
  AvgCommunicate_134109_Content_17 = {
