  },
  AvgCommunicate_134109_Content_3 = {
    Text = "İyi misin? Yine dalıp gittin mi?"
  },
  AvgCommunicate_134109_Content_4 = {
    Text = "Çok, çok uzun yürüdüm ve sonunda bir şey gördüm—bir ışık kıvılcımı, bir duman süzüntüsü gibi—ve sonra yavaşça Brown'a dönüştü! Küçük, yuvarlak gözleri o kapkaranlık boşlukta parlıyordu."
