  },
  AvgCommunicate_134109_Content_7 = {
    Text = "Evet. Onların sadece farelerden ibaret olmadığını hissettim. Ruhları varmış gibiydi, tıpkı sokaklarda tanıdığım çocuklar gibi. Yarıştık, iş birliği yaptık ve aynı zorlukları paylaştık, tıpkı fareler gibi sokaklarda koşuşturduk."
