  AvgCommunicate_134110_Content_14 = {Text = "Korkma."},
  AvgCommunicate_134110_Content_15 = {
    Text = "Ne dediğini anlayamıyorum, ama eğer dünyanın gerçekten Yıkım'a mahkûm bir günü varsa, en azından ben ve Mythag'daki Herkes, son ana kadar savaşacak ve direneceğiz."
  },
  AvgCommunicate_134110_Content_16 = {
