  },
  AvgCommunicate_134110_Content_3 = {
    Text = "Winkle! Uyan! Yine kabus mu görüyorsun?!"
  },
  AvgCommunicate_134110_Content_4 = {
    Text = "Hayır, hayır, daha fazla @2 insanın teknikleri, bilgisi, daha güçlü ruhlar, hiçbiri işe yaramıyor, hiçbiri! Hâlâ tekrar göç edemiyorum!"
  },
  AvgCommunicate_134110_Content_5 = {
