  },
  AvgCommunicate_134110_Content_6 = {
    Text = "Artık güçlenmek istemiyorum. Kaçmak istiyorum, olabildiğince uzağa. Ama tüm dünya siyahsa ve tüm ışık sahteyse, nereye gidebilirim ki..."
