  },
  AvgCommunicate_134110_Content_8 = {
    Text = "Öleceğim, öleceğim, yine öleceğim. Tekrar Deneyimlemek mi zorundayım? İstemiyorum, istemiyorum..."
  },
  AvgCommunicate_134110_Content_9 = {
