  AvgCommunicate_134111_Content_10 = {
    Text = "Castor, harika olduğunu biliyorum ve kanatların da harika. Nasıl desem..."
  },
  AvgCommunicate_134111_Content_12 = {
    Text = "Boş ver, anladım. Bununla birlikte, taşıma kapasitenin de artmış olması gerekir, değil mi?"
  },
  AvgCommunicate_134111_Content_13 = {
    Text = "Hmm, kabaca tahmin edersem, bir düzine kadar insanın ağırlığı sorun olmaz."
  },
  AvgCommunicate_134111_Content_14 = {
    Text = "Ancak kollarım o kadar çok insanı aynı anda taşıyabilecek kapasitede görünmüyor."
  },
  AvgCommunicate_134111_Content_15 = {
    Text = "Bir önerim var."
  },
  AvgCommunicate_134111_Content_16 = {
    Text = "Şöyle yapalım—sen kol gücünü geliştirmeye git, sonra ihtiyacımız olduğunda gökten inebilen bir hava aracımız olur!"
  },
  AvgCommunicate_134111_Content_17 = {
    Text = "Kol gücü mü? Bunun hava... aracıyla ne ilgisi var? Velinimetim, cehaletimi bağışlayın ama pek anlamadım."
  },
  AvgCommunicate_134111_Content_18 = {
    Text = "Bu önemli bir görev."
  },
  AvgCommunicate_134111_Content_19 = {
    Text = "Taşıma kapasitenin yeterli olduğu sürece, saha görevlerindeki hareketlilik ve tahliye hızı büyük ölçüde artacaktır. Castor, bu görevi üstlenmeye istekli misin?"
  },
  AvgCommunicate_134111_Content_2 = {
    Text = "İnananlar gerçekten de gökyüzünü kaplayan kanatları övmüşlerdir, ama biliyorum ki bir zamanlar sahip olduğum şey sıradan bir çift kanattan başka bir şey değildi."
  },
  AvgCommunicate_134111_Content_20 = {
    Text = "Elbette! Bu benim için bir onur olur, Velinimetim."
  },
  AvgCommunicate_134111_Content_21 = {
    Text = "Anlaştık o zaman. Hemen Erica'yı bulup özel bir taşıma sepeti yaptıracağım!"
  },
  AvgCommunicate_134111_Content_22 = {
    Text = "Kanatlarını bir başkasına vermeyi bir daha asla düşünmemelisin, kim olursa olsun."
  },
  AvgCommunicate_134111_Content_3 = {
    Text = "Siz kanatlılar kanat sahibi olmanın ne kadar pratik olduğunu bilmiyorsunuz... Çok kıskanıyorum..."
  },
  AvgCommunicate_134111_Content_4 = {
    Text = "Eğer kurtarıcım isterse, Fener Kilisesi'nin kanat nakli yöntemleri olduğunu belli belirsiz hatırlıyorum. Kanatlarımı sana gönüllü olarak verebilirim. Acıdan korkmuyorum."
  },
  AvgCommunicate_134111_Content_6 = {
    Text = "Hayır hayır hayır hayır, buna gerek yok. Senin üzerinde kalmaları daha iyi."
  },
  AvgCommunicate_134111_Content_7 = {
    Text = "Ah, kanatlarımı istemiyor musun, kurtarıcım? Artık oldukça etkileyici hale geldiler."
  },
  AvgCommunicate_134111_Content_8 = {
    Text = "Yasaları kavradıktan sonra, tüylerimin arasından geçen rüzgârın her hissi, dönen hava akımlarının her kuvveti—hepsi benim kontrolüm altında."
