  },
  AvgCommunicate_134111_Option_9 = {
    Text = "Etkileyici olup olmamaları önemli değil."
  },
  AvgCommunicate_134112_Content_1 = {
    Text = "Aman Tanrım, demek dünya senin gözünden böyle görünüyor."
  },
  AvgCommunicate_134112_Content_10 = {
    Text = "İnsanların gerçekten bu kadar çok İfadesi mi var? Görünüşe göre ben taş suratlı sayılırım."
  },
  AvgCommunicate_134112_Content_11 = {
    Text = "Sadece bu kadar değil, ağlarken gülmeyi, ağlarken kızgın olmayı, gülerken kızgın olmayı, gülerken korku duymayı da öğrendim..."
  },
  AvgCommunicate_134112_Content_12 = {
    Text = "Her İfadeyi birbiriyle birleştirdiğin sürece yeni bir duygu ortaya çıkıyor. Bu gidişle Casiah'ın insan duygularını tamamen öğrenmesi çok sürmez!"
  },
  AvgCommunicate_134112_Content_13 = {
    Text = "Görmek ister misin? İster misin? İnsanlığın çözülmemiş gizemi olan \"aşk\"ı bile—Casiah artık senin için sergileyebilir!"
  },
  AvgCommunicate_134112_Content_15 = {
    Text = "Hiçbir şeyi öğrenmediğin gibi, şu anki halin öncekinden bile daha az insana benziyor! Çok korkutucu, hemen dur!!!"
  },
  AvgCommunicate_134112_Content_2 = {Text = "Ne?"},
  AvgCommunicate_134112_Content_3 = {
