  },
  AvgCommunicate_134112_Content_4 = {
    Text = "Casiah gördü... birbirine binen sayısız küçük varlık ve hepsi aynı anda \"görüş\" alanında olan sayısız an."
  },
  AvgCommunicate_134112_Content_5 = {
    Text = "Kısacık bir an içinde sayısız insan ağlıyordu, sayısız başkası ise gülüyor, Öfkeyle kükreniyor, Korkuyla titriyordu…"
  },
  AvgCommunicate_134112_Content_6 = {
    Text = "Bazı insanların çok Sakin ifadeleri de vardı. O duyguya, Kayıtlarıma göre, mutluluk denmeliydi? Demek insan duyguları bu kadar çok, bu kadar ince farklılıklara sahipmiş…"
