  },
  AvgCommunicate_134112_Content_8 = {
    Text = "Hayır, Casiah sadece onların ifadelerini, hareketlerini ve duygularının renklerini görebiliyor."
  },
  AvgCommunicate_134112_Content_9 = {
    Text = "Ama Casiah taklit konusunda en iyisi! Tüm dünyadaki farklı gülen ve ağlayan yüzleri aynı anda gördükten sonra, Casiah artık senin için 21 çeşit gülümseme ve 36 çeşit ağlama İfadesi sergileyebilir!"
