  AvgCommunicate_134113_Content_11 = {
    Text = "Ayrıca, kulağa bu kadar değerli gelen bir şey pahalı olmalı, değil mi? Takasın bedeli ne?"
  },
  AvgCommunicate_134113_Content_12 = {
    Text = "Hmm... Sonuçta, geçiş yapmak için daha kullanışlı bir güç kazanmam senin sayende oldu."
  },
  AvgCommunicate_134113_Content_13 = {
    Text = "Sana özel bir indirim yapacağım. Fiyata gelince, lütfen ayrıntıları görüşmek için dükkânıma gel. Gelişini bekliyor olacağım."
  },
  AvgCommunicate_134113_Content_2 = {
