  },
  AvgCommunicate_134113_Content_3 = {
    Text = "Geri dönüşü bu kadar uzun beklemeyi gerektiren işler nadiren yaparım. Neyse ki, işlerin şu anki haline bakılırsa, bu çoktan Kesin Kazanç oldu."
  },
  AvgCommunicate_134113_Content_4 = {
