  AvgCommunicate_134113_Content_7 = {
    Text = "Hehe, belagat konusunda kesinlikle bir Tüccar Yeteneğin var."
  },
  AvgCommunicate_134113_Content_8 = {
    Text = "Bu arada, küçük dükkânıma son zamanlarda birkaç yeni ürün geldi. Oldukça nadir ve hepsini senin için saklıyordum."
  },
  AvgCommunicate_134113_Content_9 = {
    Text = "Kişinin Köken Gücü ile Rezonans kurmasını sağlayan bir küre, Dikizcilik yoluyla başka bir dünyanın görüntülerini gözetlemeyi sağlayan bir Yansıma Bakışı ve insanları itaatkârca boyun eğdiren bir tasma var."
  },
  AvgCommunicate_134113_Option_10 = {
    Text = "Bu giderek daha yanlış oluyor!"
