  AvgCommunicate_134114_Content_1 = {
    Text = "Ben… ateş oldum."
  },
  AvgCommunicate_134114_Content_10 = {
    Text = "Dünyada hâlâ tasvir edilmeye değer çok fazla güzellik var. Sanırım yaratım için daha fazla Kavrayış buldum."
  },
  AvgCommunicate_134114_Content_11 = {
    Text = "Bundan sonra ateş olacağım, daha saf ve daha doğal bir ritim getireceğim."
  },
  AvgCommunicate_134114_Content_2 = {
    Text = "Camgöbeği, dans eden ateş. Yanmak, Arındırma, Dans."
  },
  AvgCommunicate_134114_Content_3 = {
    Text = "Benim günahlarım ve başkalarının günahları ateşte Yanacak ve her şey temizlenecek."
