  AvgCommunicate_134114_Content_4 = {
    Text = "Liz… hâlâ o zamanki ateşi mi hatırlıyorsun?"
  },
  AvgCommunicate_134114_Content_5 = {
    Text = "Nefretim ateşte yavaş yavaş Yandı, ama başkaları adına o ateşi affetmeye hakkım yok."
  },
  AvgCommunicate_134114_Content_6 = {
    Text = "Hiç pişman olmadım ve o alevlerdeki yüzlerden de kaçmayacağım."
  },
  AvgCommunicate_134114_Content_7 = {
    Text = "Buraya geldikten sonra bana yeni bir hayat verdin. Artık büyük bir sahneye ihtiyacım yok, ama eğer sen Seyirci olursan, dans ederken yine mutluluk hissedeceğimi düşünüyorum."
  },
  AvgCommunicate_134114_Content_8 = {
