  AvgCommunicate_134114_Content_9 = {
    Text = "Mm, teşekkür ederim. Dansı bıraktıktan sonra sık sık pencerenin kenarında boş boş oturdum. Rüzgârı, çiçekleri, ağaçları, kuşları ve Kedileri gördüm—dans ritmiyle dolu pek çok canlı ve doğanın tamamı."
