  AvgCommunicate_134115_Content_12 = {
    Text = "Elbette, her şeyimi Tanrı Diyarının İnişi'ne adamaya devam edeceğim."
  },
  AvgCommunicate_134115_Content_13 = {
    Text = "Ama artık anlıyorum… Tanrı'nın Diyarı, sadece tamamen Varış ya da tamamen yok oluş gibi iki durumdan ibaret değil."
  },
  AvgCommunicate_134115_Content_14 = {
    Text = "Biz Tanrı Diyarının İnişi için dua ederken, Tanrı'nın Diyarı'nın bir parçası çoktan yanımıza gelmiş."
  },
  AvgCommunicate_134115_Content_15 = {
