  AvgCommunicate_134116_Content_3 = {
    Text = "Nasıl desem... Temelde, o sıradan zihinler benim için açık günlükler gibi—sıkıcı ve bir bakışta ortaya serili. Oldukça can sıkıcı, doğrusu."
