  AvgCommunicate_134181_Option_13 = {
    Text = "Ustalığın inanılmaz."
  },
  AvgCommunicate_134181_Option_17 = {
    Text = "Hayır, lütfen!!!"
  },
  AvgCommunicate_134181_Option_4 = {
    Text = "Ben duymadım."
  },
  AvgCommunicate_134181_Option_8 = {
    Text = "Heykele mi dönüştürüleceğim?"
  },
  AvgCommunicate_134187_Content_1 = {
    Text = "Küçük köpek yavrusu, son zamanlarda nasılsın?"
  },
  AvgCommunicate_134187_Content_10 = {
    Text = "Düşüncesizce davranma. Ne olursa olsun, Kara Havuz seni sıkı sıkıya hapsedecek."
  },
  AvgCommunicate_134187_Content_11 = {
    Text = "Bilginin bana ne tür bir Güç verebileceği hakkında hiçbir fikrin yok."
  },
  AvgCommunicate_134187_Content_12 = {
    Text = "Bu hediyeden çok memnun oldum. O halde, en sevgili Öğrencim, karşılığında sana bir Hediye vereceğim."
  },
  AvgCommunicate_134187_Content_13 = {Text = "...?"},
  AvgCommunicate_134187_Content_14 = {
    Text = "Tahmin et. Şimdi ne kadar ileri gidebileceğimi tahmin et."
  },
  AvgCommunicate_134187_Content_15 = {
    Text = "Kibirli kısıtlama önlemlerinin gerçekten işe yarayıp yaramayacağını tahmin et."
  },
  AvgCommunicate_134187_Content_16 = {
    Text = "Gözetlediğim Hakikat'in, şimdi bu Güç'ü elde ettiğime göre, Herkesin bilincine Yerleştirilip yerleştirilmeyeceğini tahmin et."
  },
  AvgCommunicate_134187_Content_17 = {
    Text = "Bu en önemli ödev, biliyorsun. Yakında, çok yakında, onu bizzat notlandırmaya geleceğim."
  },
  AvgCommunicate_134187_Content_2 = {
    Text = "Cüretin beni gerçekten şaşırtıyor — bu çapta bir hediye göndermeye gerçekten cesaret etmişsin."
  },
  AvgCommunicate_134187_Content_3 = {
    Text = "Nadir malzemelerin taşınması sırasında ciddi bir kaza olduğunu söylesem inanır mısın..."
  },
  AvgCommunicate_134187_Content_5 = {
    Text = "Beni küçümsüyorsun, Mythag'ı da küçümsüyorsun."
  },
  AvgCommunicate_134187_Content_6 = {
    Text = "Her Uyandırıcı'nın o sınıra dokunmasına izin vermeye hazırız, çünkü Semptom: Yıkım'ı önlemek için her yolu deneyeceğiz."
  },
  AvgCommunicate_134187_Content_7 = {
    Text = "Bu... o öğretmen Doll ile bizim ve senin aramızdaki en büyük fark. Semptom: Yıkım kaçınılmaz olsa bile, asla ona boyun eğmeyeceğiz."
  },
  AvgCommunicate_134187_Content_8 = {
    Text = "Ah, Mythag'ın eğitim sisteminin bu kadar aptal birini yetiştirebileceğini nasıl daha önce fark edemedim."
  },
  AvgCommunicate_134187_Content_9 = {
    Text = "Neyse ki, o kadar acınası derecede aptal ki, ona şefkat duymamak elde değil."
  },
  AvgCommunicate_134187_Option_13 = {Text = "...?"},
  AvgCommunicate_134187_Option_3 = {
    Text = "Bir kazaydı."
  },
  AvgCommunicate_134187_Option_5 = {
    Text = "Samimi niyetim bu."
  },
  AvgCommunicate_134188_Content_1 = {
    Text = "Kurallar, çok havalı! Bam—! Güm—! Kabum—!"
  },
  AvgCommunicate_134188_Content_11 = {
    Text = "Bu durumda, okulun onarım masrafları bu ay önemli ölçüde düşecektir..."
  },
  AvgCommunicate_134188_Content_12 = {
    Text = "Kötü ödev, belirdi, Vortice, ez geç!"
  },
  AvgCommunicate_134188_Content_13 = {
    Text = "Hayır, ödevi de düşman sayamazsın!"
  },
  AvgCommunicate_134188_Content_14 = {
    Text = "Vortice, Vortice?"
  },
  AvgCommunicate_134188_Content_16 = {
    Text = "Koruyucu, ben Nautila. İçiniz rahat olsun, Vortice kontrol altına alındı. Ödev ve sınıf güvende."
  },
  AvgCommunicate_134188_Content_17 = {
    Text = "Çok şükür..."
  },
  AvgCommunicate_134188_Content_18 = {
    Text = "Nautila, Mythag ve Vortice ve ben sana her zaman ihtiyaç duyacağız."
  },
  AvgCommunicate_134188_Content_2 = {
    Text = "Mythag Kuralları, Vortice Özel Baskısı'nın 1 Numaralı Kuralını hatırla: Hiçbir koşulda kimse Mythag'da herhangi birine ölümcül silah doğrultamaz."
  },
  AvgCommunicate_134188_Content_5 = {
    Text = "%player%, merak etme, Vortice, kontrol, yapabilir!"
  },
  AvgCommunicate_134188_Content_6 = {
    Text = "Vortice, kontrol, Moskstraumen."
  },
  AvgCommunicate_134188_Content_7 = {
    Text = "Vortice, arkadaş, sarılmalar."
  },
  AvgCommunicate_134188_Content_8 = {
    Text = "Vortice, düşman, bam—! güm—! kabum—!"
  },
  AvgCommunicate_134188_Option_2 = {
    Text = "Önce Güvenlik."
  },
  AvgCommunicate_134189_Content_1 = {
    Text = "Biz silah arkadaşıyız, bu yüzden teşekkür etmeyeceğim."
  },
  AvgCommunicate_134189_Content_2 = {
    Text = "Silahım en keskin haline bilendi—bir köle efendisinin boğazını bir anda kesecek kadar keskin."
  },
  AvgCommunicate_134189_Content_3 = {
    Text = "Direnişin anlamı, intikamın anlamı, savaşın anlamı—hâlâ durmaksızın düşünüyorum."
  },
  AvgCommunicate_134189_Content_4 = {
    Text = "Belki de hayatımın geri kalanında, artık ayakta duramayacağım güne kadar düşünmeye devam edeceğim."
  },
  AvgCommunicate_134189_Content_5 = {
    Text = "En azından artık kaybolmuş değilim."
  },
  AvgCommunicate_134189_Content_6 = {
    Text = "Silah arkadaşlarıma."
  },
  AvgCommunicate_134189_Content_7 = {
    Text = "Silah arkadaşlarıma. Beni özgür kılan ve devam etmem için Kararlı iradeyi veren sizdiniz."
  },
  AvgCommunicate_134189_Content_8 = {
    Text = "Bana ne zaman ihtiyacınız olursa, her zaman arkanızda olacağım, sizinle Birlikte Savaşacağım."
  },
  AvgCommunicate_134189_Content_9 = {
    Text = "Savaşmaya devam edelim — alınması gereken intikam için ve savaşın heyecanının kendisi için."
  },
  AvgCommunicate_134189_Option_6 = {
    Text = "Silah arkadaşlarına."
  },
  AvgCommunicate_134201_Content_1 = {
    Text = "Koruyucu, Akademik İşler Ofisi'ne bir talep gönderdim. Önümüzdeki üç gün eğitime katılmayacağım."
  },
  AvgCommunicate_134201_Content_10 = {
    Text = "Ama o sınırı aştığımda anladım."
  },
  AvgCommunicate_134201_Content_11 = {Text = "Ne?"},
  AvgCommunicate_134201_Content_13 = {
    Text = "Ben öncü birliğin kılıcıyım. Hep bu Yolda yürüdüğüm için hepinizle ve seninle tanışabildim."
  },
  AvgCommunicate_134201_Content_14 = {
    Text = "Arayışım asla yalnız olmamamı sağlıyor. Belki hiç varamayabiliriz, ama Sebat ettiğimiz sürece o ideal, adil dünyayı biraz daha yakına, biraz daha yakına getirebilirim."
  },
  AvgCommunicate_134201_Content_15 = {
    Text = "Bedenim kılıç olsun, ta ki Herkesin ışıkta yaşayabildiği ütopyaya ulaşana dek."
  },
  AvgCommunicate_134201_Content_16 = {
    Text = "Ne büyük bir vizyon, Eğitmen Alva! Seni koşulsuz destekleyeceğim!"
  },
  AvgCommunicate_134201_Content_17 = {
    Text = "Harika. O halde bu üç günü daha titiz ve zorlu bir eğitim programı geliştirmek için kullanacağım."
  },
  AvgCommunicate_134201_Content_18 = {
    Text = "İlk deneyen sen olacaksın. Merak etme, tüm eğitim boyunca sana eşlik edeceğim ve herkesle birlikte gelişeceğim."
  },
  AvgCommunicate_134201_Content_19 = {
    Text = "Dur, bence bunu biraz daha tartışabiliriz…"
  },
  AvgCommunicate_134201_Content_2 = {
    Text = "Malzemelerle ilgili bir sorun mu oldu? İyi misin? Yardıma ihtiyacın var mı?"
  },
  AvgCommunicate_134201_Content_3 = {
    Text = "Hayır, tam tersi. Her şey yolunda gitti. Daha öncekinden farklı bir atılım yaşadım."
  },
  AvgCommunicate_134201_Content_4 = {
    Text = "Pek anlamıyorum…"
  },
  AvgCommunicate_134201_Content_5 = {
    Text = "Ben… ordudan ayrıldıktan sonra çok uzun bir süre sürüklendim."
  },
  AvgCommunicate_134201_Content_6 = {
    Text = "Ne için savaşmam gerektiğini bilmiyordum. Takip edebildiğim tek şey, sonunda gerçekleştirebileceğimden bile emin olmadığım bir adalet duygusuydu."
  },
  AvgCommunicate_134201_Content_7 = {
    Text = "Zayıfların yanında, sesini çıkaramayanların yanında, haksızlığa uğrayanların yanında durmak istiyordum."
  },
  AvgCommunicate_134201_Content_8 = {
    Text = "Ama ne kadar güçlensem de her zaman Çaresiz kalacağım şeyler olacağını çok iyi biliyordum—tıpkı zaman geri sarılsa bile Aram'ın düşüşünü engelleyemeyeceğim gibi."
  },
  AvgCommunicate_134201_Content_9 = {
    Text = "Eğitmen Alva…"
  },
  AvgCommunicate_134201_Option_2 = {Text = "Ne oldu?"},
  AvgCommunicate_134202_Content_1 = {
    Text = "Bu kadar değerli bir şeyi bana emanet ettiğin için teşekkür ederim, %player%."
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "Sanırım bana, hafızada izler bırakmanın yanı sıra, dünyanın adımlarla da ölçülebileceğini söylüyor."
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "Eğer onları tutamıyorsam, o zaman ilerlemeye devam edeceğim, hep ileri. Dünya ve hepiniz benim yerime hatırlayacaksınız."
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "Ben bile heyecanlanmadan edemiyorum…"
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "En büyük kaşif, en inanılmaz usta tamirci olacağım. %player%, sana resmi olarak Daveti sunmak istiyorum."
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "Her şeyin çözüldüğü gün geldiğinde, lütfen benimle maceraya çık. Bu dünyada daha fazla değerli anı birlikte yaratalım."
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "Belki o gün çok uzakta, belki de yarın."
  },
  AvgCommunicate_134202_Content_16 = {
    Text = "Bu davet sonsuza kadar geçerli. Onu hatırlayacağım, söz veriyorum."
  },
  AvgCommunicate_134202_Content_2 = {
    Text = "Onları özümsemek için çok, çok uzun zaman harcadım... Şimdi kendimi yeniden bütün hissetmemi sağlıyorlar."
  },
  AvgCommunicate_134202_Content_3 = {
    Text = "Yani, artık bir şeyleri unutmayacak mısın?"
  },
  AvgCommunicate_134202_Content_4 = {
    Text = "Hmm, bir düşüneyim..."
  },
  AvgCommunicate_134202_Content_5 = {
    Text = "Haha, hâlâ bir şeyleri hatırlayamıyorum!"
  },
  AvgCommunicate_134202_Content_6 = {
    Text = "Bununla neden bu kadar gurur duyuyorsun!"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "Çünkü, hâlâ birçok şeyi unutsam da, geçmişte ve şimdi, %player% her zaman bana hatırlatmak ve hatırlamamı sağlamak için yanımda olacak."
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "Kim olduğumu, nerede olduğumu, ne yapmam gerektiğini—en çok güvendiğim insanlar bana söyleyecek."
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "Belki de bu yüzden, Mutlak Aksiyom'u kavradıktan sonra, hafızam düzelmemiş olsa da, tüm dünya gözlerimin önünde devasa bir harita gibi açılmış gibi hissediyorum."
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "Hafızan düzeldi mi?"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "Bir zamanlar Bilinmezliğin sevincini ancak Seyirci rolünü oynayarak yaşayabileceğime inanıyordum."
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "Tam olarak anlamıyorum… ama iyi bir şey olması gerekiyor gibi görünüyor?"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "O Kapı'dan ayrıldığımdan beri, karşılaştığım en büyük nimet bu."
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "Koruyucu, bu bana verdiğin sürpriz—asla öngöremeyeceğim bir sürpriz."
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "Kader, cömertçe verenleri asla yarı yolda bırakmaz."
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "İpliklerine dokunamam, ama sen Kader için savaştıkça, çıkrığım sonsuza dek senin için dönecek."
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "Bu duyguyu en son yaşadığımdan bu yana çok, çok uzun zaman geçti…"
  },
  AvgCommunicate_134208_Content_3 = {
    Text = "Nasıl hissettiriyor?"
  },
  AvgCommunicate_134208_Content_4 = {Text = "Yenilik."},
  AvgCommunicate_134208_Content_5 = {
    Text = "Tomurcukların sessizce açması, kâğıt üzerinde iç içe geçen kelimeler, Rüzgârda süzülen bulutlar…"
  },
  AvgCommunicate_134208_Content_6 = {
    Text = "Ve tabii ki insanlar—o uzanan kollar, o düşen gözyaşları, savaş davulları ya da yağmur damlaları gibi atan kalpler…"
  },
  AvgCommunicate_134208_Content_7 = {
    Text = "Eskisinden daha çok şey görüyorum, ama gözlerim bir zamanlar olduğundan daha aşağıda."
  },
  AvgCommunicate_134208_Content_8 = {
    Text = "Artık gökyüzünde oyalanmıyorlar, Koruyucu. Aşağı indiler, her sokağa, her yolcunun yanına düştüler."
  },
  AvgCommunicate_134208_Content_9 = {
    Text = "Artık bir rol oynamam gerekmiyor. Gerçekten bir birey olarak var olabiliyorum."
  },
  AvgCommunicate_134208_Option_10 = {
    Text = "Bu iyi bir şeye benziyor?"
  },
  AvgCommunicate_134208_Option_3 = {
    Text = "Nasıl hissettiriyor?"
  },
  AvgCommunicate_134242_Content_1 = {
    Text = "Ana istatistik, Krit. Oranı, Krit. Hasar, Anahtar Parıltısı Yenilenme Seviyesi veya Aliemus Dolum Seviyesi arasından rastgele seçilir."
  },
  AvgCommunicate_134245_Content_1 = {
    Text = "Çok değerli bir şey gibi görünüyor, Saya'ya vermek sorun olmaz mı?"
  },
  AvgCommunicate_134245_Content_12 = {
    Text = "Demek bu dünyanın da güzel bir yanı varmış, hafızamdaki dünyadan biraz farklı olsa da."
  },
  AvgCommunicate_134245_Content_13 = {
    Text = "Oluşum biçimini, işleyiş mantığını, Saya artık tamamen kavrayabildi."
  },
  AvgCommunicate_134245_Content_14 = {
    Text = "Dolayısıyla bu dünyayı hafızamdaki dünyaya yeniden yazmak, şimdiki ben için belki çok kolay olurdu."
  },
  AvgCommunicate_134245_Content_16 = {
    Text = "Şaka yaptığını bilsem de lütfen böyle bir şey yapma."
  },
  AvgCommunicate_134245_Content_17 = {Text = "..."},
  AvgCommunicate_134245_Content_18 = {
    Text = "Neden sustun, şaka yapıyordun değil mi? Böyle bir anda sessiz kalma!"
  },
  AvgCommunicate_134245_Content_19 = {
    Text = "Şey, az önce sadece bir süreliğine dışarı çıkıp herkesi yeni bir bakış açısıyla gözlemledim…"
  },
  AvgCommunicate_134245_Content_2 = {
    Text = "Saya'ya güveniyorum, o yüzden sorun olmaz."
  },
  AvgCommunicate_134245_Content_20 = {
    Text = "Tanıdığım ve Saya'ya nazikçe davranan herkes hâlâ hayattayken, böyle hissediyorum."
  },
  AvgCommunicate_134245_Content_21 = {
    Text = "Neyin yanlış olduğunu tam söyleyemiyorum ama nedense bir yerlerin yanlış olduğunu hissediyorum."
  },
  AvgCommunicate_134245_Content_22 = {
    Text = "Üstelik şu an yüzünde yine o muziplik yapmış gibi bakan ifade var!"
  },
  AvgCommunicate_134245_Content_23 = {
    Text = "Merak etme, bu dünyada herkesle iyi geçineceğiz."
  },
  AvgCommunicate_134245_Content_24 = {
    Text = "Hmm… ama Saya'nın hafızasındaki o dünya daha ilginç olabilir. Hep birlikte gidip bakalım mı? Şu an bunu yapabilmeliyiz!"
  },
  AvgCommunicate_134245_Content_25 = {
    Text = "Bu söz daha da ürkütücü!"
  },
  AvgCommunicate_134245_Content_3 = {
    Text = "Bu dünyayı daha iyi anlamana yardımcı olursa, \"Çözünme nasıl durdurulur\" araştırmasına da büyük katkı sağlayacaktır."
  },
  AvgCommunicate_134245_Content_4 = {
    Text = "Sonuçta öğrenme ve araştırma konusunda gerçekten çok güçlüsün…"
  },
  AvgCommunicate_134245_Content_5 = {
    Text = "Aslında bazı ikmal kazaları oldu… Ama şimdi pişman olmak için çok geç değil mi?"
  },
  AvgCommunicate_134245_Content_6 = {
    Text = "Ha? O zaman geri versek mi, biraz kararsız kaldım."
  },
  AvgCommunicate_134245_Content_7 = {
    Text = "Ha? Geri verebilir miyim?"
  },
  AvgCommunicate_134245_Content_8 = {
    Text = "Hmm, Saya düşünsün bir…"
  },
  AvgCommunicate_134245_Content_9 = {
    Text = "Cevap — hayır."
  },
  AvgCommunicate_134245_Option_2 = {
    Text = "Sorun değil."
  },
  AvgCommunicate_134245_Option_5 = {
    Text = "Bir kazaydı"
  },
  AvgCommunicate_134246_Content_1 = {
    Text = "Sevgili, en çok sevdiğim, en muhteşem hayırseverim~"
  },
  AvgCommunicate_134246_Content_10 = {
    Text = "Kontrol edeyim."
  },
  AvgCommunicate_134246_Content_11 = {
    Text = "Gnostik İndeks dalgalanma verilerini kontrol edeyim."
  },
  AvgCommunicate_134246_Content_12 = {
    Text = "Vay canına—Caraboo'muz bu sefer gerçekten yalan söylememiş."
  },
  AvgCommunicate_134246_Content_13 = {
    Text = "Heh heh, şimdi zavallı küçük Caraboo'ya inandın, değil mi?"
  },
  AvgCommunicate_134246_Content_14 = {
    Text = "Lütfen bana cömertçe yatırım yapmaya devam et—Böylece ileride sevgili hayırseverime yüz, bin kat kazanç sağlayabilirim!"
  },
  AvgCommunicate_134246_Content_15 = {
    Text = "Sadece sekiz tane daha—hayır, beş Aydınlanma Kırığı! Ve sizi yeniden büyülüyeceğim, söz veriyorum!"
  },
  AvgCommunicate_134246_Content_16 = {
    Text = "Bu imkânsız."
  },
  AvgCommunicate_134246_Content_17 = {
    Text = "Güzel deneme."
  },
  AvgCommunicate_134246_Content_18 = {
    Text = "Profesör Doll bana Uyandırıcı Aydınlanması üzerine yapılan araştırmaların zaten tavanına ulaştığını söyledi. Bir asır boyunca başka bir atılım olmayacak."
  },
  AvgCommunicate_134246_Content_19 = {
    Text = "Bir Uyandırıcı Mutlak Aksiyom'a ulaştığında, bir daha asla Ruh Dalgalanması ritüeline giremez."
  },
  AvgCommunicate_134246_Content_2 = {
    Text = "Bu sefer ne istiyorsun, birdenbire bu kadar yağ çekiyorsun?"
  },
  AvgCommunicate_134246_Content_21 = {
    Text = "Haha—Bir şeyleri yanlışlıkla karıştırmış olmalıyım!"
  },
  AvgCommunicate_134246_Content_22 = {
    Text = "Lütfen bu konuşmanın hafızanı altı mesaj geri sar. İyi günler~"
  },
  AvgCommunicate_134246_Content_3 = {
    Text = "Ay ay, ne diyorsun sen—beni sadece bir şey istediğinde ortaya çıkan biri mi sanıyorsun?"
  },
  AvgCommunicate_134246_Content_4 = {
    Text = "Zaten öylesin..."
  },
  AvgCommunicate_134246_Content_5 = {
    Text = "Hüngür hüngür ağlıyorum, kalbim kırıldı. Hayırseverim beni bu kadar yanlış anlıyor."
  },
  AvgCommunicate_134246_Content_6 = {
    Text = "Aslında bu sefer sana iyi bir haber getirmeye geldim!"
  },
  AvgCommunicate_134246_Content_7 = {
    Text = "Yatırımın karşılığını verdi—süper, süper harika sonuçlarla~"
  },
  AvgCommunicate_134246_Content_8 = {
    Text = "Bak? Bambaşka biri oldum. Yeniden doğdum, dönüştüm, tamamen farklı biri~"
  },
  AvgCommunicate_134246_Content_9 = {
    Text = "Gerçekten mi?"
  },
  AvgCommunicate_134246_Option_10 = {
    Text = "Kontrol edeyim."
  },
  AvgCommunicate_134246_Option_16 = {
    Text = "Bu imkânsız."
  },
  AvgCommunicate_134246_Option_17 = {
    Text = "Güzel deneme."
  },
  AvgCommunicate_134246_Option_9 = {
    Text = "Gerçekten mi?"
  },
  AvgCommunicate_134247_Content_1 = {
    Text = "Ana istatistik, Krit. Oranı, Krit. Hasar, Anahtar Parıltısı Yenilenme Seviyesi veya Aliemus Dolum Seviyesi arasından rastgele seçilir."
  },
  AvgCommunicate_134249_Content_1 = {
    Text = "Koruyucu..."
  },
  AvgCommunicate_134249_Content_10 = {
    Text = "Mmm… O his yine geldi. Birden sıcak bastı, susadım. Karnım, Karnımın içi,"
  },
  AvgCommunicate_134249_Content_11 = {
    Text = "Koruyucu, hasta mıyım? Karnım yumuşuyor, kalbim yumuşuyor, her şey yumuşuyor. Birbirinden ayırt edemiyorum, sanki eriyorum…"
  },
  AvgCommunicate_134249_Content_12 = {
    Text = "Derin nefes al, Leigh. Erimeyeceksin."
  },
  AvgCommunicate_134249_Content_13 = {
    Text = "Bu, yakın ilişkilerde normal bir insan tepkisidir. İlaca gerek yok… ve kırbaca da gerek yok!"
  },
  AvgCommunicate_134249_Content_14 = {
    Text = "Ha? Kırbaç bile yok mu? Ne hayal kırıklığı."
  },
  AvgCommunicate_134249_Content_16 = {
    Text = "…Şey, gerçekten ihtiyacın varsa, belki git Pandia'ya sor…"
  },
  AvgCommunicate_134249_Content_17 = {Text = "Hehe..."},
  AvgCommunicate_134249_Content_18 = {
    Text = "Koruyucu, artık Kapının önünde çömelmemeye çalışacağım."
  },
  AvgCommunicate_134249_Content_19 = {
    Text = "Ama… geceleri ara sıra benim için bir Kapıyı açık bırakabilir misin? Bir pencere de olur."
  },
  AvgCommunicate_134249_Content_2 = {
    Text = "Ağabeyimin Caro'su ve bedenim eskisinden daha uyumlu. Derimin altında sessizce nefes alıyorlar, artık sürekli beni parçalamak için çığlık atmıyorlar."
  },
  AvgCommunicate_134249_Content_20 = {
    Text = "İçeri girmeyeceğim. Sadece her an sana ulaşan bir Yol olduğunu bilmek, daha huzurlu uyumama yardımcı olur."
  },
  AvgCommunicate_134249_Content_3 = {
    Text = "Kan isteği de eskisi kadar acı vermiyor. Önceden boğazıma takılmış bir şey gibiydi—içmezsem Boğulma. Şimdi sanki… beni biraz beklemeye razı."
  },
  AvgCommunicate_134249_Content_4 = {
    Text = "Bu gerçekten güzel bir haber."
  },
  AvgCommunicate_134249_Content_5 = {
    Text = "Okuldaki geceler çok sessiz. Çeşme hafifçe şırıldıyor."
  },
  AvgCommunicate_134249_Content_6 = {
    Text = "Koruyucu, bana çok fazla hazine verdin. Gerçekten hak ediyor muyum?"
  },
  AvgCommunicate_134249_Content_7 = {
    Text = "Elbette ediyorsun."
  },
  AvgCommunicate_134249_Content_8 = {
    Text = "…Her zaman çok çabuk cevap veriyorsun."
  },
  AvgCommunicate_134249_Content_9 = {
    Text = "Leigh, bize çok yardım ettin. Bu yapabileceğim en az şey."
  },
  AvgCommunicate_134250_Content_1 = {
    Text = "Vahşi bir hayvan büyütünce sonunun nasıl olacağını bilmiyor musun?"
  },
  AvgCommunicate_134250_Content_10 = {
    Text = "Sık sık merak ediyorum, gerçekten yüzeyde göründüğün gibi misin, yoksa…"
  },
  AvgCommunicate_134250_Content_11 = {
    Text = "Aslında başından beri, tıpkı o köle sahipleri gibi, rol mü yapıyorsun."
  },
  AvgCommunicate_134250_Content_12 = {
    Text = "Ne düşünüyorsun? Ne oyunculukta iyiyim, ne de yalan söylemekte."
  },
  AvgCommunicate_134250_Content_13 = {
    Text = "Kendi hislerini takip edebilirsin. Seni ikna etmeye çalışmayacağım, seni bir şey yapmaya da zorlamayacağım."
  },
  AvgCommunicate_134250_Content_14 = {
    Text = "Diğer senin bir zamanlar dediği gibi, biz arkadaşız—silah arkadaşlarıyız."
  },
  AvgCommunicate_134250_Content_15 = {
    Text = "Tch, beni o zayıfla bir tutma."
  },
  AvgCommunicate_134250_Content_16 = {
    Text = "İhanetten çoktan bıktım. Arkadaşlara hiç ihtiyacım yok."
  },
  AvgCommunicate_134250_Content_17 = {
    Text = "Ayrıca, senin vaatlerini de istemiyorum."
  },
  AvgCommunicate_134250_Content_18 = {
    Text = "Bana daha fazla Güç sağladığın sürece, bu yeterli."
  },
  AvgCommunicate_134250_Content_19 = {
    Text = "Ve karşılığında senin düşmanlarından intikamını alacağım."
  },
  AvgCommunicate_134250_Content_2 = {
    Text = "Büyümüş bir canavar zincirlerini koparır ve—hırrr—bakıcısının boğazını ısırır."
  },
  AvgCommunicate_134250_Content_20 = {
    Text = "Bana gerçekten ihanet ettiğin güne kadar… Dünyanın öbür ucuna bile kaçsan, peşinden gelip boğazını koparırım."
  },
  AvgCommunicate_134250_Content_3 = {
    Text = "Şu an, benimle olan Bağlantın gözümde demir zincirlerden daha Kırılgan görünüyor."
  },
  AvgCommunicate_134250_Content_4 = {
    Text = "Korkmuyor musun?"
  },
  AvgCommunicate_134250_Content_5 = {
    Text = "Sen özgürsün. Bağlantımız seni kısıtlamak için değil."
  },
  AvgCommunicate_134250_Content_6 = {
    Text = "Korkmam için hiçbir nedenim yok."
  },
  AvgCommunicate_134250_Content_7 = {Text = "..."},
  AvgCommunicate_134250_Content_8 = {
    Text = "Tch, tatlı sözler."
  },
  AvgCommunicate_134250_Content_9 = {
    Text = "Ama seni çok uzun zamandır izliyorum ve henüz bir Gedik anını Keşfedemedim."
  },
  AvgCommunicate_134250_Option_12 = {
    Text = "Ne düşünüyorsun?"
  },
  AvgCommunicate_134250_Option_5 = {
    Text = "Sen özgürsün"
  },
  AvgCommunicate_134263_Content_1 = {Text = "Koruyucu!!"},
  AvgCommunicate_134263_Content_10 = {
    Text = "Elbette. Güçleneceğinden hiç şüphem olmadı."
  },
  AvgCommunicate_134263_Content_11 = {Text = "..."},
  AvgCommunicate_134263_Content_12 = {
    Text = "Sen gerçekten garip birisin."
  },
  AvgCommunicate_134263_Content_13 = {
    Text = "Böyle bir anda, \"Gördün mü, seni seçerken gözüm doğru görmüş\" ya da \"Beklentilerimi gerçekten karşıladın\" gibi bir şey söylemen gerekmez mi?"
  },
  AvgCommunicate_134263_Content_14 = {
    Text = "Neden bu konuda bu kadar sakinsin?"
  },
  AvgCommunicate_134263_Content_16 = {
    Text = "Şey…bu kadar çok çalıştığın için güçlenmek gayet doğal. Söylenecek ne var ki?"
  },
  AvgCommunicate_134263_Content_17 = {
    Text = "Evvelki yıl geri ödediğin 50 lira ve geçen yılki 54 lira—hepsini sakladım."
  },
  AvgCommunicate_134263_Content_18 = {
    Text = "Neden saklıyorsun ki…harca gitsin."
  },
  AvgCommunicate_134263_Content_19 = {
    Text = "Boş ver, bırak onu. Önemli bir şey var."
  },
  AvgCommunicate_134263_Content_2 = {
    Text = "O desenler ısınıyor. Aequor'un Gücü derimin altında akıyor, öncekinden çok daha belirgin bir şekilde!"
  },
  AvgCommunicate_134263_Content_20 = {
    Text = "Hemen göle gel. Burada seni bekliyorum."
  },
  AvgCommunicate_134263_Content_21 = {Text = "Neyin var?"},
  AvgCommunicate_134263_Content_22 = {
    Text = "Gelince anlarsın."
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "Tamam…o zaman beni biraz bekle. Dışarıda şu an yağmur yağıyor. Önce yurda dönüp şemsiye almam lazım."
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "Oyalanma. Bundan sonrası için şemsiyeye ihtiyacımız olmayacak."
  },
  AvgCommunicate_134263_Content_25 = {
    Text = "Islanmazsın. Zar kanatlarım yeterince büyük."
  },
  AvgCommunicate_134263_Content_3 = {
    Text = "Bunun nasıl bir his olduğunu biliyor musun?!"
  },
  AvgCommunicate_134263_Content_4 = {
    Text = "Her neyse, inanılmaz derecede muhteşem, kelimelerle anlatılamaz. Siz insanlar muhtemelen bunu kavrayamazsınız."
  },
  AvgCommunicate_134263_Content_5 = {
    Text = "…Caecus, iyi misin?"
  },
  AvgCommunicate_134263_Content_6 = {
    Text = "Tabii ki iyiyim. Hiç bu kadar iyi olmamıştım."
  },
  AvgCommunicate_134263_Content_7 = {
    Text = "Sana çoktan söylemiştim, yatırımın boşa gitmeyecek diye. Kanım bana asla yalan söylemez."
  },
  AvgCommunicate_134263_Content_8 = {Text = "Biliyorum."},
  AvgCommunicate_134263_Content_9 = {
    Text = "…Hepsi bu mu?"
  },
  AvgCommunicate_134264_Content_1 = {
    Text = "Lütfen beni bağışla, Soluk Elçi. Buna yeterince hazırlıklı değildim ve seni biraz korkutmuş olabilirim."
  },
  AvgCommunicate_134264_Content_10 = {
    Text = "Bunu düşündüğüm sürece, kalbimdeki huzur bedenimin çektiği acıyı çok aşıyor."
  },
  AvgCommunicate_134264_Content_11 = {
    Text = "Anlıyorum. Belki benim böyle büyük ideallerin yok. Ama senin için olsa bile, arkadaşlarım için olsa bile."
  },
  AvgCommunicate_134264_Content_12 = {
    Text = "O ideal, huzurlu dünyaya ulaşabildiğim sürece, ne pahasına olursa olsun, elimden gelenin en iyisini yapacağım."
  },
  AvgCommunicate_134264_Content_13 = {
    Text = "Teşekkür ederim, Soluk Elçi."
  },
  AvgCommunicate_134264_Content_14 = {
    Text = "Tüm acılar Çözülme gününü bulsun ve sen ile ben her zaman yan yana yürüyelim."
  },
  AvgCommunicate_134264_Content_15 = {
    Text = "Ulu Peder'in koruması, senin değer verdiğin her şeyin üzerine de insin."
  },
  AvgCommunicate_134264_Content_2 = {
    Text = "Huh… İyi olduğuna sevindim. Yasaların kavranmasının bu tür bir Etki yaratacağını beklemiyordum."
  },
  AvgCommunicate_134264_Content_3 = {
    Text = "Benim için endişelenme. Bu dünyaya gelişimin asıl amacı bu görev."
  },
  AvgCommunicate_134264_Content_4 = {
    Text = "Zirveye giden eşiği aşmadan önce, Ulu Peder bu kavranılamaz sırları bana açmadan önce, kendimi çoktan bu Yola adamıştım."
  },
  AvgCommunicate_134264_Content_5 = {
    Text = "Tüm varlıkların acısını kendi üzerime toplayarak, her şeyi acının artık var olmadığı tertemiz bir diyara yönlendirmek— bu bir yük değil. Bu, Ulu Peder'in bana bahşettiği lütuf."
  },
  AvgCommunicate_134264_Content_6 = {
    Text = "Her zaman çok fazla yük taşıdığını hissettim. Başkalarının acısı Çözülüyor, ama bedeli…"
  },
  AvgCommunicate_134264_Content_7 = {
    Text = "Soluk alevim, sen şefkatli bir kalbe sahipsin."
  },
  AvgCommunicate_134264_Content_8 = {
    Text = "Ama için rahat olsun. Bedensel acı benim için Dikenlerin toprak için olduğu gibidir— ne kadar derine batarsa, o kadar sağlam Kök Salarım."
  },
  AvgCommunicate_134264_Content_9 = {
    Text = "Bu dünyada hâlâ acı çeken tek bir ruh bile varsa, asla yalnız acı çekmeyecek. Acı denizinden henüz kurtulamayan tek bir kişi bile varsa, onlardan önce asla karşı kıyıya ulaşmayacağım."
  },
  AvgCommunicate_134264_Option_11 = {Text = "Anlıyorum"},
  AvgCommunicate_134264_Option_6 = {Text = "Ama…"},
  AvgCommunicate_134265_Content_1 = {
    Text = "Haha, müthiş, kesinlikle müthiş!"
  },
  AvgCommunicate_134265_Content_10 = {
    Text = "Delikanlılarımdan herhangi birine sor— beni yıllardır tanırlar. Benim böyle bir şey yaptığımı ne zaman görmüşler!"
  },
  AvgCommunicate_134265_Content_11 = {
    Text = "Ah, artık Gücüm daha da şiddetli olduğuna göre, bir dahaki sefere seni yakmamaya dikkat etmeliyim."
  },
  AvgCommunicate_134265_Content_12 = {
    Text = "Ne... sen miydin? O zaman, kıyafetlerimin değiştirildiği zamanlar... o da sen miydin?"
  },
  AvgCommunicate_134265_Content_13 = {
    Text = "Evet, kıyafetlerin içki ve yemekten berbat olmuştu. Öyle yatağa girip yatmanı izleyemezdim."
  },
  AvgCommunicate_134265_Content_14 = {
    Text = "Teşekkür ederim, Kathigu-Ra."
  },
  AvgCommunicate_134265_Content_15 = {
    Text = "Ama bir dahaki sefere beni sallayarak uyandırsan olmaz mı..."
  },
  AvgCommunicate_134265_Content_16 = {
    Text = "Aa, utanıyor musun? Boş ver— bak ne kadar yakınız."
  },
  AvgCommunicate_134265_Content_17 = {
    Text = "Kıyafet değiştirmek gibi önemsiz bir şey bir yana—ateşin içinden geçmemi ya da kılıçtan bir dağa tırmanmamı istesen bile hiç sorun olmaz!"
  },
  AvgCommunicate_134265_Content_18 = {
    Text = "En kötü ihtimalle, bir dahaki sefere kıyafetlerimi değiştirmeme sen yardım edersin. Adil olur."
  },
  AvgCommunicate_134265_Content_19 = {
    Text = "…Bunun hiçbir tarafı mantıklı değil, o kadar mantıksız ki nasıl cevap vereceğimi bile bilmiyorum!"
  },
  AvgCommunicate_134265_Content_2 = {
    Text = "Böylesine eşi benzeri görülmemiş bir coşku hissi— şimdi, ben Güneş'im!"
  },
  AvgCommunicate_134265_Content_3 = {
    Text = "Küçük olan, senden giderek daha çok etkileniyorum."
  },
  AvgCommunicate_134265_Content_4 = {
    Text = "Bunu şimdi mi anlıyorsun? Daha gösterecek çok şeyim var."
  },
  AvgCommunicate_134265_Content_5 = {
    Text = "Oh? Görünüşe göre hepimizin sana küçük olan dememiz pek uygun olmamış."
  },
  AvgCommunicate_134265_Content_6 = {
    Text = "Hmm... bundan sonra sana büyük olan demeye başlamalıyım."
  },
  AvgCommunicate_134265_Content_7 = {
    Text = "Büyük olan mı? Bu nasıl bir isim! O düz suratınla yine benimle dalga geçiyorsun, değil mi?"
  },
  AvgCommunicate_134265_Content_8 = {
    Text = "Hahaha, elden ne gelir. Her içmeye gittiğimizde ilk sızıp kalan hep sen oluyorsun."
  },
  AvgCommunicate_134265_Content_9 = {
    Text = "Bu yüzden her seferinde seni yurda taşımak, ayakkabılarını çıkarmak, yorganını örtmek ve yüzünü silmek zorunda kalıyorum."
  },
  AvgCommunicate_134265_Option_12 = {
    Text = "Sen miydin?"
  },
  AvgCommunicate_134265_Option_7 = {Text = "?!"},
  AvgCommunicate_134267_Content_1 = {
    Text = "%player%, müziğim daha da mükemmel hale geldi."
  },
  AvgCommunicate_134267_Content_10 = {
    Text = "Müziğim hassas bir şekilde çalışan bir makine gibiydi ve bir zamanlar bana en seçkin orkestrada bir yer kazandırmıştı. Tabii ki bununla gurur duyuyordum."
  },
  AvgCommunicate_134267_Content_11 = {
    Text = "O farklıydı. Topluluk için uygun değildi. Müziği, Güneş ya da Ay gibi gökyüzünde tek başına parlamak için yaratılmıştı."
  },
  AvgCommunicate_134267_Content_12 = {
    Text = "Onu hep izledim, peşinden koştum. Sadece onunla iletişim kurma şansını çoktan sonsuza dek kaybetmiştim."
  },
  AvgCommunicate_134267_Content_13 = {
    Text = "Ama... nihai mükemmelliğe ulaşan bu performans, muhtemelen bir ömür süren arayışımın ardından sunabileceğim en iyi cevap."
  },
  AvgCommunicate_134267_Content_14 = {
    Text = "Çok dokunaklı... Nasıl böyle bir geçmişin olabilir? Parlak bir şekilde ışıldayan ve birbirlerinin ışığını yansıtan müzisyenlerin efsanevi hikâyesi gibi..."
  },
  AvgCommunicate_134267_Content_15 = {
    Text = "Hm, sadece son derece sıradan düşünceler. Gerçekten o kadar dramatik değil."
  },
  AvgCommunicate_134267_Content_16 = {
    Text = "Her ne olursa olsun, en çok söylemek istediğim şey, teşekkür ederim, %player%."
  },
  AvgCommunicate_134267_Content_17 = {
    Text = "Bundan sonra da senin için flütümü çalmaya devam etmeme izin ver, her gece seni huzurlu bir uykuya eşlik edeyim."
  },
  AvgCommunicate_134267_Content_2 = {
    Text = "Senin rehberliğin olmadan, muhtemelen bu son adımı asla atamazdım—bir zamanlar insan yeteneğinin düzeltemeyeceği küçük hataları kalibre etmek."
  },
  AvgCommunicate_134267_Content_3 = {
    Text = "Mükemmel ritim, kusursuz perde, her şey çok enfes duyuluyor..."
  },
  AvgCommunicate_134267_Content_4 = {
    Text = "Kesinlikle! Bu kadar hoş bir performans hiç duymamıştım!"
  },
  AvgCommunicate_134267_Content_5 = {
    Text = "Bu, müzik ile hesaplama, enstrüman ile beden, zihin ile kas arasındaki Rezonansın sonucu."
  },
  AvgCommunicate_134267_Content_6 = {
    Text = "Sonunda bu kuru ve sıkıcı Yolun sonunda böylesine mükemmel bir müziğin de var olabileceğini kanıtladım."
  },
  AvgCommunicate_134267_Content_7 = {
    Text = "De mi? Bununla ne demek istiyorsun?"
  },
  AvgCommunicate_134267_Content_8 = {
    Text = "Geçmişte, müziği en üst düzey duyarlılık ve yaratıcılığın ürünü olan Bir Arkadaşım vardı."
  },
  AvgCommunicate_134267_Content_9 = {
    Text = "Özgürce kullandığı yetenek, her performansta benzersiz besteler doğaçlamasına olanak tanıyordu."
  },
  AvgCommunicate_134267_Option_14 = {Text = "Vaaah..."},
  AvgCommunicate_134267_Option_4 = {
    Text = "Gerçekten Öyle"
  },
  AvgCommunicate_134267_Option_7 = {Text = "De mi?"},
  AvgCommunicate_134268_Content_1 = {
    Text = "En değerli konuğum, cömertliğinize nasıl teşekkür edebilirim ki?"
  },
  AvgCommunicate_134268_Content_10 = {
    Text = "Anlıyorum, anlıyorum. O bayağı kutlamaları istemiyorsunuz. Ben de size yakışmadığını düşünüyorum."
  },
  AvgCommunicate_134268_Content_11 = {
    Text = "Güzel bir fikrim var. Belki benimle birlikte Necrovia'nın ötesine çıkıp, sonuna yaklaşan birini karşılamaya eşlik etmek istersiniz?"
  },
  AvgCommunicate_134268_Content_12 = {
    Text = "Böyle bir onura nail olursak, umarım O'nu birlikte karşılar, O'nu son varış noktasına ve Yeniden Doğuş'a yönlendiririz. Ne dersiniz?"
  },
  AvgCommunicate_134268_Content_13 = {
    Text = "Sormak biraz zamansız olabilir ama... Sonuçta yine tüketimle ilgili olacağını tahmin ediyorum, çünkü Necrovia'nın geleneği bu."
  },
  AvgCommunicate_134268_Content_14 = {
    Text = "Hmm, bunu tüketim olarak tanımlamazdım. Zaten bildiğin hikayelerdeki gibi."
  },
  AvgCommunicate_134268_Content_15 = {
    Text = "Bu sadece en vakur, ama aynı zamanda en huzurlu vedadır."
  },
  AvgCommunicate_134268_Content_16 = {
    Text = "Katılmaktan memnuniyet duyarım, bazı kısımları atlamamıza izin verdiğin sürece..."
  },
  AvgCommunicate_134268_Content_17 = {
    Text = "Tabii ki, tabii ki."
  },
  AvgCommunicate_134268_Content_18 = {
    Text = "O halde, Necrovia'dan gelen araba ve ben yarın sabah Kapı'nın dışında gelişinizi bekliyor olacağız."
  },
  AvgCommunicate_134268_Content_2 = {
    Text = "Hediyeniz bana Necrovia'nın Koruyucusu olarak gerçekten ve kararlılıkla hizmet edecek Gücü bahşetti."
  },
  AvgCommunicate_134268_Content_3 = {
    Text = "Sıradan yemekler sunumunuza layık değil ve kişisel koleksiyonum da damak zevkinize pek uygun olmayabilir."
  },
  AvgCommunicate_134268_Content_4 = {
    Text = "Ne hoş bir ikilem bu böyle."
  },
  AvgCommunicate_134268_Content_5 = {
    Text = "Çok naziksiniz, Doresain."
  },
  AvgCommunicate_134268_Content_6 = {
    Text = "Birlikte çok şey yaşadık. Geçiş'in o sıkıcı formaliteleriyle uğraşmanıza gerçekten gerek yok."
  },
  AvgCommunicate_134268_Content_7 = {
    Text = "Hayır, hayır, bu kesinlikle basit bir formalite değil. Değerli bir dostla nasıl bir buluşma düzenleyeceğimi içtenlikle düşünüyorum."
  },
  AvgCommunicate_134268_Content_8 = {
    Text = "Necrovia'nın en olağanüstü Dansı'na zaten tanık oldunuz. Sizinle aramızdaki bağı nasıl daha da derinleştireceğimiz—işte asıl zorluk bu."
