  },
  AvgCommunicate_134269_Content_14 = {
    Text = "Sıcak avuçlarını tutmak, yumuşak tenine dokunmak istiyorum…"
  },
  AvgCommunicate_134269_Content_15 = {
    Text = "Ay ışığında seni kucaklamak istiyorum, tıpkı sözümüzü verdiğimiz gece gibi."
  },
  AvgCommunicate_134269_Content_16 = {
    Text = "Giderek artan Gücümle, seninle parça parça bütünleşerek ve senin tatlı özünün beni yavaş yavaş ısıtmasına izin vererek…"
  },
  AvgCommunicate_134269_Content_2 = {
    Text = "Bana verdiğin söz—ay ışığı altında ve kum denizinin ötesinde yaptığımız antlaşma—onu benim için yerine getirmeye çoktan başladın."
