  AvgCommunicate_134269_Content_3 = {
    Text = "Çok mutluyum."
  },
  AvgCommunicate_134269_Content_4 = {
    Text = "Herkesin huzur içinde yaşayabileceği bir dünya hâlâ çok uzakta olsa da, bunun için çabalamaya devam edeceğim."
  },
  AvgCommunicate_134269_Content_5 = {
    Text = "İlk tanıştığımız andan beri sana inandım."
  },
  AvgCommunicate_134269_Content_6 = {
