  },
  AvgCommunicate_134269_Content_7 = {
    Text = "Küçük fidanım, dünyaya ciddiyetle meydan okurken çok sevimli görünüyorsun."
  },
  AvgCommunicate_134269_Content_8 = {
    Text = "Sabırla, ciddiyetle bekleyeceğim— Bekleyeceğim, Bekleyeceğim... sözümüzün yerine geldiği günü."
