  AvgCommunicate_134270_Content_15 = {Text = "...Yani?"},
  AvgCommunicate_134270_Content_16 = {
    Text = "O zamana kadar, sadece senin düşmanlarını öldüreceğim."
  },
  AvgCommunicate_134270_Content_17 = {
    Text = "Yani hâlâ öldürmeye devam mı edeceksin?!"
