  AvgCommunicate_134270_Content_2 = {
    Text = "…? Ha? Ne dememem gerekiyor? Teşekkürler mi?"
  },
  AvgCommunicate_134270_Content_3 = {
    Text = "Roma'nın çöküşünden sonra bu dünya gerçekten sıkıcı oldu."
  },
  AvgCommunicate_134270_Content_4 = {
    Text = "Öldürme, öldürme, öldürme. Saf katliam ve Kan'dan başka bir şey yok. Roma olmadan geriye hiçbir şey kalmadı."
  },
  AvgCommunicate_134270_Content_5 = {
    Text = "Senin hediyenin beni o zincirlerden kurtardı. Şimdi bir iki kol, belki de bir boğaz koparacağım."
