  AvgCommunicate_134270_Content_6 = {
    Text = "Üzülerek söylüyorum Uvhash, ama modern çağda özel yetki olmadan insanları öldürmek yasalara aykırı."
  },
  AvgCommunicate_134270_Content_7 = {
