  AvgCommunicate_134271_Option_6 = {
    Text = "Her ne kadar"
  },
  AvgCommunicate_134272_Content_1 = {
    Text = "Efendim~ Karen borcunu nasıl ödesin? İçecekler, temizlik, yemekler—lütfen Karen'ı istediğiniz gibi çalıştırın!"
  },
  AvgCommunicate_134272_Content_10 = {
    Text = "Karen istediği sürece, Karen'ın cildi en pahalı mücevherlerden daha parlak bir şekilde ışıldayabilir ve en kusursuz incilerden daha göz kamaştırıcı bir şekilde parıldayabilir."
  },
  AvgCommunicate_134272_Content_11 = {
    Text = "Eğer Karen şimdi bir Baloya giderse, kesinlikle ilgi odağı olur, artık kimsenin umursamadığı o küçük hiç kimse olmaktan çıkar."
  },
  AvgCommunicate_134272_Content_12 = {
    Text = "Her ne kadar bunun Mutlak Aksiyom Güçlendirmesinin asıl amacı olduğunu düşünmesem de, ama..."
  },
  AvgCommunicate_134272_Content_13 = {
    Text = "Seni mutlu ettiği sürece, önemli olan tek şey bu."
  },
  AvgCommunicate_134272_Content_2 = {
    Text = "Önce yemeği listeden çıkaralım!"
  },
  AvgCommunicate_134272_Content_3 = {
    Text = "Aaa, ev işi becerilerim sorgulanıyor. Karen bunun için üzülmeli, ama, ama..."
  },
  AvgCommunicate_134272_Content_4 = {
    Text = "Bu kadar çok, bu kadar çok mücevher ve aksesuar! Karen kendini şimdiye kadarki en göz kamaştırıcı mücevher gibi hissediyor. Karen'ın üzülmesi gerçekten çok zor!"
