  AvgCommunicate_134272_Content_5 = {
    Text = "Önce biraz sakinleş. Ne dediğini artık zar zor anlıyorum."
  },
  AvgCommunicate_134272_Content_6 = {
    Text = "Özür dilerim, Karen çok heyecanlandı. Efendim Karen'ın o şeyi anlamasına yardım ettikten sonra... neydi o, bir saç tokası mı? Bir kurdele mi öyle bir şey..."
