  },
  AvgCommunicate_134276_Content_5 = {
    Text = "Hayır, hayır, hayır... Bu kadar sıradan, bayağı malzemelerle taklit edilemez. Daha çok düşün, daha çok düşünmeliyim..."
  },
  AvgCommunicate_134276_Content_6 = {
    Text = "Pickman? Sanki kendi sanatında çoktan kaybolmuş gibisin..."
  },
  AvgCommunicate_134276_Content_7 = {
    Text = "Şşş, sence evrenin gerçek rengi nasıl görünüyor? Senin gibi özel biri bana eşsiz bir Kavrayış bahşedebilir!"
  },
  AvgCommunicate_134276_Content_8 = {
    Text = "Bence dünya herkesin gözünden farklı görünüyor olabilir."
  },
  AvgCommunicate_134276_Content_9 = {
    Text = "Oh! Yani demek istediğin... kendi kalbimi takip etmem... duygularımı takip edip evrenin farklı renklerini boyamam..."
  },
  AvgCommunicate_134276_Option_10 = {Text = "Belki"},
  AvgCommunicate_134276_Option_8 = {Text = "Bence"},
  AvgCommunicate_134277_Content_1 = {
    Text = "Sır~ saklayan~ Koruyucu—"
  },
  AvgCommunicate_134277_Content_10 = {
    Text = "Sana acımayacağım, davranış mantığını küçümseyerek varsaymayacağım. Sadece bu dünyada eğlenmeni umuyorum."
  },
  AvgCommunicate_134277_Content_11 = {Text = "..."},
  AvgCommunicate_134277_Content_12 = {
    Text = "Vay canına, burada hangimiz daha deli? Böyle bir sebep için, bu seviyede bir Gücü benim gibi bir deliye mi teslim edeceksin?"
  },
  AvgCommunicate_134277_Content_13 = {
    Text = "Bu dünyaya gelişim gerçekten Kaderin bir düzenlemesi olabilir mi?"
  },
  AvgCommunicate_134277_Content_15 = {
    Text = "Her neyse, senin sayende sizin dünyanızda bana ait olan şeye dokundum—benim \"sınırıma.\""
  },
  AvgCommunicate_134277_Content_16 = {
    Text = "Şimdi, haydi çabuk bana bir görev ver! Birkaç kafa kesip sana neler yapabildiğimi göstermek için sabırsızlanıyorum~"
  },
  AvgCommunicate_134277_Content_2 = {
    Text = "Yabancı bir dünyada mahsur kalan bir kız, onu güçlendirebilecek pahalı bir hediye alıyor. Bunun kulağa neye benzediğini biliyor musun?"
  },
  AvgCommunicate_134277_Content_3 = {
    Text = "Normal insan düşünce süreçlerinden sapan bir şey söylemeden önce, şunu belirteyim—sen Mythag'ın bir üyesisin. Birbirimize yardım ederiz. Bu yüzden sana o malzemeleri verdim."
  },
  AvgCommunicate_134277_Content_4 = {
    Text = "Gerçekten mi? Sıkıcı, dolambaçlı, sosyalleşmiş insan sahne önü davranışlarından biri değil yani?"
  },
  AvgCommunicate_134277_Content_5 = {
    Text = "\"Evine gidemiyormuş, ne acınası, ona biraz daha ilgi gösterelim.\""
  },
  AvgCommunicate_134277_Content_6 = {
    Text = "\"Her şeyi tek başına çözmek çok zor olmalı, ona bir destek verelim.\" Gerçekten sıradan bir toplumda sıkça rastlanan bu tür sebeplerden biri değil mi?"
  },
  AvgCommunicate_134277_Content_7 = {
    Text = "Her şeyden önce, nereden bakarsan bak Mouchette, senin \"sıradan\" kelimesiyle hiçbir alakan yok!"
  },
  AvgCommunicate_134277_Content_8 = {
    Text = "Hmph☆hmph, işte bu oldukça hoşuma giden bir değerlendirme."
  },
  AvgCommunicate_134277_Content_9 = {
    Text = "İkincisi, öz algın ne olursa olsun ya da yüzeyde nasıl görünürsen görün, benim için, senin dediğin gibi, \"Mouchette\" \"Mouchette\"dir."
  },
  AvgCommunicate_134277_Option_7 = {
    Text = "Her şeyden önce"
  },
  AvgCommunicate_134278_Content_1 = {
    Text = "Teşekkür ederim, sevgilim. Bana çok fazla mutluluk getirdin ve hırsımı sonsuza dek korumamı sağladın."
  },
  AvgCommunicate_134278_Content_10 = {
    Text = "Hangi şekilde minnettarlık istersen, gerçekleştirebilirim."
  },
  AvgCommunicate_134278_Content_11 = {
    Text = "Henüz sahip olmasam bile, Yıldızlar ve Ay bile olsa, onları sana getirmenin bir yolunu bulurdum."
  },
  AvgCommunicate_134278_Content_12 = {
    Text = "İstediğim her şey mi? Gerçekten her şey mi?"
  },
  AvgCommunicate_134278_Content_13 = {
    Text = "Sözünde durmak, şöhret ve servet dünyasında vazgeçilmez bir geçiş belgesidir."
  },
  AvgCommunicate_134278_Content_14 = {
    Text = "O hâlde, Madam'ın bana bir söz vermesini istiyorum. Ayrıntılara gelince, biraz daha düşünmem gerekecek."
  },
  AvgCommunicate_134278_Content_15 = {Text = "..."},
  AvgCommunicate_134278_Content_16 = {
    Text = "Hahahaha, ne kurnaz bir tercih. Senden giderek daha çok hoşlanıyorum."
  },
  AvgCommunicate_134278_Content_17 = {
    Text = "Tabii ki, canım. Düşünmek için bolca zamanın var."
  },
  AvgCommunicate_134278_Content_18 = {
    Text = "Eğer vaktin varsa, bu gece malikâneme gelmeye ne dersin? Belki de sadece ikimiz olduğumuzda... ferahlatıcı bir \"güzel fikir\" bulmak senin için daha kolay olur."
  },
  AvgCommunicate_134278_Content_2 = {
    Text = "Size hizmet etmek benim için bir zevk, leydim."
  },
  AvgCommunicate_134278_Content_3 = {
    Text = "Hehe, anlayışlı, zeki, cesur, sadık, üstüne bir de tam kıvamında... güzellik."
  },
  AvgCommunicate_134278_Content_4 = {
    Text = "Kim senin mükemmel bir... olmadığını söyleyebilir ki?"
  },
  AvgCommunicate_134278_Content_5 = {
    Text = "...Mükemmel bir ne?"
  },
  AvgCommunicate_134278_Content_6 = {
    Text = "Biraz gergin görünüyorsun?"
  },
  AvgCommunicate_134278_Content_7 = {
    Text = "Leydim insanı her zaman sözsüz bırakır."
  },
  AvgCommunicate_134278_Content_8 = {
    Text = "Bazı şeylerin sözlerle ifade edilmesine gerek yok. Bunca zamandır hissettiklerini... hepsini aldım."
  },
  AvgCommunicate_134278_Content_9 = {
    Text = "Arazi, mülk, nadir hazineler, sanat eserleri ve pek çok yıldızla tanışma fırsatı... Şu anki gücümle hepsi ulaşılabilir mesafede."
  },
  AvgCommunicate_134278_Option_12 = {
    Text = "Gerçekten, her şey mi?"
  },
  AvgCommunicate_134278_Option_14 = {
    Text = "Sizden bir söz istiyorum, Madam."
  },
  AvgCommunicate_134278_Option_2 = {Text = "Zevkle"},
  AvgCommunicate_134278_Option_5 = {
    Text = "Mükemmel mi?"
  },
  AvgCommunicate_134278_Option_7 = {Text = "..."},
  AvgCommunicate_134279_Content_1 = {
    Text = "Koruyucu, hâlâ uyanık mısın?"
  },
  AvgCommunicate_134279_Content_10 = {
    Text = "Ama bana kattığın her şey… içimde yeni bir göl oluşturdu. O denizden bile daha engin bir göl."
  },
  AvgCommunicate_134279_Content_11 = {
    Text = "Bana şunu söyledi: artık korkmana gerek yok."
  },
  AvgCommunicate_134279_Content_12 = {
    Text = "Acının belki de asla tamamen Çözülmeyeceğini anlıyorum, ama kaç kez gerekirse gereksin, seni her zaman kıyıya geri çekeceğim."
  },
  AvgCommunicate_134279_Content_13 = {
    Text = "…Annem ve babam bunu söylediğini duysalardı, eminim içleri rahat ederdi."
  },
  AvgCommunicate_134279_Content_14 = {
    Text = "Sanırım… belki de o denizin bir yerinde, şimdiki halimi izliyorlardır."
  },
  AvgCommunicate_134279_Content_15 = {
    Text = "Bundan sonra, bana verilen bu Gücü kullanacak ve senin Koruyucun olarak hizmet eden gelgit olacağım."
  },
  AvgCommunicate_134279_Content_16 = {
    Text = "Belki… bir cesur isteğimi daha yerine getirmeyi kabul eder misin?"
  },
  AvgCommunicate_134279_Content_17 = {
    Text = "Nedir? Yapabileceğim bir şey olduğu sürece, memnuniyetle."
  },
  AvgCommunicate_134279_Content_18 = {
    Text = "Hava açtığında, lütfen benimle deniz kenarında bir yürüyüşe çık."
  },
  AvgCommunicate_134279_Content_19 = {
    Text = "Sana anlatmak istediğim çok şey var. Sadece bir öğleden sonra, hepsi bu."
  },
  AvgCommunicate_134279_Content_2 = {
    Text = "Dinlenmeni bölüyorsam özür dilerim…"
  },
  AvgCommunicate_134279_Content_20 = {
    Text = "Tabii ki, sorun değil. Söz veriyorum."
  },
  AvgCommunicate_134279_Content_3 = {
    Text = "Hayır, hâlâ ayaktayım. Ne oldu?"
  },
  AvgCommunicate_134279_Content_4 = {
    Text = "Hediyeni aldıktan sonra derin bir uykuya daldım ve bir Rüyaya sürüklendim. Daha önceki o okyanusu ve Sanatoryum'un dışındaki gün batımını rüyamda gördüm."
  },
  AvgCommunicate_134279_Content_5 = {
    Text = "Ama bu sefer… denize doğru yürümedim."
  },
  AvgCommunicate_134279_Content_6 = {
    Text = "Kıyıda durdum, o denize baktım. İçimi hâlâ bir huzurla dolduruyordu, ama ileri gitme arzum yoktu."
  },
  AvgCommunicate_134279_Content_7 = {
    Text = "Tahmin etmek küstahlık olmayacaksa—bu sefer kalman için bir nedenin olduğu için mi?"
  },
  AvgCommunicate_134279_Content_8 = {Text = "Elbette."},
  AvgCommunicate_134279_Content_9 = {
    Text = "Bir zamanlar acı altında ezildim. Boğazıma yerleşen o ağırlığı hiçbir şey yıkayıp götüremezdi—her şeyi silip süpüren ve kucaklayan Derin Deniz dışında hiçbir şey."
  },
  AvgCommunicate_134279_Option_12 = {
    Text = "Nymphaea…"
  },
  AvgCommunicate_134279_Option_17 = {Text = "Ne?"},
  AvgCommunicate_134279_Option_7 = {
    Text = "Çünkü..."
  },
  AvgCommunicate_134280_Content_1 = {
    Text = "%player%, dün gece yine o Rüyayı gördüm."
  },
  AvgCommunicate_134280_Content_10 = {
    Text = "Belki de Mutlak Aksiyom'un Etkisiydi."
  },
  AvgCommunicate_134280_Content_11 = {
    Text = "Evet, bu yüzden şunu söylemek istiyorum — tüm \"24\"ler adına, teşekkür ederiz, %player%."
  },
  AvgCommunicate_134280_Content_12 = {
    Text = "Birbirimizi duymamızı, birbirimizi görmemizi, birbirimizi anlamamızı ve birbirimizi kabul etmemizi sağladığın için teşekkür ederiz."
  },
  AvgCommunicate_134280_Content_13 = {
    Text = "Bu benim yaptığım bir şey değildi."
  },
  AvgCommunicate_134280_Content_14 = {
    Text = "Hayır, senin rehberliğin ve teselli tüm huzursuz ruhları yatıştırdı."
  },
  AvgCommunicate_134280_Content_15 = {
    Text = "Senin varlığın tüm nehirlerin bir araya akmasını sağladı."
  },
  AvgCommunicate_134280_Content_16 = {
    Text = "\"Ben\" — hepimiz — senin iyiliğini asla unutmayacağız."
  },
  AvgCommunicate_134280_Content_2 = {
    Text = "Uzak kuzeydeki karlı dağların eteklerine, kapkaranlık bir mağaranın içine dönmüş gibiydim."
  },
  AvgCommunicate_134280_Content_3 = {
    Text = "Sayısız balçık kütlesi, sayısız \"24\" gölgesi yansıtıyordu…"
  },
  AvgCommunicate_134280_Content_4 = {
    Text = "Onlar… hepsi sensin, hepsi senin bir parçan."
  },
  AvgCommunicate_134280_Content_5 = {Text = "Biliyorum."},
  AvgCommunicate_134280_Content_6 = {
    Text = "Kaos'un ortasında, birinin bana bir şey söylediğini duyar gibi oldum."
  },
  AvgCommunicate_134280_Content_7 = {
    Text = "Ses bulanıktı. Net bir şekilde seçemedim…"
  },
  AvgCommunicate_134280_Content_8 = {
    Text = "Ama o kişi ayrıldıktan sonra, etrafımdaki tüm gürültünün dinip sükunete kavuştuğunu hissettim."
  },
  AvgCommunicate_134280_Content_9 = {
    Text = "Kulaklarımdaki gürültülü fısıltılar uyumlu ve doğal bir hâl aldı, sanki ahenkli bir melodiymiş gibi…"
  },
  AvgCommunicate_134280_Option_4 = {
    Text = "Hepsi sensin."
  },
  AvgCommunicate_134281_Content_1 = {
    Text = "Koruyucu, Kadere inanır mısın?"
  },
  AvgCommunicate_134281_Content_10 = {
    Text = "...Sıradan bir insan olarak, bunun ne kadar harika hissettirdiğini zar zor hayal edebiliyorum. Dişlerimi sıkarak sormama izin ver — aslında nasıl bir his?"
  },
  AvgCommunicate_134281_Content_11 = {
    Text = "Nasıl tarif etmeliyim? Mesela, şu an biraz acıktım..."
  },
  AvgCommunicate_134281_Content_12 = {Text = "? Sonra?"},
  AvgCommunicate_134281_Content_13 = {
    Text = "Ah, beklettiğim için özür dilerim. Az önce kapı çalındı—Bayan Mason taze pişirmiş kek getirmiş."
  },
  AvgCommunicate_134281_Content_14 = {Text = "Ne???"},
  AvgCommunicate_134281_Content_15 = {
    Text = "Aynen böyle. Ve sonra... biraz susadım."
  },
  AvgCommunicate_134281_Content_16 = {
    Text = "Hm? Bay Doresain'in Uşağı az önce bir davetiye getirdi, yakındaki bir restoranda sakladığı kırmızı şarap koleksiyonunu tatmam için beni davet etmek istiyormuş."
  },
  AvgCommunicate_134281_Content_17 = {
    Text = "...Yeter. Bir dahaki sefere, içtenlikle ödevime yardım etmek istediğini hissedebilir misin?"
  },
  AvgCommunicate_134281_Content_18 = {
    Text = "Hahaha, emredersiniz, %player%. Artık benim en büyük hamim, sponsorum, iyi ortağım ve vazgeçilmez Watson'ımsın."
  },
  AvgCommunicate_134281_Content_19 = {
    Text = "Şanslı Dedektif, hizmetinizde olmaktan büyük mutluluk duyar."
  },
  AvgCommunicate_134281_Content_2 = {
    Text = "Ben Kadere inanıyorum ve tüm Kaderlerin en şanslısına sahip olduğuma inanıyorum."
  },
  AvgCommunicate_134281_Content_3 = {
    Text = "Beklenmedik sevinçler, beklenmedik kazançlar, gökten düşen nimetler — bunlar benim başıma geldiğinde artık gözümü bile kırpmıyorum."
  },
  AvgCommunicate_134281_Content_4 = {
    Text = "Kaderin lütfuna alıştığında, tüm hoş sürprizler sıradanlaşıyor."
  },
  AvgCommunicate_134281_Content_5 = {
    Text = "Az önce söylediğin şey gerçekten hem kıskanılacak hem de çıldırtıcı."
  },
  AvgCommunicate_134281_Content_6 = {
    Text = "Dur, daha sözümü bitirmedim. Seninle tanışmak tüm şanslarım arasındaki en büyük şans."
  },
  AvgCommunicate_134281_Content_7 = {
    Text = "Bana verdiklerin her zaman yeni sürprizler getiriyor."
  },
  AvgCommunicate_134281_Content_8 = {
    Text = "Tıpkı şimdi olduğu gibi — Mutlak Aksiyom'u kavradıktan sonra Beliren Güç, her bir şans anını daha gelmeden açıkça hissetmemi sağlıyor."
  },
  AvgCommunicate_134281_Content_9 = {
    Text = "Şanslı şeyler yağmur damlaları gibi düşüyor — hafif bir çiseden, vışş — şiddetli bir sağanağa dönüşüyor."
  },
  AvgCommunicate_134281_Option_10 = {
    Text = "Bu nasıl bir his?"
  },
  AvgCommunicate_134281_Option_14 = {Text = "???"},
  AvgCommunicate_134281_Option_5 = {
    Text = "Bu hem kıskanılacak hem de çıldırtıcı bir şey"
  },
  AvgCommunicate_137645_Content_1 = {Text = "Koruyucu."},
  AvgCommunicate_137645_Content_10 = {
    Text = "Ama o kadar bacakla, bir koşu yarışına katılman biraz haksızlık olmaz mı..."
  },
  AvgCommunicate_137645_Content_11 = {
    Text = "Castor'un kanatları var ve Nautila da aracını getirdi."
  },
  AvgCommunicate_137645_Content_12 = {
    Text = "Ben genellikle tiyatroda Dokuma yaparım ve sporda pek yetenekli değilim. Ama Hizmetçimi zaten kaydettirdim."
  },
  AvgCommunicate_137645_Content_13 = {
    Text = "Böyle bir şeyle neden ilgilendiğini hayal etmek zor?"
  },
  AvgCommunicate_137645_Content_14 = {
    Text = "İnsanların bir hedefe ulaşmak için canlı enerjilerini ve inatçı iradelerini ortaya koymasını izlemek gerçekten keyifli bir şey."
  },
  AvgCommunicate_137645_Content_15 = {
    Text = "Ve... ödül olarak sunulan o pastanın ne tür bir sihre sahip olduğunu merak ediyorum, Tawil'i bile bu kadar büyülemiş."
  },
  AvgCommunicate_137645_Content_16 = {
    Text = "Bir dünyayı yok edecek türden bir seçim olmadığı sürece, her şey olur..."
  },
  AvgCommunicate_137645_Content_17 = {
    Text = "Şey, yarışmanın sonuçlarını manipüle etmek için Kader İpliklerini kullanmazsın, değil mi?"
  },
  AvgCommunicate_137645_Content_18 = {
    Text = "...Arachne?"
  },
  AvgCommunicate_137645_Content_2 = {Text = "Neyin var?"},
  AvgCommunicate_137645_Content_20 = {
    Text = "Seyirci'de görüşürüz, Koruyucu."
  },
  AvgCommunicate_137645_Content_3 = {
    Text = "Sence... nasıl bir Kader adil ve doğru sayılabilir?"
  },
  AvgCommunicate_137645_Content_4 = {
    Text = "Adil ve doğru mu?... Muhtemelen çoğunluğun çıkarlarını mümkün olduğunca korumak."
  },
  AvgCommunicate_137645_Content_5 = {
    Text = "Peki ya azınlığın çıkarları Kurban edilmeye mahkûmsa? Kaderin böyle bir yönünü onaylıyorsun, doğru mu?"
  },
  AvgCommunicate_137645_Content_6 = {
    Text = "Sen... neden birdenbire bunu soruyorsun? Söylediklerimi yanlış anlama!"
  },
  AvgCommunicate_137645_Content_7 = {
    Text = "Eğer yine bir dünyayı yok etmek gibi bir şey yapmak üzereysen, lütfen bir kez daha düşün, Arachne!"
  },
  AvgCommunicate_137645_Content_8 = {
    Text = "Endişelenmeye gerek yok, Koruyucu. Sadece bir koşu yarışı."
  },
  AvgCommunicate_137645_Content_9 = {
    Text = "Huh... beni korkuttun..."
  },
  AvgCommunicate_137645_Option_2 = {Text = "Neyin var?"},
  AvgCommunicate_137646_Content_1 = {
    Text = "Koruyucu, bir soruşturma için uzaklara seyahat edeceğini öğrenince, özellikle senin için bir eser kaleme aldım."
  },
  AvgCommunicate_137646_Content_10 = {
    Text = "İsimlendirme anlayışın gerçekten bir başka, Arachne..."
  },
  AvgCommunicate_137646_Content_11 = {
    Text = "Eğrilen her ipliğin kaderinde yazılı bir sahibi vardır. Her hikâyenin de bir okuyucusu."
  },
  AvgCommunicate_137646_Content_12 = {
    Text = "Kolay yayılan bir isim, bu mükemmel hikâyelerin ulaşması gereken daha fazla insana ulaşmasına yardımcı olabilir."
  },
  AvgCommunicate_137646_Content_13 = {
    Text = "Örneğin, bu çok satan eser..."
  },
  AvgCommunicate_137646_Content_14 = {
    Text = "\"Aequor Yaratıkları Yemek Rehberi\"? Çok satan mı?"
  },
  AvgCommunicate_137646_Content_15 = {
    Text = "Yoksa Doresain, Necrovia'daki her bir kişiye birer kopya mı almış..."
  },
  AvgCommunicate_137646_Content_16 = {
    Text = "Tulu bundan haberdar mı?"
  },
  AvgCommunicate_137646_Content_18 = {
    Text = "İnsan kalbine ve Kadere dair bu keskin kavrayışınız, sizi gerçekten takdir etmeme neden oluyor."
  },
  AvgCommunicate_137646_Content_19 = {
    Text = "\"Herkes Koruyucu'yu Sever\"."
  },
  AvgCommunicate_137646_Content_2 = {
    Text = "Aslında senin için bir tiyatro oyunu hazırlamak istemiştim, ama taşınabilirliği düşünerek roman olarak yazdım."
  },
  AvgCommunicate_137646_Content_20 = {
    Text = "Lütfen bu eseri Yolculuğunuzun Başlangıcı'nda yanınıza alın."
  },
  AvgCommunicate_137646_Content_3 = {
    Text = "Bu da mı..."
  },
  AvgCommunicate_137646_Content_4 = {
    Text = "\"Büyük Koruyucu\"? \"Koruyucu'nun Destanı\"? \"Koruyucu'nun Dünyası\"?"
  },
  AvgCommunicate_137646_Content_5 = {
    Text = "Normalde ne yazıyorsun sen!? Bunları gerçekten okuyan var mı???"
  },
  AvgCommunicate_137646_Content_6 = {
    Text = "Mythag'daki popülariteni hafife alma. Bunların hepsi son derece popüler eserler."
  },
  AvgCommunicate_137646_Content_7 = {
    Text = "Bu kadar dramatik bir Kader, doğal olarak dünyaya sunulmayı hak eder."
  },
  AvgCommunicate_137646_Content_8 = {
    Text = "Aslında sadece sen değil. Başkalarının Kaderleri hakkında da hikâyeler ördüm."
  },
  AvgCommunicate_137646_Content_9 = {
    Text = "\"Savaş Alanında Beş Yıl, Üç Yıl Simülasyon\", \"Fareler İçin Doğum Sonrası Bakım\", \"Mum Damlatma Sanatı Büyük Sergisi\"..."
  },
  AvgCommunicate_137646_Option_3 = {
    Text = "Bu da mı..."
  },
  AvgCommunicate_137647_Content_1 = {
    Text = "Farklı zamanları ve mekânları görünmez ipliklerle birbirine bağlamak..."
  },
  AvgCommunicate_137647_Content_10 = {
    Text = "Sabırsızlanıyorum, Koruyucu."
  },
  AvgCommunicate_137647_Content_2 = {
    Text = "İnsan uygarlığı beni şaşırtmaktan asla vazgeçmiyor."
  },
  AvgCommunicate_137647_Content_3 = {
    Text = "Şaşırtmak mı?"
  },
  AvgCommunicate_137647_Content_4 = {
    Text = "Ama bu kaderler senin kendi ellerinle seçilmiyor mu?"
  },
  AvgCommunicate_137647_Content_5 = {
    Text = "Benim seçtiğim sadece yön. Tüm uygarlık ve tarih hâlâ sizin tarafınızdan yaratılıyor."
  },
  AvgCommunicate_137647_Content_6 = {
    Text = "Doğal olarak uzanan Kader İplikleri, nihayetinde yeni yaratımlara, bilinmeyen köklere Doğuş verecektir."
  },
  AvgCommunicate_137647_Content_7 = {
    Text = "Tüm bunlara Sessiz Tanık olarak, bu Dokumacılığın sevincini yaşayarak bu sorumluluğu taşımaya devam edebiliyorum."
  },
  AvgCommunicate_137647_Content_8 = {
    Text = "Anlıyorum..."
  },
  AvgCommunicate_137647_Content_9 = {
    Text = "Yeni yaratımlar olursa, lütfen bana da göster."
  },
  AvgCommunicate_137647_Option_3 = {
    Text = "Şaşırtmak mı?"
  },
  AvgCommunicate_140194_Content_1 = {
    Text = "Bir şeyler tuhaf hissettiriyor. Kimsenin benden hiç korkmaması..."
  },
  AvgCommunicate_140194_Content_10 = {
    Text = "Merak etme, herkes bana çok nazik davrandı! Güvendeler!"
  },
  AvgCommunicate_140194_Content_11 = {
    Text = "...Muhtemelen. Şimdilik."
  },
  AvgCommunicate_140194_Content_12 = {
    Text = "Şimdilik mi? ...Lütfen kesin olsun!"
  },
  AvgCommunicate_140194_Content_13 = {
    Text = "Şimdilik~!"
  },
  AvgCommunicate_140194_Content_2 = {
    Text = "Doll özel bir feromon geliştirdi. Şu anda herkesin gözüne sıradan bir insan kızı gibi görünüyorsun."
  },
  AvgCommunicate_140194_Content_4 = {
    Text = "Kullanışlı, sanırım, ama..."
  },
  AvgCommunicate_140194_Content_5 = {
    Text = "İnsanları artık korkutamayacak olmam biraz hayal kırıklığı mı yaratıyor?"
  },
  AvgCommunicate_140194_Content_6 = {Text = "...?"},
  AvgCommunicate_140194_Content_7 = {
    Text = "Nasıl desem... hmm... mesela, \"avlanmamı\" zorlaştıracak..."
  },
  AvgCommunicate_140194_Content_8 = {
    Text = "Son zamanlarda yemek bulmakta zorlanmıyordum, yani avlanmak acil bir ihtiyaç değil, ama... bazen... evet..."
  },
  AvgCommunicate_140194_Content_9 = {
    Text = "Artık Uyandırıcıların çeşitli çılgınca şeyler söylemesine neredeyse alıştım, ama yine de söylemeliyim... Bu çok tehlikeli bir söz!"
  },
  AvgCommunicate_140195_Content_1 = {
    Text = "Satın Alma Talebi"
  },
  AvgCommunicate_140195_Content_10 = {
    Text = "...Ve ben de bunların hiçbirinden haberdar değilmiş gibi davranacağım. Tamam mı?"
  },
  AvgCommunicate_140195_Content_2 = {
    Text = "Dört büyük ev tipi buzdolabı... Üniversite bütçesi tam olarak kısıtlı değil ama bu buzdolaplarını ne için istiyorsun?"
  },
  AvgCommunicate_140195_Content_3 = {
    Text = "Doğru hatırlıyorsam, Saya, taşındığın ilk gün zaten yurt odana bir tane konulmasını talep etmiştin."
  },
  AvgCommunicate_140195_Content_4 = {
    Text = "Şey, yani... Buzdolabı alanının ne zaman işe yarayacağını bilemezsin ki..."
  },
  AvgCommunicate_140195_Content_5 = {
    Text = "Ayrıca, bilirsin, etin tazeliği önemlidir..."
  },
  AvgCommunicate_140195_Content_6 = {Text = "..."},
  AvgCommunicate_140195_Content_7 = {
    Text = "Üzgünüm ama daha fazla buzdolabını onaylayamam. Ancak Xu ve Doresain'in iletişim bilgilerini sana ileteceğim."
  },
  AvgCommunicate_140195_Content_9 = {
    Text = "Onlarla yemek ve tarifler hakkında sohbet etmekten keyif alacağını düşünüyorum."
  },
  AvgCommunicate_140196_Content_1 = {Text = "¥%&#...%"},
  AvgCommunicate_140196_Content_10 = {Text = "..."},
  AvgCommunicate_140196_Content_11 = {
    Text = "Yanlış! Splish Splash demen gerekiyordu!"
  },
  AvgCommunicate_140196_Content_12 = {
    Text = "Görünüşe göre, Profesör Doll'un geliştirdiği feromon Bayan Vortice üzerinde işe yaramıyor."
  },
  AvgCommunicate_140196_Content_13 = {
    Text = "Ama yine de bana aynı şekilde davranıyor. Tavrı hiç değişmedi."
  },
  AvgCommunicate_140196_Content_14 = {
    Text = "Sanırım bunun sebebi, şey, nasıl desem..."
  },
  AvgCommunicate_140196_Content_15 = {
    Text = "...Belki de Vortice olağanüstü sosyal becerilere... doğuştan sahiptir?"
  },
  AvgCommunicate_140196_Content_2 = {
    Text = "A... Abandon. Ah, bir kelime daha öğrendim. Hmm."
  },
  AvgCommunicate_140196_Content_3 = {Text = "?"},
  AvgCommunicate_140196_Content_4 = {
    Text = "Son zamanlarda her türlü dil çalışıyorum. ...Büyüleyici."
  },
  AvgCommunicate_140196_Content_6 = {
    Text = "Standart Leonialı dilinin yanı sıra, bir sürü yeni kelime de öğrendim. Mesela..."
  },
  AvgCommunicate_140196_Content_7 = {
    Text = "Gurgle gurgle?"
  },
  AvgCommunicate_140196_Content_8 = {Text = "Tıp tıp!"},
  AvgCommunicate_140196_Content_9 = {Text = "Doğru!"},
  AvgCommunicate_140196_Option_10 = {Text = "..."},
  AvgCommunicate_140196_Option_8 = {Text = "Tıp tıp!"},
  AvgCommunicate_141374_Content_1 = {
    Text = "Resmi bir teşekkür belki biraz soğuk kaçar, ama yürekten söylüyorum, teşekkür ederim sana; hem kendim için, hem de tüm Ebwynnos için."
  },
  AvgCommunicate_141374_Content_10 = {
    Text = "Bu özellikleri sergiliyorum çünkü doğam böyle."
  },
  AvgCommunicate_141374_Content_12 = {
    Text = "Bu tür şeyleri bu kadar gururlu bir tonla söyleme."
  },
  AvgCommunicate_141374_Content_13 = {
    Text = "Dolayısıyla, o sınıra ulaşmama ve O'nun kontrolünden kurtulmama yardım etmen gerçekten büyük bir iyilik oldu."
  },
  AvgCommunicate_141374_Content_14 = {
    Text = "Daha önce yapması zor olan pek çok şey artık sorun olmaktan çıktı."
  },
  AvgCommunicate_141374_Content_15 = {
    Text = "Şimdi verdiğim şeyleri geri alabilir miyim hâlâ?"
  },
  AvgCommunicate_141374_Content_16 = {
    Text = "Sakin ol, Pontos; Londinium'un eksiksiz bir hukuk sistemi var!"
  },
  AvgCommunicate_141374_Content_2 = {
    Text = "Birden bu kadar ciddi olunca, gerçekten biraz alışılmadık geliyor."
  },
  AvgCommunicate_141374_Content_3 = {
    Text = "Bunun ne anlama geldiğini muhtemelen bilmiyorsun; ben yeterince güçlenmeden önce, Ebwynnos aslında o kadim varlığın kontrolünden hiçbir zaman kurtulamıyordu."
  },
  AvgCommunicate_141374_Content_4 = {
    Text = "Bu, O'nunla yaptığım bir anlaşmaydı; neyse ki O'nun kötü bir niyeti yoktu, hatta cömert bile sayılabilirdi."
  },
  AvgCommunicate_141374_Content_5 = {
    Text = "Ancak O, sonuçta insanlığa ait değil; O'nun denetimi altında Ebwynnos daha da öngörülemez olurdu, Ebwynnos'taki insanların da karakterleri daha uç noktalara kayardı."
  },
  AvgCommunicate_141374_Content_6 = {
    Text = "Öyleyse, sen daha önce de O'nun etkisiyle mi o kadar, hm…"
  },
  AvgCommunicate_141374_Content_7 = {
    Text = "Bir tahmin edeyim; Paranoya Pençesi, kin beslemek mi demek istedin, yoksa kontrolcü mü?"
  },
  AvgCommunicate_141374_Content_9 = {Text = "Hayır."},
  AvgCommunicate_141374_Option_2 = {
    Text = "Biraz alışılmadık"
  },
  AvgCommunicate_141374_Option_6 = {Text = "Yoksa"},
  AvgCommunicate_143429_Content_1 = {
    Text = "Bu sahte tanrılara tapan Tarikat Müridleri gülünç derecede aptal olsa da itiraf etmek gerekir ki, bazılarının zevki fena sayılmaz."
  },
  AvgCommunicate_143429_Content_10 = {
    Text = "Üstelik dönemleri bile tutmuyor ki!"
  },
  AvgCommunicate_143429_Content_11 = {
    Text = "Bence sen de böyle şeylerden daha fazla ilham alsan, hırsını artırsan, saha görevlerinde tehlikeye düşüp yardım isteme sayını önemli ölçüde azaltabilirsin."
  },
  AvgCommunicate_143429_Content_12 = {
    Text = "Tabii, bana birkaç kez daha dayı dersen, hırssız küçük çocukların arkasını toplamaktan her zaman memnuniyet duyarım."
  },
  AvgCommunicate_143429_Content_13 = {
    Text = "…Hemen gidip Golyat ile konuşacağım."
  },
  AvgCommunicate_143429_Content_14 = {
    Text = "Onları Mythag'ın yasaklı filmler listesine ekleyeceğim, öyle gelişigüzel öneri yapılmaz!"
  },
  AvgCommunicate_143429_Content_2 = {
    Text = "Birkaç gün önce Miryam'dan habersiz, sık sık Mythag'ı terk ettiğinde bile çok şaşırmıştım…"
  },
  AvgCommunicate_143429_Content_3 = {
    Text = "Bahsettiğin kişi Golyat değil mi…"
  },
  AvgCommunicate_143429_Content_4 = {
    Text = "Hmm, her şeyden önce, amacına ulaşmak için başkasının altında kalmayı göze almasındaki kararlılığına hayran kaldım."
  },
  AvgCommunicate_143429_Content_5 = {
    Text = "Bunun yanı sıra, önerdiği oyunlar gerçekten çok ilginçti."
  },
  AvgCommunicate_143429_Content_6 = {
    Text = "Golyat'ın tiyatroya gideceğini hayal etmek bile zordu."
  },
  AvgCommunicate_143429_Content_7 = {
    Text = "Bana <Italic:Leonia'da Bir Zamanlar> ve <Italic:Baba▼> filmlerini tavsiye etti—herkes onları çok sevdi."
  },
  AvgCommunicate_143429_Content_8 = {
    Text = "Bu gece Ebwynnos'ta \"Londinium'un Kurdu\" gösterime girecek."
  },
  AvgCommunicate_143429_Content_9 = {
    Text = "Hayır, dur bir dakika, Mythag'da çete liderlerine izin verilmiyor, kurt kültürü de yasak!"
  },
  AvgCommunicate_143429_Option_2 = {
    Text = "Kastettiğin yoksa"
  },
  AvgCommunicate_143430_Content_1 = {
    Text = "Bu ayın altıncı taşınma başvurusu; anlaşılan okul yönetimi yönetmelikleri her zaman işe yaramıyor."
  },
  AvgCommunicate_143430_Content_10 = {
    Text = "Ah, ne yazık."
  },
  AvgCommunicate_143430_Content_11 = {
    Text = "Haa?? Hey?! Neden bir kabus bir sınav cevap kâğıdı alıp oturup tezimi yazmaya başladı?"
  },
  AvgCommunicate_143430_Content_12 = {
    Text = "Omuzlarındaki yük çok ağır; şaka olarak bile böyle bir şey söylüyor olman, iyi bir şekilde Dinlen'men gerektiğini gösteriyor, küçük arkadaşım."
  },
  AvgCommunicate_143430_Content_13 = {
    Text = "Yalnızca bu sefer; çok istesem de çocuğunu şımartıp duran o tür bir ebeveyne dönüşmemeye çalışacağım."
  },
  AvgCommunicate_143430_Content_14 = {
    Text = "Şimdi, pencereyi aç; seni bir geceliğine dışarı götüreyim, Ebwynnos'a gitmeden de gerçeklikten uzaklaşmanın keyfini çıkar."
  },
  AvgCommunicate_143430_Content_15 = {
    Text = "…Yaşasın!"
  },
  AvgCommunicate_143430_Content_3 = {
    Text = "Not ortalaması, devam, etkin uygulama dönüşüm oranı ve… Koruyucular'da olmasa da sıradan Öğrencilerin büyük çoğunluğunda var olan iş bulma baskısı."
  },
  AvgCommunicate_143430_Content_4 = {
    Text = "Çözünme gözümüzün önünde olsa bile, gerçek hayatın sorunları yine de insanı dehşete düşürecek kadar korkunç."
  },
  AvgCommunicate_143430_Content_5 = {
    Text = "Herkesin gerçeklikten kaçmak istemesi normal, beni de Ebwynnos'a al yanına…"
  },
  AvgCommunicate_143430_Content_6 = {
    Text = "Ciddi misin?"
  },
  AvgCommunicate_143430_Content_7 = {
    Text = "Pencerenin dışından gerçekten kanat çırpma sesi mi geliyor, yoksa üç gece üst üste çalışmaktan Fantazma mı görüyorum?"
  },
  AvgCommunicate_143430_Content_8 = {
    Text = "Fırsatlar kaçırılmaz; böyle bir fırsat varken, ardından tüm Mythag başıma bela olsa bile kabul etmekten büyük memnuniyet duyarım."
  },
  AvgCommunicate_143430_Content_9 = {
    Text = "Hayır hayır hayır hayır hayır hayır şaka yapıyordum lütfen böyle bir şey yapma."
  },
  AvgCommunicate_143431_Content_1 = {
    Text = "Bir işin mi var benimle?"
  },
  AvgCommunicate_143431_Content_10 = {
    Text = "Hahahahaha, tamam, böyle bir İfade takınma."
  },
  AvgCommunicate_143431_Content_11 = {
    Text = "Onun özel mührünü ele geçirmek zor değil; hayır yemeğinin adresi için Ebwynnos'u ne dersin?"
  },
  AvgCommunicate_143431_Content_12 = {
    Text = "Bir sonraki adımda polis, özel mülke tecavüz gerekçesiyle hepimizi tutuklayacak."
  },
  AvgCommunicate_143431_Content_14 = {
    Text = "Pekâlâ, ne yazık ki, birkaç günlüğüne Kaçın'acağım."
  },
  AvgCommunicate_143431_Content_15 = {
    Text = "Savunmasız olduğu bir anda onu öldürmek belki daha eğlenceli olurdu."
  },
  AvgCommunicate_143431_Content_16 = {Text = "???!"},
  AvgCommunicate_143431_Content_2 = {
    Text = "Ee, Pontos, Ebwynnos'a gidip bir süre orada kalmayı düşünmez misin?"
  },
  AvgCommunicate_143431_Content_3 = {
    Text = "Profesör Dexter tam iki aydır Okulda görünmüyor."
  },
  AvgCommunicate_143431_Content_4 = {
    Text = "Ha, o korkak pis şey, şu an muhtemelen öfkeyle çılgına dönmüş, adamlarından birine bağırıp çağırıyordur."
  },
  AvgCommunicate_143431_Content_5 = {
    Text = "Merak etme, Köken'ine Dönüş yapmadan önce benim Rakibim olmaya hak kazanamaz."
  },
  AvgCommunicate_143431_Content_6 = {
    Text = "Sorun şu ki bir sürü belge onun mührünü bekliyor, bu yılki hayır yemeği ne olacak! Czort müdire ile Doll profesörü böyle bir şeye davet etmek, onlara Mythag'ı doğrudan havaya uçurtmaktan daha zor."
  },
  AvgCommunicate_143431_Content_7 = {
    Text = "Öğretmen Sylvia yönetirse, o zaman endişelenilecek başka şeyler olur…"
  },
  AvgCommunicate_143431_Content_8 = {
    Text = "Ne kadar üzücü, küçük arkadaşım. Biliyorum, Mythag'da seni koruyan pek çok insan var artık, bana ihtiyacın kalmadı. Oysa senin için bu kadar şey yaptım, hatta sen bile…"
  },
  AvgCommunicate_145234_Content_1 = {
