  AvgCommunicate_145234_Content_12 = {
    Text = "Elbette hayır."
  },
  AvgCommunicate_145234_Content_13 = {
    Text = "Artık vücudumu sakinleştirmek için dövüşe ihtiyacım yok, ama..."
  },
  AvgCommunicate_145234_Content_14 = {
    Text = "Şimdi gücümü daha özgürce kullanabilir ve istediğim herkese meydan okuyabilirim!"
  },
  AvgCommunicate_145234_Content_15 = {
    Text = "Sanırım... sana teşekkür borçluyum."
  },
  AvgCommunicate_145234_Content_16 = {
    Text = "Beni uzun zamandır özlem duyduğum bir zirveye taşıdın. Ama..."
  },
  AvgCommunicate_145234_Content_17 = {
    Text = "Gücün yolunun sonu yoktur. Değil mi, Koruyucu?"
  },
  AvgCommunicate_145234_Content_2 = {
    Text = "Sessizleşti mi? Ne demek istiyorsun?"
  },
  AvgCommunicate_145234_Content_3 = {
    Text = "Kanım kaynamayı bıraktı. Kemiklerim, ağrımayı bıraktı. Kılıcım artık kükremiyor..."
  },
  AvgCommunicate_145234_Content_4 = {
    Text = "Doğduğum andan bu yana, hiç durmamışlardı."
  },
  AvgCommunicate_145234_Content_5 = {
    Text = "Şimdi, hepsi sessiz."
  },
  AvgCommunicate_145234_Content_6 = {
    Text = "Bu kötü bir şey mi?"
  },
  AvgCommunicate_145234_Content_7 = {
    Text = "İyi misin?"
  },
  AvgCommunicate_145234_Content_8 = {
    Text = "Önceki gürültü—sadece bir açlıktı. Yeterince güçlü, yeterince hızlı olamamaktan gelen çılgın bir kaşıntı."
  },
  AvgCommunicate_145234_Content_9 = {
