  AvgCommunicate_146392_Content_2 = {Text = "?"},
  AvgCommunicate_146392_Content_3 = {
    Text = "Lotan? Bunlarla ilgilenmediğini sanıyordum."
  },
  AvgCommunicate_146392_Content_4 = {
    Text = "Sadece sıkıldım. Doll'un bana verdiği bu aleti deniyorum."
  },
  AvgCommunicate_146392_Content_5 = {
    Text = "Bir gün işe yarayabilir."
