  },
  AvgCommunicate_146393_Content_3 = {
    Text = "Bu bir tür \"ne istediğini tahmin et\" oyunu mu...?"
  },
  AvgCommunicate_146393_Content_4 = {
    Text = "Geçen sefer öldürdüğüm canavarı geri getirdim."
  },
  AvgCommunicate_146393_Content_5 = {
    Text = "Zaten koyacak yer yoktu, bir hatıra istersin diye düşündüm."
  },
  AvgCommunicate_146393_Content_6 = {
    Text = "Hiçbiri cazip gelmiyor..."
  },
  AvgCommunicate_146393_Content_7 = {
    Text = "Hepsini istemek tuhaf mı kaçar..."
  },
  AvgCommunicate_146393_Content_8 = {
    Text = "Zor karar... benim yerime sen seçsene..."
  },
  AvgCommunicate_146393_Content_9 = {
    Text = "Boynuz iyi. Kırılmadan önce üç darbeye dayanmış. Sana yakışıyor."
  },
  AvgCommunicate_146393_Option_6 = {
    Text = "Hiçbiri cazip gelmiyor..."
  },
  AvgCommunicate_146393_Option_7 = {
    Text = "Hepsini istemek tuhaf mı kaçar..."
  },
  AvgCommunicate_146394_Content_1 = {
    Text = "Bir sorunum var."
  },
  AvgCommunicate_146394_Content_10 = {
    Text = "Üç kez ayrıldım. Her seferinde kendilerini feda etmeye başladılar. Görünüşe göre bunu ilahi bir sınav olarak gördüler."
  },
  AvgCommunicate_146394_Content_11 = {
    Text = "Hepsi deli."
  },
  AvgCommunicate_146394_Content_12 = {
    Text = "Peki neden geri döndün ki??"
  },
  AvgCommunicate_146394_Content_13 = {
    Text = "Kılıcımı cesedinden çıkarmamıştım."
  },
  AvgCommunicate_146394_Content_14 = {
    Text = "Şimdi onu da kutsal emanet olarak koruyor altına aldılar."
  },
  AvgCommunicate_146394_Content_15 = {Text = "..."},
  AvgCommunicate_146394_Content_16 = {
    Text = "Kılıcımı, önümde toplu intihar etmelerine yol açmadan geri almam gerekiyor."
  },
  AvgCommunicate_146394_Content_17 = {
    Text = "Bu zayıf küçük yaratıkları benden daha iyi anlıyorsun. Bana yardım et."
  },
  AvgCommunicate_146394_Content_18 = {
    Text = "...Hey, bu ne demek oluyor?!"
  },
  AvgCommunicate_146394_Content_2 = {
    Text = "Vay canına, demek sen de bazen başın belaya giriyor!"
  },
  AvgCommunicate_146394_Content_3 = {
    Text = "Güçlü bir solucan varmış diye duydum, gidip öldürdüm."
  },
  AvgCommunicate_146394_Content_4 = {
    Text = "Öldükten sonra, uzun süredir onun altındaki gezegenin içinde mahsur kalan insanlar sürünerek dışarı çıktı."
  },
  AvgCommunicate_146394_Content_5 = {
    Text = "Bana tanrı dediler, önümde eğildiler, hatta benim için altın bir heykel diktiler—berbat görünümlü bir şey."
  },
  AvgCommunicate_146394_Content_6 = {Text = "HAHAHAHAHA"},
  AvgCommunicate_146394_Content_7 = {
    Text = "Gülmeyi bırak."
  },
  AvgCommunicate_146394_Content_8 = {
    Text = "Tapınılmaktan hoşlanmıyor musun?"
  },
  AvgCommunicate_146394_Content_9 = {
    Text = "Tapınılmaktan hoşlanmıyor musun?"
  },
  AvgCommunicate_146394_Option_6 = {Text = "HAHAHAHA"},
  AvgCommunicate_146394_Option_8 = {
    Text = "Neden sadece uzaklaşmadın?"
  },
  AvgCommunicate_146394_Option_9 = {
    Text = "Neden sadece uzaklaşmadın?"
  },
  AvgCommunicate_148438_Content_1 = {
    Text = "Sanırım zaten biliyorsun, hmm?"
  },
  AvgCommunicate_148438_Content_10 = {
    Text = "Hi hi, fazla düşünme~ Fazla düşünenler sıkıcı, eğlencesiz yetişkinlere dönüşür~"
  },
  AvgCommunicate_148438_Content_11 = {
    Text = "Tabii ki, eğer Koruyucu kendini Peri'ye çekilmekten alamıyorsa—gece gündüz her adımımı takip edip gerçek sevgimi kazanmaya çalışıyorsan—bunu gayet anlayışla karşılarım~"
  },
  AvgCommunicate_148438_Content_12 = {Text = "Ah..."},
  AvgCommunicate_148438_Content_13 = {
    Text = "En tatlı şeker elmasını zaten yurdundaki masanın üzerine bıraktım."
  },
  AvgCommunicate_148438_Content_14 = {
    Text = "Şimdi onu mutlaka, kesinlikle yavaş yavaş tatmalı, her ısırığını incelemeli ve tek başına keyifle yemelisin~"
  },
  AvgCommunicate_148438_Content_2 = {
    Text = "Yani tüm o zahmete girip çıkış izni aldın... sadece Aigis, Ogier ve Murphy'ye hiç tatmadıklarını söyledikleri sınırlı üretim şekerli elmalardan almak için mi?"
  },
  AvgCommunicate_148438_Content_3 = {
    Text = "O küçük serseri—öhöm—o dindar çocuklar üyelik aidatlarını tam ödememiş olabilir, ama Peri'nin bereketini dört bir yana yaymada son derece hayati bir rol oynuyorlar."
  },
  AvgCommunicate_148438_Content_4 = {
    Text = "Sürümü beslemek, böylece müjdeyi daha da istekle yaymaları için—bu, Peri'nin omuzlarında taşıdığı bir yük daha~"
  },
  AvgCommunicate_148438_Content_5 = {
    Text = "Bu sefer iyi bir gerekçen olsa bile, neden sürekli benim hesabıma yatırıyorsun bunu..."
  },
  AvgCommunicate_148438_Content_7 = {
    Text = "Oh, küçük ayrıntıları umursama~ Bak, çocuklar artık gerçek birer inançlı. Peki sen ne zaman onlara katılacaksın, hmm?"
  },
  AvgCommunicate_148438_Content_9 = {
    Text = "Gerçek benliğinin zaman zaman bir parçasını sızdırıp sızdırmadığını, yoksa gerçek amacını hep bir kat daha altında saklayan bir soğan mı olduğunu gerçekten anlayamıyorum..."
  },
  AvgCommunicate_148439_Content_1 = {Text = "[Görsel]"},
  AvgCommunicate_148439_Content_10 = {
    Text = "[Görüntü başarıyla yüklendi]"
  },
  AvgCommunicate_148439_Content_11 = {Text = "[Görsel]"},
  AvgCommunicate_148439_Content_12 = {
    Text = "Ne... gerçekten bir özür mektubu..."
  },
  AvgCommunicate_148439_Content_13 = {
    Text = "Özür dilerim... Caraboo. Sonunda bir kez samimi olduğunda böyle tepki vermemeliydim."
  },
  AvgCommunicate_148439_Content_14 = {
    Text = "Şu an yaptığım şikayeti hemen geri çekmeye gidiyorum. Seni eve hapsetmeni öneren... tüm dışarı çıkma taleplerini reddeden... İşte! Sana karşı yaptığım her şikayeti geri çektim."
  },
  AvgCommunicate_148439_Content_15 = {
    Text = "Harika~ Hı hı, Koruyucu—bir şikayet geri çekildiğinde, tam bir ay boyunca aynı Uyandırıcı hakkında yeni bir şikayet yapamayacağına inanıyorum, değil mi?"
  },
  AvgCommunicate_148439_Content_17 = {
    Text = "Bu konuda çok kötü bir his var içimde..."
  },
  AvgCommunicate_148439_Content_18 = {
    Text = "Ah canım, Peri hiçbir zaman %player%'ın samimi kalbini eğlence aracı yapacak kadar nezaketsiz olmaz~ O özür mektubundaki her kelime dürüst bir gerçekti. Gezintiden döndüğümde, sana en tatlı kırmızı elmayı getireceğime söz veriyorum~"
  },
  AvgCommunicate_148439_Content_19 = {
    Text = "Dur! Aigis neden az önce ağlayarak yanıma geldi ve ne yaptığını bilmese de özür mektubunu görünce onu affetmemi umduğunu söyledi?"
  },
  AvgCommunicate_148439_Content_2 = {
    Text = "Yükleniyor..."
  },
  AvgCommunicate_148439_Content_20 = {
    Text = "Ve senin onu iletmeye söz verdiğini—ama bana yeniden kızmaması için yüz yüze de özür dilemek istediğini?!"
  },
  AvgCommunicate_148439_Content_21 = {
    Text = "Hey, Caraboo. CARABOO!!"
  },
  AvgCommunicate_148439_Content_3 = {Text = "?"},
  AvgCommunicate_148439_Content_4 = {
    Text = "Caraboo, bu numarayı zaten bir kez yaptın. Ne dersen de, bu görseli AÇMIYORUM."
  },
  AvgCommunicate_148439_Content_5 = {
    Text = "Hayır, %player%... Gerçekten düşündüm. Sen ve Mythag'daki herkes bana çok iyi davrandı. Eski alışkanlıklarımı bu güzel yere taşımamam gerekirdi."
  },
  AvgCommunicate_148439_Content_6 = {
    Text = "Sonuçta, en başta kim olduğumu seçmedim."
  },
  AvgCommunicate_148439_Content_7 = {
    Text = "Bu yüzden oturdum ve sana düzgün bir özür mektubu yazdım—el yazısıyla, her bir kelimesini, kendi elimle~ Ama bir de ne görelim, tam bu anda İletişimci arıza yaptı..."
  },
  AvgCommunicate_148439_Content_8 = {
    Text = "İnanmasan da anlıyorum. Sadece... bekleyeceğim. Bana yeniden güvenmen ne kadar sürerse o kadar..."
  },
  AvgCommunicate_148439_Content_9 = {
    Text = "...Ah, neden vicdanım sızlıyor ki? Her neyse, asla..."
  },
  AvgCommunicate_148440_Content_1 = {Text = "[Görsel]"},
  AvgCommunicate_148440_Content_10 = {
    Text = "Ne diyorsun sen? Sanki sana geri ödeme yapacakmışım gibi!"
  },
  AvgCommunicate_148440_Content_11 = {Text = "Ha?"},
  AvgCommunicate_148440_Content_12 = {
    Text = "Artık numara bile yapmıyorsun?"
  },
  AvgCommunicate_148440_Content_13 = {
    Text = "Hehe. Peri'ye hizmet etmek başlı başına senin en büyük onurun. Seni eşsiz bir cennete götürecek. Buna kıyasla, dünyevi bir geri ödeme elbette söz etmeye bile değmez."
  },
  AvgCommunicate_148440_Content_14 = {
    Text = "Yeter artık bunlarla! Parayı çabucak havale etmezsen, harita sonsuza dek kaybolacak..."
  },
  AvgCommunicate_148440_Content_16 = {
    Text = "Bana gönderdiğin şeye zaten baktım. Açıkça berbat bir Gümüş teknolojisiyle sahte yapılmıştı..."
  },
  AvgCommunicate_148440_Content_17 = {
    Text = "Oh? Açtın mı? Bu tamamen senin kendi tercihindir, biliyorsun~ Harika! *Peri, %player%'ın sunusunu sonsuza dek hatırlayacak.*"
  },
  AvgCommunicate_148440_Content_18 = {
    Text = "Dur bir dakika, neden 1.000 Florin düşüldüğüne dair bir bildirim alıyorum—bu benim saha çalışması ödeneğim!"
  },
  AvgCommunicate_148440_Content_2 = {
    Text = "Yükleniyor..."
  },
  AvgCommunicate_148440_Content_20 = {
    Text = "Dur dur. Oldukça varlıklısın, değil mi? Bu sefer sadece 200 Florin alacağım—iletişim cihazındaki bilinmeyen bağlantıları açmaması gerektiği dersinin bedeli olarak. Peri'nin merhametine şükret, tamam mı?"
  },
  AvgCommunicate_148440_Content_21 = {
    Text = "[Transfer: 800 Leonian Florin]"
  },
  AvgCommunicate_148440_Content_3 = {
    Text = "[Görsel Bozuldu]"
  },
  AvgCommunicate_148440_Content_4 = {
    Text = "...Ne gönderdin?"
  },
  AvgCommunicate_148440_Content_5 = {Text = "Eyvah!"},
  AvgCommunicate_148440_Content_6 = {
    Text = "Mahvolduk! O görsel, sadık takipçilerimin kan, ter ve gözyaşıyla ele geçirilmiş Doğu'ya giden haritayı içeriyordu—ve şimdi asıl nüsha da onunla birlikte bozuldu! Bu, bizi Doğu'ya ulaşmaktan alıkoymaya çalışan kötü bir @2 olmalı!"
  },
  AvgCommunicate_148440_Content_7 = {
    Text = "%player%, yanında kaç Florin var? Çabuk, hepsini ver bana! Onu kurtarmanın hâlâ bir yolu olabilir..."
  },
  AvgCommunicate_148440_Content_8 = {
    Text = "Tahmin edeyim, Doğu'ya ulaştığında on katını geri ödeyeceksin. Ben dün doğmadım, biliyorsun."
  },
  AvgCommunicate_148440_Content_9 = {
    Text = "Zamanla ayak uyduramayan bir dolandırıcılığın geleceği yoktur."
  },
  AvgCommunicate_149803_Content_1 = {
    Text = "Akademinin daha önce bana verdiği koruma görevi tamamlandı. Efendim, benden yapmamı istediğiniz bir şey var mı?"
  },
  AvgCommunicate_149803_Content_10 = {
    Text = "Her neyse, eğer boş durmak istemiyorsan birkaç gün sonra okulda çok sayıda etkinlik var, biraz eğlenmek ister misin?"
  },
  AvgCommunicate_149803_Content_11 = {
    Text = "…Efendimin emri olduğuna göre itaat edeceğim."
  },
  AvgCommunicate_149803_Content_12 = {
    Text = "Şimdi devriyeye çıkıyorum."
  },
  AvgCommunicate_149803_Content_13 = {
    Text = "Umarım gerçekten itaat edersin!"
  },
  AvgCommunicate_149803_Content_2 = {
    Text = "Biraz dinlenmek istemez misin?"
  },
  AvgCommunicate_149803_Content_3 = {Text = "Gerek yok."},
  AvgCommunicate_149803_Content_4 = {
    Text = "Üstelik… böyle bir huzuru hak ettiğimi düşünmüyorum."
  },
  AvgCommunicate_149803_Content_5 = {
    Text = "O kara gölge hâlâ zaman zaman kulağımda beni rahatsız ediyor."
  },
  AvgCommunicate_149803_Content_6 = {
    Text = "Belki elim işte olduğunda daha sakin hissediyorum."
  },
  AvgCommunicate_149803_Content_7 = {
    Text = "Sadece bu kadar, Efendim endişelenmesin."
  },
  AvgCommunicate_149803_Content_8 = {
    Text = "Sanırım aylaklamanın gerekliliğini öğretmem gerekiyor."
  },
  AvgCommunicate_149803_Content_9 = {
    Text = "Daha iyi savaşmak için daha fazla dinlenmelisin."
  },
  AvgCommunicate_149803_Option_8 = {
    Text = "Sanırım aylaklamanın gerekliliğini öğretmem gerekiyor."
  },
  AvgCommunicate_149803_Option_9 = {
    Text = "Daha iyi savaşmak için daha fazla dinlenmelisin."
  },
  AvgCommunicate_149950_Content_10 = {
    Text = "Hüh...... Benimle alay mı ediyorsun? Bu beden üzerinde şu an kurabileceğim kontrolün sınırı bu kadar!"
  },
  AvgCommunicate_149950_Content_11 = {
    Text = "Ne yapmak istiyorsun? Onu kışkırtmaya, onu manipüle etmeye devam mı edeceksin?"
  },
  AvgCommunicate_149950_Content_12 = {
    Text = "Eğer yapabilseydim, çoktan......"
  },
  AvgCommunicate_149950_Content_13 = {
    Text = "Neyse, keskin bir bıçak olmak yerine kalkan ya da barikat olmak da fena sayılmaz......"
  },
  AvgCommunicate_149950_Content_14 = {
    Text = "Onun güvendiği ve hizmet ettiği efendisi olan sen ise, yakından tanıdıkça oldukça ilginç biri çıktın."
  },
  AvgCommunicate_149950_Content_15 = {
    Text = "Anladım, sen Ogier'in ters etkisine maruz kalmışsın."
  },
  AvgCommunicate_149950_Content_17 = {Text = "???"},
  AvgCommunicate_149950_Content_18 = {
    Text = "Efendim, çok özür dilerim. Az önce birkaç dakika aniden kendimden geçtim."
  },
  AvgCommunicate_149950_Content_19 = {
    Text = "Kendime gelince iletişim cihazının açık olduğunu gördüm."
  },
  AvgCommunicate_149950_Content_2 = {
    Text = "Sonunda seninle karşılaşabildim......"
  },
  AvgCommunicate_149950_Content_20 = {
    Text = "Sanki, az önce uzun süredir duymadığım o sinir bozucu sesi yeniden duydum......"
  },
  AvgCommunicate_149950_Content_21 = {
    Text = "Nasıl desem...... görünüşe göre sen ve içindeki o güç artık oldukça uyum içinde bir arada yaşayabiliyorsunuz."
  },
  AvgCommunicate_149950_Content_22 = {
    Text = "...... Kaydı okudum."
  },
  AvgCommunicate_149950_Content_23 = {
    Text = "O'nun eskisi gibi kötü, saldırgan sözler söyleyeceğinden endişeleniyordum."
  },
  AvgCommunicate_149950_Content_24 = {
    Text = "Gerçekten şaşırtıcı, bir zamanlar hep ben O'nun erozyonuna uğrardım, şimdi ise sanki tam tersi olmuş."
  },
  AvgCommunicate_149950_Content_25 = {
    Text = "Bu iyi bir şey olmalı. En azından... bu, O'nu tamamen yendiğimi kanıtlıyor."
  },
  AvgCommunicate_149950_Content_26 = {
    Text = "Tabii ki, Ogier'in gücünün artması sayesinde mi bu görünmez varlık üzerindeki hakimiyet bu seviyeye ulaşabildi?"
  },
  AvgCommunicate_149950_Content_27 = {
    Text = "Evet, öyle olmalı. Bu değişimlerin hepsi de sizin sayenizde gerçekleşti."
  },
  AvgCommunicate_149950_Content_28 = {
    Text = "Üstelik benim için kavradığım \"Nihai Yasa\" yalnızca bir güç değil......"
  },
  AvgCommunicate_149950_Content_29 = {
    Text = "Başkalarını koruma inancı da göğsümde her zamankinden daha tutkuyla yanıyor. Sanırım asıl köken de bu."
  },
  AvgCommunicate_149950_Content_3 = {
    Text = "Sen Ogier değilsin, sen kimsin?"
  },
  AvgCommunicate_149950_Content_4 = {
    Text = "İletişim cihazını hemen sahibine geri ver!"
  },
  AvgCommunicate_149950_Content_5 = {
    Text = "Gülünç, ben olmasaydım bu çocuk nasıl hayatta kalabilirdi ki, hem de Uyandırıcı kimliğiyle burada nasıl kalabilirdi?"
  },
  AvgCommunicate_149950_Content_6 = {
    Text = "Sen...... ona yapışmış olan o görünmez varlık mısın?"
  },
  AvgCommunicate_149950_Content_7 = {
    Text = "Aynen öyle. Mythag'ın Koruyucusu, beni tanımıyor musun."
  },
  AvgCommunicate_149950_Content_8 = {
    Text = "Ee...... Ogier tarafından sürekli bastırıldığın için seni hiç görmedim ki."
  },
  AvgCommunicate_149950_Option_3 = {
    Text = "Sen Ogier değilsin, sen kimsin?"
  },
  AvgCommunicate_149950_Option_4 = {
    Text = "İletişim cihazını hemen sahibine geri ver!"
  },
  AvgCommunicate_149986_Content_1 = {
    Text = "Efendim, size bir davet iletmek için geldim."
  },
  AvgCommunicate_149986_Content_10 = {
    Text = "...... Bir ağaç."
  },
  AvgCommunicate_149986_Content_11 = {Text = "Ha?"},
  AvgCommunicate_149986_Content_12 = {
    Text = "Belki de profesyonel eğitim aldığım için, ne kadar kaotik olursa olsun sahnede sağlam durabilirim."
  },
  AvgCommunicate_149986_Content_13 = {
    Text = "Oyununuzda tam olarak neler oluyor öyle!"
  },
  AvgCommunicate_149986_Content_14 = {
    Text = "Bilmiyorum, ben sadece bir ağacım."
  },
  AvgCommunicate_149986_Content_15 = {
    Text = "...... Pekâlâ, oyunda prensesi canlandıran Jenkin yukarıdan aşağıya ineceek, prensi canlandıran Lily ise onu tutacak."
  },
  AvgCommunicate_149986_Content_16 = {
    Text = "Kötü kralı canlandıran Aigis ise sahneden inip seyirciyle etkileşime geçecek."
  },
  AvgCommunicate_149986_Content_17 = {
    Text = "Bu rol dağılımını artık eleştirmek bile istemiyorum......"
  },
  AvgCommunicate_149986_Content_18 = {
    Text = "Ama bu spoiler sayılmaz mı?"
  },
  AvgCommunicate_149986_Content_19 = {
    Text = "Çünkü sizden bir şey gizlemek istemiyorum."
  },
  AvgCommunicate_149986_Content_2 = {
    Text = "Tiyatro topluluğu bir peri masalı oyunu sahneleyecek ve Mythag'daki reşit olmayan Uyandırıcıları birlikte oynamaya davet etti."
  },
  AvgCommunicate_149986_Content_20 = {
    Text = "Üstelik provalara bakılırsa her seferinde farklı bir aksilik yaşanıyor; efendimin gerçekte ne göreceğini de garanti edemem."
  },
  AvgCommunicate_149986_Content_21 = {
    Text = "...... O zaman gerçekten merak uyandırıcı."
  },
  AvgCommunicate_149986_Content_22 = {
    Text = "Oyundaki bu davranışların hepsi az ya da çok belirli bir tehlike barındırıyor."
  },
  AvgCommunicate_149986_Content_23 = {
    Text = "Bu yüzden, ağacı canlandırırken aynı zamanda sahne üzerindeki ve izleyici arasındaki durumu mümkün olduğunca takip etmem, oyuncuların ve seyircilerin güvenliğini sağlamam gerekiyor."
  },
  AvgCommunicate_149986_Content_24 = {
    Text = "Demek aslında yarı zamanlı koruma görevlisi olarak gittin... Kulağa çok yorucu geliyor."
  },
  AvgCommunicate_149986_Content_25 = {
    Text = "Evet. Her ne olursa olsun, lütfen endişelenmeyin. Ben sahnedeyken, kimsenin bir daha zarar görmesine izin vermeyeceğim."
  },
  AvgCommunicate_149986_Content_3 = {
    Text = "Söylemesi biraz zor ama... ben de sahneye çıkacağım. Umarım izlemeye gelirsiniz."
  },
  AvgCommunicate_149986_Content_4 = {
    Text = "! Çok merak ediyorum."
  },
  AvgCommunicate_149986_Content_5 = {
    Text = "Ama bu tür bir etkinliğe katılmayı kabul edeceğini hiç düşünmemiştim."
  },
  AvgCommunicate_149986_Content_6 = {
    Text = "Evet, ben artık çocuk değilim, bu yüzden içlerinde yer almam pek uygun değil."
  },
  AvgCommunicate_149986_Content_7 = {
    Text = "Ama onlar ısrar etti......"
  },
  AvgCommunicate_149986_Content_8 = {
    Text = "Keyflerini kaçırmak istemedim; üstelik bu rolü gerçekten yalnızca benim oynayabileceğimi fark ettim."
  },
  AvgCommunicate_149986_Content_9 = {
    Text = "Peki, Ogier hangi rolü oynayacak? Şövalye mi?"
  },
  AvgCommunicate_149987_Content_1 = {
    Text = "Efendim, son zamanlarda D-fenomen ile ilgili dersler var mı?"
  },
  AvgCommunicate_149987_Content_10 = {
    Text = "Ne kadar çalışkansın...... Ben de senin gibi gayretli olsaydım, sınavlar için hiç endişelenmezdim."
  },
  AvgCommunicate_149987_Content_11 = {
    Text = "Lütfen beni böyle övmeyin, sizin üstlendiğiniz sorumluluklar benimkinden çok daha ağır."
  },
  AvgCommunicate_149987_Content_12 = {
    Text = "Üstelik bu, günahlarımı ödemek için yapmam gereken zorunlu bir çalışma."
  },
  AvgCommunicate_149987_Content_13 = {
    Text = "Ama çok hızlı öğreniyorsun, kim bilir Ogier'in de akademisyen olma potansiyeli vardır."
  },
  AvgCommunicate_149987_Content_14 = {
    Text = "Herkesin çocukken düşündüğü gibi, gelecekle ilgili konular."
  },
  AvgCommunicate_149987_Content_15 = {
    Text = "Ogier büyüyünce ne yapmak istediğini hiç düşündü mü?"
  },
  AvgCommunicate_149987_Content_16 = {
    Text = "Biliyorsunuz, ben Uyandırıcı oldum; artık büyüyüp yetişkin olma ihtimalim yok."
  },
  AvgCommunicate_149987_Content_17 = {
    Text = "Yine de ilerideki planlarını hayal edebilirsin! Bu kadar karamsar olmana gerek yok."
  },
  AvgCommunicate_149987_Content_18 = {
    Text = "Ogier'in \"başkalarını korumak\" dışında yapmak istediği bir şey yok mu?"
  },
  AvgCommunicate_149987_Content_19 = {
    Text = "Teşvik ettiğiniz için teşekkür ederim."
  },
  AvgCommunicate_149987_Content_2 = {
    Text = "Daha derinlemesine öğrenmek istiyorum."
  },
  AvgCommunicate_149987_Content_20 = {
    Text = "Başka yapmak istediğim şeyler mi...... Özür dilerim, gerçekten aklıma gelmiyor."
  },
  AvgCommunicate_149987_Content_21 = {
    Text = "Bu beden günahlardan arındığında, o zaman düşünürüm."
  },
  AvgCommunicate_149987_Content_3 = {
    Text = "Var tabii, seni de götürürüm sonra."
  },
  AvgCommunicate_149987_Content_4 = {
    Text = "Ama Ogier neden bu konuları öğrenmek istedi birden?"
  },
  AvgCommunicate_149987_Content_5 = {
    Text = "Çünkü bugün biri bana, üzerimdeki gücün D-balçıkla ilgili olup olmadığını sordu."
  },
  AvgCommunicate_149987_Content_6 = {
    Text = "Öyle demek, sadece görünüşe bakılırsa gerçekten biraz benziyor."
  },
  AvgCommunicate_149987_Content_7 = {
    Text = "Evet, ben de bu görünmez şeyin özünü hep merak ettim; belki yeterince anlarsam O'nu daha iyi kontrol edebilirim."
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "Mythag'a geldikten sonra fark ettim ki, anlaşılması güç varlıklar hayal ettiğimden çok daha fazla......"
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "Bu yüzden önce D-balçıkla ilgili daha fazla bilgi edinmeye karar verdim; sonuçta bu, efendimin uzun süredir karşı durduğu bir düşman."
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "Ah, itaatsiz küçük yavrum, her zaman dünyanın dört bir yanında başıboş dolaşıyor."
  },
  AvgCommunicate_149988_Content_10 = {
    Text = "William'ın umurunda kimse yok."
  },
  AvgCommunicate_149988_Content_11 = {
    Text = "Sadece unutma: sen benim kişisel evcil yavrumsun. Sefil hayatına yönelik her tehdit, benim varlıklarımın kaybından ibarettir."
  },
  AvgCommunicate_149988_Content_12 = {
    Text = "Üstelik bu dünyayı ben özellikle seçtim — küçük bir yarık, Çözülme'den güvende."
  },
  AvgCommunicate_149988_Content_13 = {
    Text = "O yüzden dikkatli ol. Onu kırmamaya çalış."
  },
  AvgCommunicate_149988_Content_2 = {
    Text = "Sinyalin yine kesiliyor. Bu sefer hangi tanrının unuttuğu ıssız yere sürüklendин?"
  },
  AvgCommunicate_149988_Content_3 = {
    Text = "Hyperborea'dayım."
  },
  AvgCommunicate_149988_Content_4 = {
    Text = "Yaylaların çok yukarısındayım."
  },
  AvgCommunicate_149988_Content_5 = {
    Text = "Sırada bir dağa tırmanmaya hazırlanıyoruz. Açıkçası, dayanıklılığım konusunda biraz endişeleniyorum."
  },
  AvgCommunicate_149988_Content_6 = {
    Text = "Hava inanılmaz derecede seyrek burada. Birkaç adım koşsam bayılacakmış gibi hissediyorum."
  },
  AvgCommunicate_149988_Content_7 = {
    Text = "Ve sen gerçekten böyle bir dağa tırmanabileceğini mi sanıyorsun? Ne kadar pervasız, akılsız bir küçük yavru, kendi sınırlarından tamamen habersiz."
  },
  AvgCommunicate_149988_Content_8 = {
    Text = "Sadece endişelendiğini biliyorum, ama bitirmem gereken işler var."
  },
  AvgCommunicate_149988_Content_9 = {
    Text = "Merak etme, Kıdemli William burada benimle. İyi olacağız."
  },
  AvgCommunicate_149988_Option_3 = {
    Text = "Hyperborea."
  },
  AvgCommunicate_149988_Option_4 = {
    Text = "Yüksek rakımlı bir bölge."
  },
  AvgCommunicate_150103_Content_1 = {
    Text = "Kaderin dokusunun uzak köşelerinde hafif bir titreşim dalgalanıyor."
  },
  AvgCommunicate_150103_Content_10 = {
    Text = "Bu da senin kader dokumandaki bir iplik mi?"
  },
  AvgCommunicate_150103_Content_11 = {
    Text = "Bu konuda tezgah sessiz kalmalıdır."
  },
  AvgCommunicate_150103_Content_12 = {
    Text = "Bu dünyada yaşayan insanlara ne olacak? Şimdi onları ne bekliyor?"
  },
  AvgCommunicate_150103_Content_13 = {
    Text = "En saf özlerine dönecekler — Gümüş Çekirdeklere."
  },
  AvgCommunicate_150103_Content_14 = {
    Text = "Ve Tanrı-Kral, o parçaları sonsuz yağmurdan toplayacak; uzun ve sessiz bir uykudan sonra dünyayı yeniden şekillendirecek."
  },
  AvgCommunicate_150103_Content_15 = {
    Text = "Bu sessiz tanıklık paylaşılacaktır."
  },
  AvgCommunicate_150103_Content_2 = {
    Text = "Kritik eşik aşıldı. Uzun süredir aranan vaat edilmiş topraklara nihayet ulaşıldı."
  },
  AvgCommunicate_150103_Content_3 = {
    Text = "Buna inanamıyorum."
  },
  AvgCommunicate_150103_Content_4 = {
    Text = "Dünya yok oluyor."
  },
  AvgCommunicate_150103_Content_5 = {
    Text = "Gökyüzü eriyor, kar çöküyor, dağ zirveleri ufalanıyor."
  },
  AvgCommunicate_150103_Content_6 = {
    Text = "Bu dünyanın tamamı... hepsi sahteydi."
  },
  AvgCommunicate_150103_Content_7 = {
    Text = "Bunu hep biliyor muydun? Bunu hep görebiliyor muydun?"
  },
  AvgCommunicate_150103_Content_8 = {
    Text = "Dünyanın büyük sahnesinin dışında durmak, sonsuza dek dokumak demektir."
  },
  AvgCommunicate_150103_Content_9 = {
    Text = "Caraboo'nun dileği de buna dahil miydi? Dünya onsuz yok olmazdı."
  },
  AvgCommunicate_150103_Option_3 = {
    Text = "Görebiliyorum..."
  },
  AvgCommunicate_150103_Option_4 = {
    Text = "Dünya kayboluyor..."
  },
  AvgCommunicate_57593_Content_1 = {
    Text = "Ortak, geçen sefer sana ödünç verdiğim tarih ve doğa bilimleri kitaplarını bitirdin mi?"
  },
  AvgCommunicate_57593_Content_10 = {
    Text = "Ha? Gerçekten o kadar ciddi mi...?"
  },
  AvgCommunicate_57593_Content_11 = {
    Text = "Bunlar müfettişler için temel kitaplar. Ne kadar sıkıcı olursa olsun ezberlemen gerekiyor."
  },
  AvgCommunicate_57593_Content_12 = {
    Text = "Her gün sana bir saat ders vermeyi planlıyorum. Tabii daha hızlı öğrenmek istersen, bütün gece birlikte çalışabiliriz."
  },
  AvgCommunicate_57593_Content_13 = {
    Text = "Hayır, hayır, bir saat yeterli! Fazla çalışmak da sağlıklı değil!"
  },
  AvgCommunicate_57593_Content_14 = {
    Text = "Bu kadar istekli olmanı görmek beni sevindiriyor."
  },
  AvgCommunicate_57593_Content_15 = {
    Text = "Defterini getirmeyi unutma. İlerlemenizi kontrol edeceğim."
  },
  AvgCommunicate_57593_Content_17 = {
    Text = "Neden öyle dedim ki..."
  },
  AvgCommunicate_57593_Content_2 = {
    Text = "Şey, yani, biraz... göz gezdirdim."
  },
  AvgCommunicate_57593_Content_3 = {
    Text = "Ne kadarını gördün?"
  },
  AvgCommunicate_57593_Content_4 = {
    Text = "Şey ben... muhtemelen içindekiler kısmını hatırlıyorum."
  },
  AvgCommunicate_57593_Content_5 = {Text = "..."},
  AvgCommunicate_57593_Content_6 = {
    Text = "Kitaplar çok uzun ve sıkıcı! Daha ilk sayfayı bile geçemeden uyuyakalıyorum!"
  },
  AvgCommunicate_57593_Content_7 = {
    Text = "İyi tarafından bakarsak, okuduktan sonra bebek gibi uyudum..."
  },
  AvgCommunicate_57593_Content_8 = {
    Text = "Boş ver. Gel, her kitabı sana kendim öğreteyim."
  },
  AvgCommunicate_57593_Content_9 = {
    Text = "Her gün dersten sonra yurduma gel."
  },
  AvgCommunicate_57593_Option_10 = {
    Text = "Ha? Gerçekten o kadar ciddi mi...?"
  },
  AvgCommunicate_57593_Option_13 = {
    Text = "Hayır, hayır, bir saat yeterli!"
  },
  AvgCommunicate_57593_Option_2 = {Text = "Şey..."},
