  },
  AvgCommunicate_57594_Content_1 = {
    Text = "Partner, işte notlarım ve sen yokken kaçırdığın ödevler."
  },
  AvgCommunicate_57594_Content_10 = {
    Text = "D-değil mi?!"
  },
  AvgCommunicate_57594_Content_12 = {
    Text = "Tabii ki. Partnerlerin yapması gereken şey bu."
  },
  AvgCommunicate_57594_Content_13 = {
    Text = "Öğretmen Doll da memnun oldu ve sana özel olarak ek bonus sorular ekleyeceğini söylememi istedi."
  },
  AvgCommunicate_57594_Content_2 = {
    Text = "Ödevini yapmayı unutma."
  },
  AvgCommunicate_57594_Content_3 = {
    Text = "Boş verelim şunu..."
  },
  AvgCommunicate_57594_Content_4 = {
    Text = "Pardon, bağlantım pek stabil değil. Son mesajın ulaşmadı."
  },
  AvgCommunicate_57594_Content_6 = {
    Text = "Ah gerçekten mi? Bu arada, sana bir şey söylemeyi unuttum. Öğretmen Doll tam yanımda, izliyor."
  },
  AvgCommunicate_57594_Content_7 = {
    Text = "Şey... VAAAY! Bugün öğrenmek için birden ÇOK HEYECANLANDIM!"
  },
  AvgCommunicate_57594_Content_8 = {
    Text = "Ödevimi nasıl unuttum! Geç kalmadan hepsini bitirmeliyim!"
  },
  AvgCommunicate_57594_Content_9 = {
    Text = "Yani, Partner! Yetişmeme yardım edeceksin, değil mi?!"
  },
  AvgCommunicate_57594_Option_3 = {
