  },
  AvgCommunicate_57595_Content_1 = {
    Text = "Koruyucu, sen demiştin ki..."
  },
  AvgCommunicate_57595_Content_10 = {
    Text = "Birkaç düello daveti yazıp herkesin yatakhanesine göndereceğim; bu yeterince kibar olmalı."
  },
  AvgCommunicate_57595_Content_11 = {
    Text = "Karar verildi. Kırk tane yeterli mi acaba...?"
