  AvgCommunicate_57595_Content_12 = {
    Text = "?! Dur bir dakika, mesele insanlara nasıl meydan okuduğun değil! Bu çok ileri gidiyor!"
  },
  AvgCommunicate_57595_Content_13 = {
    Text = "Anlamıyorsun. Dexter'ın söylediğini duydum, eskiden insanlara yazılı bir davetle düello teklif etmek beyefendice bir davranış sayılırmış. Atalarından bir şeyler öğrenmelisin, genç adam!"
  },
  AvgCommunicate_57595_Content_14 = {
