  AvgCommunicate_57897_Content_1 = {
    Text = "%player%, sınav sonuçların geldi."
  },
  AvgCommunicate_57897_Content_10 = {
    Text = "Merak etme, hiç sorun değil. Yarın görüşürüz~."
  },
  AvgCommunicate_57897_Content_11 = {
    Text = "Tatilimde zaten planlanmış başka eğitimlerim var—"
  },
  AvgCommunicate_57897_Content_12 = {
    Text = "Şaka yapıyorum."
  },
  AvgCommunicate_57897_Content_13 = {
    Text = "Eğitim programını ayarladım. Git ve önümüzdeki birkaç gün tatilinin tadını çıkar."
  },
  AvgCommunicate_57897_Content_14 = {
    Text = "Gerçekten mi? Harika, teşekkür ederim!"
  },
  AvgCommunicate_57897_Content_2 = {
    Text = "Nasıl yaptığını tahmin etmek ister misin?"
  },
  AvgCommunicate_57897_Content_3 = {
    Text = "...B-beni strese sokuyorsun..."
  },
  AvgCommunicate_57897_Content_4 = {
    Text = "Endişelenme, seni tebrik etmek için buradayım. Bu dönem yaşadığın onca \"olaya\" rağmen, bu sınavda ÇOK iyi bir iş çıkardın."
  },
  AvgCommunicate_57897_Content_5 = {
    Text = "Hatta o kadar iyi yaptın ki bir ödülü hak ediyorsun. Yaklaşan eğitim programını bizzat ayarladım. Tatilinin tadını çıkar~."
  },
  AvgCommunicate_57897_Content_6 = {
    Text = "Özür dilerim, berbat ettim. Tatilimde çok çalışacağım..."
  },
  AvgCommunicate_57897_Content_7 = {
    Text = "Endişelenme, seni tebrik etmeye geldim. Bu dönem yaşadığın tüm “olaylara” rağmen, bu sınavda öyle İYİ iş çıkardın ki."
  },
  AvgCommunicate_57897_Content_8 = {
    Text = "Madem biraz izin almak istedin, tatilini telafi etmek için ders sonrası ekstra dersler vermemde bir sakınca yok."
  },
  AvgCommunicate_57897_Content_9 = {Text = "Ne? Asla!"},
  AvgCommunicate_57897_Option_11 = {
