  AvgCommunicate_57897_Option_9 = {Text = "Ne? Asla!"},
  AvgCommunicate_57898_Content_1 = {
    Text = "Seni buldum."
  },
  AvgCommunicate_57898_Content_10 = {
    Text = "...Bulduğun bu açığı okul yönetimine bildireceğim."
  },
  AvgCommunicate_57898_Content_11 = {
    Text = "Aman, ne yaramaz bir çocuk. Bu küçük şeyin beni sonsuza kadar tutabileceğini gerçekten düşünmüyorsun, değil mi?"
  },
  AvgCommunicate_57898_Content_12 = {
    Text = "Seni HER ZAMAN izliyor olacağım."
  },
  AvgCommunicate_57898_Content_2 = {
