  },
  AvgCommunicate_57898_Content_3 = {
    Text = "Zekisin. Neden tahmin edip çözmeye çalışmıyorsun?"
  },
  AvgCommunicate_57898_Content_4 = {
    Text = "Hmm, iletişim cihazını biliyorsun demek. Öğrenci misin?"
  },
  AvgCommunicate_57898_Content_5 = {
    Text = "Tabii, neden olmasın? Zaten herkes öyle diyor."
  },
  AvgCommunicate_57898_Content_6 = {
    Text = "Dur... sen o Doll değil misin?!"
  },
  AvgCommunicate_57898_Content_7 = {
