    Text = "Sen kimsin?"
  },
  AvgCommunicate_57898_Option_4 = {
    Text = "Burada öğrenci misin?"
  },
  AvgCommunicate_57898_Option_6 = {
    Text = "Sen o Doll'sun!"
  },
  AvgCommunicate_57898_Option_8 = {
    Text = "Ödül mü?"
