    Text = "{Male=Mr.,Female=Miss} %player%, Jenkin'i gördün mü?"
  },
  AvgCommunicate_57899_Content_10 = {
    Text = "Teşekkür ederim, %player%."
  },
  AvgCommunicate_57899_Content_2 = {
    Text = "Bu sabah \"çikolatalı çıtır\" diye bir şeyden bahsedip gitti. Şimdi onu bulamıyorum."
  },
  AvgCommunicate_57899_Content_3 = {
    Text = "Biraz endişeliyim."
  },
  AvgCommunicate_57899_Content_4 = {
    Text = "Hannah, Jenkin’in yanında olduğunu söyledi."
  },
  AvgCommunicate_57899_Content_5 = {
    Text = "Sanırım sana hediye olarak biraz çikolata almak istemişti."
  },
  AvgCommunicate_57899_Content_6 = {Text = "Hediye mi?"},
  AvgCommunicate_57899_Content_7 = {
    Text = "Ama bugün herhangi bir tatil bile değil... değil mi?"
  },
  AvgCommunicate_57899_Content_8 = {
    Text = "Şey, tatil olmasa bile birine hediye alabilirsin."
  },
  AvgCommunicate_57899_Content_9 = {
    Text = "Öyle mi... Tamam, o zaman Jenkin'e de bir hediye alacağım."
  },
  AvgCommunicate_57899_Option_4 = {
    Text = "Hannah, Jenkin’in yanında olduğunu söyledi."
  },
  AvgCommunicate_57899_Option_8 = {Text = "Şey..."},
  AvgCommunicate_57900_Content_1 = {Text = "Efendim?"},
  AvgCommunicate_57900_Content_10 = {
    Text = "İnanılmaz! Bunu nasıl yaptın?"
  },
  AvgCommunicate_57900_Content_11 = {
    Text = "Bekle. Gelip sana göstereyim."
  },
  AvgCommunicate_57900_Content_2 = {
    Text = "Ne oldu, Ogier?"
  },
  AvgCommunicate_57900_Content_3 = {
    Text = "Vay, gerçekten çalışıyor..."
  },
  AvgCommunicate_57900_Content_4 = {
    Text = "Özür dilerim, Lordum. Biraz önce soğukkanlılığımı kaybettim."
  },
  AvgCommunicate_57900_Content_5 = {
    Text = "Bayan Doll az önce bana test etmem için geliştirilmiş bir iletişimci gönderdi. Bu kadar iyi çalışacağını beklemiyordum."
  },
  AvgCommunicate_57900_Content_6 = {
    Text = "Acaba başka neler gönderilebilir."
  },
  AvgCommunicate_57900_Content_7 = {
    Text = "Görsel de gönderebilirsin!"
  },
  AvgCommunicate_57900_Option_2 = {Text = "Neyin var?"},
  AvgCommunicate_57901_Content_1 = {Text = "?!#¥%&*()"},
  AvgCommunicate_57901_Content_10 = {
    Text = "Ah! Özür dilerim, Koruyucu!"
  },
  AvgCommunicate_57901_Content_11 = {
    Text = "Bir dahaki sefere kesinlikle unutmayacağım! Kesinlikle!"
  },
  AvgCommunicate_57901_Content_2 = {Text = "??"},
  AvgCommunicate_57901_Content_3 = {
    Text = "Özür dilerim. Hâlâ klavye kullanmaya alışıyorum."
  },
  AvgCommunicate_57901_Content_4 = {
    Text = "Sorun değil. Ben de başladığımda hatalar yapıyordum. Pratik yapmaya devam et, sonunda alışırsın."
  },
  AvgCommunicate_57901_Content_5 = {
    Text = "Evet, ama... Yarına kadar öğrendiğim her şeyi unutacağımdan korkuyorum."
  },
  AvgCommunicate_57901_Content_6 = {
    Text = "O zaman daha çok pratik yap! Her şey yoluna girecek!"
  },
  AvgCommunicate_57901_Content_7 = {
    Text = "Haklısın! Teşekkürler, Alva!"
  },
  AvgCommunicate_57901_Content_8 = {
    Text = "Şey... Ben Alva değilim."
  },
  AvgCommunicate_57901_Content_9 = {
    Text = "Aslında ben Koruyucu'yum."
  },
  AvgCommunicate_57901_Option_2 = {Text = "??"},
  AvgCommunicate_57901_Option_4 = {
    Text = "Pratik yapmak mükemmelleştirir. Kısa sürede alışırsın."
  },
  AvgCommunicate_57901_Option_6 = {
    Text = "O zaman daha çok pratik yap!"
  },
  AvgCommunicate_57901_Option_8 = {
    Text = "Ben Alva değilim."
  },
  AvgCommunicate_57901_Option_9 = {
    Text = "Aslında ben Koruyucu'yum."
  },
  AvgCommunicate_57903_Content_1 = {
    Text = "İyi günler, solgun haberci."
  },
  AvgCommunicate_57903_Content_10 = {
    Text = "Söylemeliyim ki, oldukça dahice."
  },
  AvgCommunicate_57903_Content_2 = {
    Text = "Merhaba, Piskopos Salvador."
  },
  AvgCommunicate_57903_Content_3 = {
    Text = "Görünüşe göre en yeni iletişim cihazını almışsın. Nasıl buldun?"
  },
  AvgCommunicate_57903_Content_4 = {
    Text = "Çok ilginç ve kullanışlı. Yüzlerce mil uzakta olmamıza rağmen, yüz yüzeymişiz gibi iletişim kurabiliyoruz."
  },
  AvgCommunicate_57903_Content_5 = {
    Text = "Tüm dünyada böyle cihazlar olsaydı, insanlar arasındaki mesafe şimdiki kadar büyük olmazdı."
  },
  AvgCommunicate_57903_Content_6 = {
    Text = "Ama bu teknolojinin benzersizliğini anlıyorum—bilgiyi ruhlarımızı birbirine bağlayarak ilettiğini biliyorsun, değil mi?"
  },
  AvgCommunicate_57903_Content_7 = {
    Text = "Sadece içinde bir Gümüş Çekirdek olduğunu biliyorum."
  },
  AvgCommunicate_57903_Content_8 = {
    Text = "Nasıl çalıştığını öğrenebildin mi?"
  },
  AvgCommunicate_57903_Content_9 = {
    Text = "Evet. Ruhlarımız bir Gümüş Çekirdeğe bağlanıyor ve bu çekirdek de diğer benzer cihazlardaki Çekirdeklere bağlanıyor."
  },
  AvgCommunicate_57903_Option_2 = {
    Text = "Merhaba, Piskopos Salvador."
  },
  AvgCommunicate_57903_Option_7 = {
    Text = "Sadece içinde bir Gümüş Çekirdek olduğunu biliyorum."
  },
  AvgCommunicate_57903_Option_8 = {
    Text = "Nasıl çalıştığını öğrenebildin mi?"
  },
  AvgCommunicate_57904_Content_1 = {
    Text = "Koruyucu, dün sanatoryuma malzeme getirdiğin için teşekkür ederim. Lütfen Lord Dexter'a süregelen desteği için teşekkürlerimi ilet."
  },
  AvgCommunicate_57904_Content_10 = {
    Text = "Onun için yapabileceğim tek şey bu..."
  },
  AvgCommunicate_57904_Content_2 = {
    Text = "Yapmamız gereken şey bu."
  },
  AvgCommunicate_57904_Content_3 = {
    Text = "Sanatoryum sensiz ayakta kalamazdı."
  },
  AvgCommunicate_57904_Content_4 = {
    Text = "Dekan sana mutlaka minnettar kalacaktır."
  },
  AvgCommunicate_57904_Content_5 = {
    Text = "Sanatoryumu tek başına yönetmek zor olmalı."
  },
  AvgCommunicate_57904_Content_6 = {
    Text = "Önemli bir şey değil, gerçekten."
  },
  AvgCommunicate_57904_Content_7 = {
    Text = "Tek umduğum, sanatoryumdaki hastaların bir anlığına da olsa huzur bulabilmesi."
  },
  AvgCommunicate_57904_Content_8 = {
    Text = "Vaktin olursa, lütfen Lily’yi daha sık geri getir."
  },
  AvgCommunicate_57904_Content_9 = {
    Text = "Dekanın ofisini temizleyip sizi bekleyeceğim."
  },
  AvgCommunicate_57904_Option_2 = {
    Text = "Yapmamız gereken şey bu."
  },
  AvgCommunicate_57904_Option_5 = {
    Text = "Sanatoryumu tek başına yönetmek zor olmalı."
  },
  AvgCommunicate_57905_Content_1 = {
    Text = "Ding-ding~! Harika Hizmetçiniz Karen burada, kahvaltınızın kalktığınızda kapınızda olacağını bildirmek için~!"
  },
  AvgCommunicate_57905_Content_10 = {
    Text = "Ah, onu bana bırakın! Karen her işe yarayan bir hizmetçidir; çamaşırdan kilit değişimine ve daha neler neler~!"
  },
  AvgCommunicate_57905_Content_11 = {
    Text = "Hayır! Odama GİRME!"
  },
  AvgCommunicate_57905_Content_12 = {
    Text = "Bu kadar utangaç olmayın! Birazdan orada olacağım~!"
  },
  AvgCommunicate_57905_Content_2 = {
    Text = "Hey! Kıyafetlerimi sen mi aldın!?"
  },
  AvgCommunicate_57905_Content_3 = {
    Text = "Aman Tanrım, Efendim. Neden bu kadar erken uyandınız? Kıyafetleriniz henüz kurumadı!"
  },
  AvgCommunicate_57905_Content_4 = {
    Text = "\"Henüz kurumadı mı\"? Kıyafetlerimi mi yıkıyorsun?"
  },
  AvgCommunicate_57905_Content_5 = {
    Text = "Tabii ki! Nitelikli bir hizmetçi olarak, Efendim'in kirli, buruşuk kıyafetlerle dışarı çıkmasına asla izin veremezdim!"
  },
  AvgCommunicate_57905_Content_6 = {
    Text = "Bu yüzden bütü~n gece uyanık kalıp tüm kıyafetlerinizi te~miz~le~dim~!"
  },
  AvgCommunicate_57905_Content_7 = {
    Text = "Her şeyi yıkayıp giyecek hiçbir şey bırakmaman olmaz ki!"
  },
  AvgCommunicate_57905_Content_8 = {
    Text = "Aslında Efendim'in hâlâ bir kıyafeti var. Açıkçası onu da yıkamak isterdim ama... Efendim yatakta öyle sımsıkı sarılmıştı ki, sizi uyandırmadan çıkaramadım~."
  },
  AvgCommunicate_57905_Content_9 = {
    Text = "...Kilit değiştiriyorum."
  },
  AvgCommunicate_57905_Option_11 = {
    Text = "Hayır! Odama GİRME!"
  },
  AvgCommunicate_57905_Option_2 = {
