  AvgCommunicate_57906_Content_1 = {
    Text = "Mmm... bir bakayım şu şey çalışıyor mu..."
  },
  AvgCommunicate_57906_Content_2 = {
    Text = "Dışarıda tatminsiz olan ve benim kırbacıma biraz ihtiyaç duyan biri var mı?"
