  AvgCommunicate_57906_Content_7 = {
    Text = "...İletişim cihazımı kapatıyorum."
  },
  AvgCommunicate_57906_Content_8 = {
    Text = "Seninle bu kadar rahat ve özel bir şekilde konuşabilmek oldukça nadir. Korkma; bu bizim küçük sırrımız."
  },
  AvgCommunicate_57906_Content_9 = {
