  },
  AvgCommunicate_57907_Content_10 = {
    Text = "...Bunu daha önce duymamıştım."
  },
  AvgCommunicate_57907_Content_11 = {
    Text = "Hâlâ emin değilsen, iyi olduğun şeylerle başlamaya ne dersin?"
  },
  AvgCommunicate_57907_Content_12 = {
    Text = "Geçmişini düşünürsek, asker eğitiminde oldukça yetenekli olduğunu söyleyebilirim. Neden oradan başlamıyorsun?"
  },
  AvgCommunicate_57907_Content_13 = {
    Text = "Eğitim, ha. Bu... işe yarayabilir."
  },
  AvgCommunicate_57907_Content_14 = {
    Text = "Teşekkür ederim, Koruyucu."
  },
  AvgCommunicate_57907_Content_2 = {
    Text = "Biraz... kafam karışık."
  },
  AvgCommunicate_57907_Content_3 = {
    Text = "Sana hemen iş mi verdi?"
  },
  AvgCommunicate_57907_Content_4 = {
    Text = "Şimdiden seni mi sömürüyor?"
  },
  AvgCommunicate_57907_Content_5 = {
    Text = "Hahaha... öyle değil. Yardım etmeyi teklif eden bendim ama... nasıl yardımcı olabileceğimden emin değilim..."
  },
  AvgCommunicate_57907_Content_6 = {
    Text = "Hayatım boyunca asker oldum; hep başkalarının emirlerini takip ettim. Remouahe'deyken bile ne yapmam gerektiğinden hiçbir zaman tam emin olamadım."
  },
  AvgCommunicate_57907_Content_7 = {
