  AvgCommunicate_58498_Option_7 = {Text = "!!"},
  AvgCommunicate_60943_Content_1 = {
    Text = "Partner, bu görev için elimiz yetersiz. İleri mevziye erken gidip hazırlık yapmam gerekiyor, bu yüzden korkarım seninle birlikte operasyon yürütemeyeceğim."
