  AvgCommunicate_60943_Content_10 = {
    Text = "Biliyorum. Her zaman herkes için her şeyi düşünürsün."
  },
  AvgCommunicate_60943_Content_11 = {
    Text = "Ama belki de artık arkana bakma konusunda bana güvenmeyi öğrenmenin zamanı gelmiştir? Partner."
