  },
  AvgCommunicate_60943_Content_2 = {
    Text = "Senin için birkaç kriz acil durum planı yazdım. Herhangi bir acil durum ortaya çıkarsa, içindekiler bölümündeki ilgili kısma başvurabilirsin."
  },
  AvgCommunicate_60943_Content_3 = {
