  },
  AvgCommunicate_60943_Content_7 = {
    Text = "Elbette yeteneklerine güveniyorum, sadece…"
  },
  AvgCommunicate_60943_Content_8 = {
    Text = "Özür dilerim, her şey hakkında Çıkarım yapmaya alışkınım. Orada olmazsam, en kötü olasılıkları düşünmeden edemiyorum."
  },
  AvgCommunicate_60943_Content_9 = {
