  },
  AvgCommunicate_66973_Content_12 = {
    Text = "Tabii ki. Ablam her zaman benim için en önemli kişi olacak ve sonsuza dek ona bakmaya devam edeceğim."
  },
  AvgCommunicate_66973_Content_13 = {
    Text = "Görünüşe göre gelecekteki buluşmalarda ablama rehberlik etme sırası bende olacak."
  },
  AvgCommunicate_66973_Content_14 = {
    Text = "Fırsatın olursa, Koruyucu, sen de bize katılmalısın!"
