  AvgCommunicate_66973_Content_15 = {
    Text = "Sorun değil!"
  },
  AvgCommunicate_66973_Content_2 = {
    Text = "Rica ederim! Yardımcı olabildiğime sevindim!"
  },
  AvgCommunicate_66973_Content_3 = {
    Text = "Eskiden hep ablama bağımlıydım ve o da benim önümde hep güçlü davranırdı—hatta biraz sert bile."
  },
  AvgCommunicate_66973_Content_4 = {
    Text = "O tür bir durumda bu kadar telaşlanacağını hiç beklemezdim. Ablamı daha önce hiç bu kadar utangaç görmemiştim."
