  AvgCommunicate_66985_Option_14 = {
    Text = "O zaman bir deneyeyim—leydimin en çok sevdiği yemeği."
  },
  AvgCommunicate_66985_Option_3 = {
    Text = "Çok naziksiniz, Leydi Sorel."
  },
  AvgCommunicate_66985_Option_6 = {
    Text = "Vay canına, herhangi bir şey mi?"
  },
  AvgCommunicate_66985_Option_8 = {
    Text = "Şimdi beni gerçekten zor durumda bıraktın…"
  },
  AvgCommunicate_66986_Content_1 = {
    Text = "Lotan ile az önce bir dövüş yaptık. Berabere kaldık."
  },
  AvgCommunicate_66986_Content_10 = {
    Text = "Ahaha… Sanırım o kadar çok dikkat dağıtan düşüncem yok, bu yüzden şimdilik pas geçeyim…"
  },
  AvgCommunicate_66986_Content_11 = {
    Text = "O zaman sen de güçlüsün."
  },
  AvgCommunicate_66986_Content_12 = {
    Text = "Ne yazık ki, o şelalenin yanında her zaman balık tutan biri oluyor. Biraz gürültülü."
  },
  AvgCommunicate_66986_Content_13 = {
    Text = "Bir keresinde şelaleden çıkıp ondan sesini kısmasını istemeye çalıştım. O kadar korktu ki balığını yüzüme fırlatıp kaçtı."
  },
  AvgCommunicate_66986_Content_14 = {
    Text = "Acaba bir dahaki sefere geri gelir mi?"
  },
  AvgCommunicate_66986_Content_15 = {
    Text = "Hmm… Geleceğini sanmıyorum…"
  },
  AvgCommunicate_66986_Content_2 = {
    Text = "İkinizin arasında ne oldu?"
  },
  AvgCommunicate_66986_Content_3 = {
    Text = "Kavga etmediniz, değil mi?"
  },
  AvgCommunicate_66986_Content_4 = {
    Text = "Hayır, sadece savaşçılar arasında bir antrenman dövüşüydü."
  },
  AvgCommunicate_66986_Content_5 = {
    Text = "Daha önce dövüş tarzımın yeterince saf olmadığını söylemişti. Sanırım şimdi anlıyorum."
  },
  AvgCommunicate_66986_Content_6 = {
    Text = "Daha saf olmanın bir yolunu buldum. Şu anki ben daha güçlü."
  },
  AvgCommunicate_66986_Content_7 = {
    Text = "Bu iyi bir şey, ama daha saf olmak için ne yöntem kullanıyorsun?"
  },
  AvgCommunicate_66986_Content_8 = {
    Text = "Bir şelalenin altında dur ve suyun dikkat dağıtan düşüncelerini yıkamasına izin ver."
  },
  AvgCommunicate_66986_Content_9 = {
    Text = "Çok etkili. Birlikte gitmek ister misin?"
  },
  AvgCommunicate_66986_Option_10 = {
    Text = "Ahaha… Sanırım o kadar çok dikkat dağıtan düşüncem yok, bu yüzden şimdilik pas geçeyim…"
  },
  AvgCommunicate_66986_Option_15 = {
    Text = "Hmm… Geleceğini sanmıyorum…"
