  },
  AvgCommunicate_66986_Option_7 = {
    Text = "Bu iyi bir şey, ama daha saf olmak için ne yöntem kullanıyorsun?"
  },
  AvgCommunicate_66987_Content_1 = {
    Text = "Koruyucu, balık tarifleri biliyor musun?"
  },
  AvgCommunicate_66987_Content_10 = {
    Text = "Ne kadar nazik ve şefkatli bir nine."
  },
  AvgCommunicate_66987_Content_11 = {
    Text = "Mm. Bu yüzden ben de balık pişirmeyi öğrenmek istiyorum. Bir dahaki sefere onun için ben pişireceğim."
  },
  AvgCommunicate_66987_Content_12 = {
    Text = "Çok dokunaklı! Kesinlikle yapmalısın! Hemen gidip yemekhane aşçısını senin için sorguya çekeyim!"
  },
  AvgCommunicate_66987_Content_13 = {
    Text = "Teşekkür ederim."
  },
  AvgCommunicate_66987_Content_2 = {
    Text = "Tarifler mi?? Yemek mi yapacaksın?"
  },
  AvgCommunicate_66987_Content_3 = {
    Text = "Mm, geçen sefer oltacıyı korkuttuğumdan beri şelalenin yakınları epey sessiz kaldı."
  },
  AvgCommunicate_66987_Content_4 = {
    Text = "Son zamanlarda yaşlı bir kadın buraya balık tutmaya geliyor. Hiç ses çıkarmıyor, ben de kendimi hiç göstermedim."
  },
  AvgCommunicate_66987_Content_5 = {
    Text = "Sonra bir keresinde ateş yakıp tuttuğu balıkları ızgara yapmaya başladı."
  },
  AvgCommunicate_66987_Content_6 = {
    Text = "Kokusu o kadar güzeldi ki karnım hafifçe ses çıkardı ve beni fark etti."
  },
  AvgCommunicate_66987_Content_7 = {
    Text = "Ha? Onu da mı korkuttun?"
  },
  AvgCommunicate_66987_Content_8 = {
    Text = "Hayır, beni de ızgara balık yemeye davet etti. Çok lezzetliydi."
  },
  AvgCommunicate_66987_Content_9 = {
    Text = "Sonra balık tutmaya gelirken yanında küçük bir tencere getirmeye başladı, balık çorbası yapıp benimle paylaşıyordu."
  },
  AvgCommunicate_66987_Option_10 = {
    Text = "Ne kadar nazik ve şefkatli bir nine."
  },
  AvgCommunicate_66987_Option_12 = {
    Text = "Çok dokunaklı! Kesinlikle yapmalısın! Hemen gidip yemekhane aşçısını senin için sorguya çekeyim!"
  },
  AvgCommunicate_66987_Option_2 = {
