  AvgCommunicate_66987_Option_7 = {
    Text = "Ha? Onu da mı korkuttun?"
  },
  AvgCommunicate_66988_Content_1 = {
    Text = "Geçenlerde güzel bir miktar para kazandım ama bu süreçte neredeyse ölüyordum. Neyse ki şans tanrıçası bana her zaman Lütuf bahşeder."
  },
  AvgCommunicate_66988_Content_10 = {
    Text = "Ama dövüşmeye başladığımızda, kurduğu tuzak yanlışlıkla tetiklendi ve kendisine isabet etti."
  },
  AvgCommunicate_66988_Content_11 = {Text = "Ha?"},
  AvgCommunicate_66988_Content_12 = {
    Text = "Hatta ona acil Kan kontrolü bile uyguladım, onu karakola getirdiğimde hâlâ hayatta olmasının tek sebebi buydu."
  },
  AvgCommunicate_66988_Content_13 = {
    Text = "Polis bana ödül verdi. Mahkûm cezaevine geri döndü ve cezasının müebbete çevrildiğini duydum."
  },
  AvgCommunicate_66988_Content_14 = {
    Text = "Çıkmasına sadece birkaç yıl kalmıştı. Neden bu kadar aptalca bir şey yapmak zorundaydı ki... *iç çeker*..."
  },
  AvgCommunicate_66988_Content_15 = {
    Text = "Kimin durumu daha kötü söylemek Zor, seninki mi onunki mi..."
  },
  AvgCommunicate_66988_Content_16 = {
    Text = "Ama dur, daha dün Bahis Fang'ından adamlar borç tahsil etmeye gelmedi mi? Ödül paran ne oldu?"
  },
  AvgCommunicate_66988_Content_17 = {
    Text = "Ahaha... Şey, şansım sınırlı ne de olsa. Hepsini önceden harcarsam, masada birkaç el kaybetmem kaçınılmaz..."
  },
  AvgCommunicate_66988_Content_18 = {
    Text = "Bunu duyunca, birden kendimi çok daha iyi hissettim."
  },
  AvgCommunicate_66988_Content_2 = {Text = "Ne oldu??"},
  AvgCommunicate_66988_Content_3 = {
    Text = "Bilirsin, genellikle dışarıda dedektiflik görevleri alırım. Dava çözme başarı oranım o kadar yüksek ki her zaman büyük talep görürüm."
  },
  AvgCommunicate_66988_Content_4 = {
    Text = "Ama bunun diğer tarafında, hapse gönderdiğim suçlular benden nefret ediyor."
  },
  AvgCommunicate_66988_Content_5 = {
    Text = "Sonuçta en şaşırtıcı şekillerde kaybettiler."
  },
  AvgCommunicate_66988_Content_6 = {
    Text = "Birkaç gün önce, bir mahkum hapisten kaçtı ve sık gittiğim Bahis Fang'ın önünde günlerce pusuya yattı, ta ki sonunda beni yakalayıncaya kadar."
  },
  AvgCommunicate_66988_Content_7 = {
    Text = "Senden intikam almak için mi oradaymış?!"
  },
  AvgCommunicate_66988_Content_8 = {
    Text = "Aynen öyle. Uzun süre beni takip etti ve sonunda bir ara sokakta köşeye sıkıştırdı."
  },
  AvgCommunicate_66988_Content_9 = {
    Text = "Ara sokağa önceden tuzaklar kurmuştu, beni öldürmeyi planlıyordu."
  },
