  AvgCommunicate_66989_Content_1 = {
    Text = "Koruyucu, bana danıştığın Müfettiş kriz yönetimi protokollerini derlemeyi bitirdim."
  },
  AvgCommunicate_66989_Content_10 = {
    Text = "O Ramona'dan ihtiyaçlarına karşı daha dikkatli olsam da, unutma— bir zamanlar ben de oydum."
  },
  AvgCommunicate_66989_Content_11 = {
    Text = "Beni kandırmak istiyorsan, daha çok pratik yapman gerekecek."
  },
  AvgCommunicate_66989_Content_12 = {
    Text = "Ah be… Samimiyetimi yanlış kişiye harcamışım!"
  },
  AvgCommunicate_66989_Content_13 = {
    Text = "Peki o ödev— yani, o soru— en azından nasıl yaklaşmam gerektiğine dair bir ipucu ver!"
  },
  AvgCommunicate_66989_Content_14 = {Text = "Ramona?"},
  AvgCommunicate_66989_Content_15 = {Text = "Ramona—"},
  AvgCommunicate_66989_Content_2 = {
