  },
  AvgCommunicate_66989_Option_8 = {Text = "?!"},
  AvgCommunicate_66990_Content_1 = {
    Text = "Koruyucu, herkesin isimleri çok zor yazılıyor. Yazılışlarını hatırlayamıyorum!"
  },
  AvgCommunicate_66990_Content_10 = {
    Text = "O zaman, o zaman değiştiririm! Sakın kimseye söyleme!"
  },
  AvgCommunicate_66990_Content_11 = {
    Text = "Tamam, tamam, peki Aigis ve Lily'nin isimleri ne?"
  },
  AvgCommunicate_66990_Content_12 = {
    Text = "Tabii ki adları Aigis ve Lily. Onlar arkadaş. Arkadaşların aynı adı olamaz!"
  },
  AvgCommunicate_66990_Content_13 = {
    Text = "O zaman bana neden Koooruyucu deniyor..."
