  AvgCommunicate_66990_Content_15 = {
    Text = "Bence önce sana okuma yazma öğretecek birini bulmak daha güvenilir olur."
  },
  AvgCommunicate_66990_Content_2 = {
    Text = "Doğrusu, senin için biraz zorlayıcı. Ramona sana okuma yazma dersi verse nasıl olur?"
  },
  AvgCommunicate_66990_Content_3 = {
    Text = "Olmaz öyle şey! Ne yani, Batı-Yavrusu? Okuma bilmiyorum diye beni küçümsüyor musun?"
  },
  AvgCommunicate_66990_Content_4 = {
    Text = "Ben etmedim... Konuyu ilk sen açmadın mı!"
