    Text = "Brown mı?! Brown senin evinde mi?"
  },
  AvgCommunicate_66991_Content_14 = {
    Text = "Evet, aramayı bırakabilirsin. Ayrıca gömleğime dolanmış ve ağzında bir çorabım var, bırakmıyor. Bunun ne anlama geldiği hakkında bir fikrin var mı?"
  },
  AvgCommunicate_66991_Content_15 = {
    Text = "B-bu kesinlikle onun kendi fare hobisi. Benimle hiçbir ilgisi yok!"
  },
  AvgCommunicate_66991_Content_16 = {
    Text = "En kötü ihtimalle sana yeni bir çift çorap alırım."
  },
  AvgCommunicate_66991_Content_2 = {
    Text = "Brown mu? Hep senin yanında değil mi?"
  },
  AvgCommunicate_66991_Content_3 = {
    Text = "Çoğu zaman evet, ama bazen dışarı çıkıp çal... *öhöm* avlanmaya gidiyor. Genelde yarım gün içinde döner, ama bir gündür onu hiç görmedim!"
  },
  AvgCommunicate_66991_Content_4 = {
