  },
  AvgCommunicate_66991_Content_5 = {
    Text = "En çok mutfağa gider, ama o salaklar Brown'u asla yakalayamaz."
  },
  AvgCommunicate_66991_Content_6 = {
    Text = "Parlak şeyler bulmak için laboratuvarlara da gidebilir, ama hepsini tek tek kontrol ettim. Hiçbir yerde Brown'dan iz yok."
  },
  AvgCommunicate_66991_Content_7 = {
