    Text = "Önceki ziyaretim herkese biraz yardımcı olmuş gibi görünüyor ve konferans salonunda herkesle sohbet etmek için tekrar davet edildim."
  },
  AvgCommunicate_67018_Content_3 = {
    Text = "Eğer biraz boş vaktin olursa, kampüste buluşabileceğimizi umuyorum."
  },
  AvgCommunicate_67018_Content_4 = {
    Text = "Çok isterim!"
  },
  AvgCommunicate_67018_Content_5 = {
    Text = "Harika. Sadece senin için zaman ayıracağım, bana anlatmak istediğin her şeyi dinlemek için."
  },
  AvgCommunicate_67018_Content_6 = {
    Text = "Sadece ikimiz mi?"
  },
  AvgCommunicate_67018_Content_7 = {
    Text = "Evet. Sonuçta bu bir ibadet töreni değil—Sadece arkadaşlar arasında bir buluşma, değil mi?"
  },
  AvgCommunicate_67018_Content_8 = {
    Text = "Sorun değil. Sana Mythag'ın görülecek yerlerini gezdireceğim. Belki Uyandırıcı yemekhanesini denemek istersin?"
  },
  AvgCommunicate_67018_Content_9 = {
    Text = "Senin planlarına uyacağım. Sabırsızlanıyorum."
  },
  AvgCommunicate_67018_Option_4 = {
    Text = "Çok isterim!"
  },
  AvgCommunicate_67018_Option_6 = {
