  AvgCommunicate_67018_Option_8 = {
    Text = "Sorun değil!"
  },
  AvgCommunicate_67019_Content_1 = {
    Text = "Soluk Elçi, Kilise bölgesinde yakında büyük bir Ayin düzenlenecek."
  },
  AvgCommunicate_67019_Content_10 = {
    Text = "Samimi kalbin beni çok duygulandırıyor. O halde artık reddetmeyeceğim."
  },
  AvgCommunicate_67019_Content_11 = {
    Text = "Müsait olduğun zaman gel ve basit temizlik ve süsleme işlerinde bana yardım et."
  },
  AvgCommunicate_67019_Content_12 = {
    Text = "Sorun değil, o zaman görüşürüz!"
  },
  AvgCommunicate_67019_Content_13 = {
    Text = "Bir kez daha teşekkür ederim, Soluk Elçi. Ulu Peder önündeki Yol'u gözetsin."
  },
  AvgCommunicate_67019_Content_2 = {
    Text = "Töreni ben yöneteceğim ve Ulu Peder'in öğretilerini paylaşacağım."
  },
  AvgCommunicate_67019_Content_3 = {
    Text = "Londinium ve çevre bölgelerden inananlar katılacak. İlgilenirsen, sen de bu Efkaristiya kutlamasına katılabilirsin."
  },
  AvgCommunicate_67019_Content_4 = {
    Text = "Çok isterim! Ama bu kadar çok inananla ilgilenmek gerektiğinde, bu Ayin için hazırlıklar epey zorlu olmalı."
  },
  AvgCommunicate_67019_Content_5 = {
    Text = "Her zaman çok dikkatli, nazik ve başkalarını düşünen birisin."
  },
  AvgCommunicate_67019_Content_6 = {
    Text = "Gerçekten de herkesin uygun şekilde ağırlanmasını ve Ulu Peder'in lütfunu hissedebilmesini sağlamak büyük bir hazırlık gerektiriyor."
  },
  AvgCommunicate_67019_Content_7 = {
