  },
  AvgCommunicate_67019_Content_9 = {
    Text = "Sonuçta bu kadar büyük bir etkinlik için hazırlıklar ne kadar kapsamlı olursa o kadar iyi."
  },
  AvgCommunicate_67019_Option_12 = {
    Text = "Sorun değil, o zaman görüşürüz!"
  },
  AvgCommunicate_67019_Option_4 = {
    Text = "Memnuniyetle!"
