  AvgCommunicate_67019_Option_8 = {
    Text = "Mümkünse erken gelip sana yardım edeyim!"
  },
  AvgCommunicate_67020_Content_1 = {
    Text = "Ah, Mythag o kısıtlama emrini çıkardığından beri, artık hiçbir tatlı şey bana eşlik etmeye gelmiyor."
  },
  AvgCommunicate_67020_Content_10 = {
    Text = "Pekâlâ, o hâlde Güneş'in çabuk batması için dua etmem gerekecek."
  },
  AvgCommunicate_67020_Content_11 = {
    Text = "Ah, bu geceki ay ışığını şimdiden dört gözle bekliyorum."
  },
  AvgCommunicate_67020_Content_2 = {
    Text = "Senin eşliğin olmadan başka kimsenin beni görmesine izin verilmediğini söylüyorlar."
  },
  AvgCommunicate_67020_Content_3 = {
    Text = "Sen, ah sen, söyle bana—kıskandın da beni okula mı şikâyet ettin?"
  },
  AvgCommunicate_67020_Content_4 = {
    Text = "Öğrencileri tuhaf şeyler içmeye kandıran ilk başta sen oldun..."
  },
  AvgCommunicate_67020_Content_5 = {
    Text = "Bu açıkça bir sevgi hediyesiydi. Gözünde gerçekten bu kadar aşağılık mıyım?"
  },
  AvgCommunicate_67020_Content_6 = {
    Text = "Her gün yalnızlık içinde seni bekliyorum, ama sen beni böyle mi görüyorsun..."
  },
  AvgCommunicate_67020_Content_7 = {
    Text = "Dur! Anladım, seni daha sık ziyarete geleceğim."
  },
  AvgCommunicate_67020_Content_8 = {
    Text = "Ne düşünceli bir çocuk. Ama seni her an görmek istiyorum—şu an—bir saniye bile beklemek istemiyorum."
  },
  AvgCommunicate_67020_Content_9 = {
    Text = "Bu gece, bu gece geleceğim, tamam mı!"
  },
  AvgCommunicate_67020_Option_4 = {
    Text = "Öğrencileri tuhaf şeyler içmeye kandıran ilk başta sen oldun..."
  },
  AvgCommunicate_67020_Option_7 = {
