  AvgCommunicate_67021_Content_1 = {
    Text = "Koruyucu, rahatsız ettiğim için özür dilerim. Son zamanlarda boş vaktin var mı?"
  },
  AvgCommunicate_67021_Content_10 = {
    Text = "Yani benimle gelip gelemeyeceğimi mi soruyorsun?"
  },
  AvgCommunicate_67021_Content_11 = {
    Text = "Mm, olur mu acaba?"
  },
  AvgCommunicate_67021_Content_12 = {
    Text = "Tabii ki! Çok eğlenceli olacağa benziyor!"
  },
  AvgCommunicate_67021_Content_13 = {
    Text = "Teşekkür ederim, Koruyucu! Yanımda olman beni çok daha rahat hissettiriyor."
  },
  AvgCommunicate_67021_Content_14 = {
    Text = "Orada anında yazılan şiirlerin ödül kazanma şansı olduğunu duydum. Şansım yaver gidip bir tane kazanırsam, teşekkür hediyesi olarak sana vereceğim."
  },
  AvgCommunicate_67021_Content_2 = {
    Text = "Ne oldu? Kendi başına bana gelmen çok nadir."
  },
  AvgCommunicate_67021_Content_3 = {
    Text = "Şey, Londinium'da yakında bir şiir fuarı olacak. Orada birçok yeni ve eski kitap satılacak ve birçok şair fikir alışverişi yapmak için katılacak."
  },
  AvgCommunicate_67021_Content_4 = {
    Text = "Organizatörler beni de şiir koleksiyonumu paylaşmam için bir stant kurmaya davet ettiler."
  },
  AvgCommunicate_67021_Content_5 = {
    Text = "Davetleri o kadar nazikti ki yanlışlıkla kabul ettim, ama..."
  },
  AvgCommunicate_67021_Content_6 = {
    Text = "Ama tek başına stant işletmek çok gerginlik verici mi geliyor?"
  },
  AvgCommunicate_67021_Content_7 = {
    Text = "Mm... Beni her zaman anlıyorsun."
  },
  AvgCommunicate_67021_Content_8 = {
    Text = "Ama kabul ettiğim bir şeyden geri dönmek istemiyorum ve etkinlik gerçekten çok ilginç görünüyor! Hatta canlı bir ortak yazım yarışması bile olduğunu duydum."
  },
