  AvgCommunicate_67022_Content_13 = {
    Text = "Tabii ki! Mythag'ın en nazik, en güvenilir ve en güçlü Koruyucusu — bu iş için senden daha uygun kimse yok!"
  },
  AvgCommunicate_67022_Content_14 = {
