  AvgCommunicate_67022_Content_3 = {
    Text = "Gece boyunca içini aydınlık tutan bir uyku küresi tasarladım. Böylece güçlü ışıklara gerek kalmıyor ve yakınlarda karanlık kör nokta kalmaması sağlanıyor."
  },
