  AvgCommunicate_67023_Content_1 = {
    Text = "Koruyucu, son zamanlarda sürekli gözlerimin önünde garip noktalar görüyorum ve hep başım dönüyor, çarpıntım var, göğsüm sıkışıyor, kulaklarım çınlıyor... Ölecek miyim?!"
  },
  AvgCommunicate_67023_Content_10 = {
