    Text = "Üstelik iyi eğitilmiş askeri köpekler, askerlere çeşitli görevlerde büyük yardım sağlayabilir. Belki bunu müfettiş görevlerine eklemeyi düşünebiliriz."
  },
  AvgCommunicate_67026_Content_11 = {
    Text = "Köpekler... Çok güzel olurdu..."
  },
  AvgCommunicate_67026_Content_12 = {
    Text = "Yani bu seni eğitim derslerine gelmeye daha istekli kılar mı?"
  },
  AvgCommunicate_67026_Content_13 = {
    Text = "Kesinlikle, Eğitmen Alva!"
  },
  AvgCommunicate_67026_Content_2 = {
    Text = "Önerim: Eğitim harikaydı! Daha fazla eğitime gerek yok..."
  },
  AvgCommunicate_67026_Content_3 = {
    Text = "Eğitim çok mu zordu?"
  },
  AvgCommunicate_67026_Content_4 = {
    Text = "Şaka yapıyordum. Sadece eğitimi çok sıkıcı buluyorum. Hiç motivasyonum yok..."
  },
  AvgCommunicate_67026_Content_5 = {
    Text = "Anlıyorum. Görünüşe göre asıl sorun ilgiyle ilgili."
  },
  AvgCommunicate_67026_Content_6 = {
    Text = "Bunu düşününce aklıma bir fikir geldi. Askeri köpekleri eğitim programına dahil etsek insanlar daha motive olur mu acaba?"
  },
  AvgCommunicate_67026_Content_7 = {
    Text = "Askeri köpekler mi? Yani derste yanınızda köpekler mi oluyor?"
  },
  AvgCommunicate_67026_Content_8 = {
    Text = "Evet. Aslında orduda yaygın olarak kullanılan bir yöntem. Askerler yanlarında bir köpek olduğunda kendilerini daha iyi hissediyorlar."
  },
  AvgCommunicate_67026_Content_9 = {
