  },
  AvgCommunicate_67027_Content_1 = {
    Text = "Koruyucu, neden artık Mythag'dan kimse dileklerini yerine getirmemi istemiyor?"
  },
  AvgCommunicate_67027_Content_10 = {
    Text = "İnsanlar dileklerinin doğrudan gerçekleşmesini istemek yerine, hayal edecek bir şey istiyorlar; dört gözle bekleyecek bir şey."
  },
  AvgCommunicate_67027_Content_11 = {
    Text = "Dilekleri hemen gerçekleşmese bile, bir şey dilemenin kendisi onlara teselli verebiliyor."
  },
  AvgCommunicate_67027_Content_12 = {
    Text = "Hemen gerçekleştirilemeyen dilekler... gerçekten o kadar değerli mi?"
  },
  AvgCommunicate_67027_Content_13 = {
    Text = "Sanırım şimdi anlıyorum. Yarından itibaren okulun çeşmesinde herkese Kutsama vereceğim."
  },
  AvgCommunicate_67027_Content_14 = {
    Text = "Dur, neden okul çeşmesi?"
  },
  AvgCommunicate_67027_Content_15 = {
    Text = "Dilek kuyularının birçok yerde popüler olduğunu duydum, bu yüzden okul çeşmesini bir dilek kuyusuna dönüştürürsem herkes gelip Kutsama isteyebilir."
  },
  AvgCommunicate_67027_Content_16 = {
    Text = "Mantığını anlıyorum ama biraz tuhaf!"
  },
  AvgCommunicate_67027_Content_2 = {
    Text = "Hmm... Sanırım Mythag'daki insanlar pragmatik olduğu için."
  },
  AvgCommunicate_67027_Content_3 = {
    Text = "Her gün sayısız tehlikeyle yüzleşerek ruhları, onları kurtarması için dilek dilemeye bel bağlamayacak kadar dayanıklı hale geldi."
  },
  AvgCommunicate_67027_Content_4 = {
    Text = "...Görünüşe göre hâlâ çok işe yaramazım."
  },
  AvgCommunicate_67027_Content_5 = {
    Text = "Hayır, hayır! Herkes tamamen bir şeyler dilemekten vazgeçmiş değil ki."
  },
  AvgCommunicate_67027_Content_6 = {
    Text = "Daha çok dilekleri soyutlaştı; uzun vadeli oldu."
  },
  AvgCommunicate_67027_Content_7 = {Text = "Öyle mi?"},
  AvgCommunicate_67027_Content_8 = {
    Text = "Anlamıyorum. Soyut derken ne demek istiyorsun?"
