  },
  AvgCommunicate_67028_Content_1 = {
    Text = "Merhaba, {Male=Mr.,Female=Miss} Koruyucu. Bunca zaman sonra seni tekrar rahatsız ettiğim için özür dilerim."
  },
  AvgCommunicate_67028_Content_10 = {
    Text = "Harika. Uygun bir zamanda uğrarım."
  },
  AvgCommunicate_67028_Content_11 = {
    Text = "Ah, bir de şimdilik Lily'den gizli tutalım. Ona sürpriz yapmak istiyorum."
  },
  AvgCommunicate_67028_Content_2 = {
    Text = "Beklenmedik bir şekilde iki güzel kırmızı Japon balığı edindim."
  },
  AvgCommunicate_67028_Content_3 = {
    Text = "Neyse ki, bakımım altında başarıyla birçok yumurta bıraktılar. O yumurtalardan sayısız küçük balık çıktı."
  },
  AvgCommunicate_67028_Content_4 = {
    Text = "Bu harika. Doğru hatırlıyorsam, balıkları çok seviyorsun değil mi?"
  },
  AvgCommunicate_67028_Content_5 = {
    Text = "Gerçekten öyle. Su altı dünyasına derin bir bağlılığım var."
  },
  AvgCommunicate_67028_Content_6 = {
    Text = "Sudaki balıklar, denizotları ve mercanlar, Hafızamda sıcak, ev gibi bir yer."
  },
  AvgCommunicate_67028_Content_7 = {
    Text = "Pardon, konudan saptım. Japon balıklarının bir kısmına bakıp bakamayacağını sormak istemiştim."
  },
  AvgCommunicate_67028_Content_8 = {
    Text = "Kuyruk yüzgeçlerini suda sallamaları çok tatlı. Bence Lily onlara bayılır."
  },
  AvgCommunicate_67028_Content_9 = {
    Text = "Tabii! İkimizin de odasına birkaç tane koyabiliriz."
  },
  AvgCommunicate_67028_Option_4 = {
    Text = "Bu harika. Doğru hatırlıyorsam, balıkları çok seviyorsun değil mi?"
  },
  AvgCommunicate_67028_Option_9 = {
    Text = "Tabii! İkimizin de odasına birkaç tane koyabiliriz."
  },
  AvgCommunicate_67029_Content_1 = {
    Text = "Aman Tanrım, Koruyucu, beni mi arıyordun?"
  },
  AvgCommunicate_67029_Content_10 = {
    Text = "Bu yüzden Casiah'ın harika bir fikri oldu: hayvanları araştıralım! Bu çok daha kolay!"
  },
  AvgCommunicate_67029_Content_11 = {
    Text = "...Peki tavuklar şu an nerede?"
  },
  AvgCommunicate_67029_Content_12 = {
    Text = "Casiah'ın odasında, yeni yumurtadan çıkmış bir sürü civciv serbestçe dolaşıyor! Odam çok canlı oldu!"
  },
  AvgCommunicate_67029_Content_13 = {
    Text = "O tavukları hemen yemekhaneye geri götür!!"
  },
  AvgCommunicate_67029_Content_14 = {
    Text = "Ne kadar acımasızsın Koruyucu! Bu civcivleri annelerinden ayırmak istiyorsun! Anne sevgisini unuttun mu?!"
  },
  AvgCommunicate_67029_Content_15 = {
    Text = "Bir sürü tavuğa karşı anne sevgisi hissetmeyeceğim!"
  },
  AvgCommunicate_67029_Content_16 = {
    Text = "Ve senin gibi biri tarafından kalpsiz olarak anılmayacağım!"
  },
  AvgCommunicate_67029_Content_2 = {
    Text = "Aynen öyle. Casiah, birisi dün okul yemekhanesindeki doğaçlama sihir gösterinden sonra depodan üç tavuk ve yirmi yumurtanın kaybolduğunu bildirdi."
  },
  AvgCommunicate_67029_Content_3 = {
    Text = "Neee~? Bu nasıl olmuş olabilir ki? Casiah gerçekten şaşkın."
  },
  AvgCommunicate_67029_Content_4 = {
    Text = "Numaraya son ver! Herkes bir sürü tavuk çıkardığını gördü!"
  },
  AvgCommunicate_67029_Content_5 = {
    Text = "Ah, sanırım öyle bir şey OLDU... Belki o tavuklar kendi başlarına uçup gitmiştir?"
  },
  AvgCommunicate_67029_Content_6 = {
    Text = "Ya da belki gizemli şapka boyutunda bir yerlerde sıkışıp kalmışlardır! Ne üzücü..."
  },
  AvgCommunicate_67029_Content_7 = {
    Text = "Casiah, yalan söylemeye devam edersen, Leydi Nergis'e çalışanının Mythag mülkünü çaldığını söylerim."
  },
  AvgCommunicate_67029_Content_8 = {
    Text = "Tamam tamam, peki! Sen ve o kıt mizah anlayışın!"
  },
  AvgCommunicate_67029_Content_9 = {
