  AvgCommunicate_67030_Content_1 = {
    Text = "Ah, Efendim, sence Karen'ın özenle hazırladığı küçük kekler neden hiç satılmıyor?"
  },
  AvgCommunicate_67030_Content_10 = {
    Text = "Burada farklı zevkleri olan kişi sensin!!"
  },
  AvgCommunicate_67030_Content_11 = {
    Text = "Ah, iş kurmak çok zor. Görünüşe göre farklı bir şey satmam gerekiyor. Bu sefer içecek yapmaya ne dersiniz?"
  },
  AvgCommunicate_67030_Content_12 = {
    Text = "Dur artık, yaratımlarınla herkese eziyet etmeyi bırak!!!"
  },
  AvgCommunicate_67030_Content_2 = {
    Text = "Geçen sefer kampüste tezgâh açtığımızda Murphy onları yere tükürdü bile. Yeterince hızlı kaçmasaydım beni dövecekti!"
  },
  AvgCommunicate_67030_Content_3 = {
