  AvgCommunicate_67031_Content_12 = {
    Text = "Okuyamı—Temel dil dersini görmezden mi geliyorsun?!"
  },
  AvgCommunicate_67031_Content_13 = {
    Text = "Ahh, bunların hepsi çok sinir bozucu! Labirentin efendisi neden ders çalışmak zorunda ki!"
  },
  AvgCommunicate_67031_Content_14 = {
    Text = "Çabuk bana hizmet edecek köleler bulun!"
