  AvgCommunicate_67031_Content_15 = {
    Text = "Uyan prenses. Roma çoktan yıkıldı."
  },
  AvgCommunicate_67031_Content_16 = {
    Text = "Toplumumuzda artık hükümdarlar ve köleler yok!"
  },
  AvgCommunicate_67031_Content_17 = {
    Text = "Umurumda değil! Bana kimseyi getiremiyorsan, o zaman sen hizmet etmelisin!"
  },
  AvgCommunicate_67031_Content_18 = {
    Text = "O zaman dişlerini sabunla fırçalamaya devam et bence."
  },
  AvgCommunicate_67031_Content_19 = {
    Text = "Seni labirente atıp yavrularıma yem ederim!!!"
