  },
  AvgCommunicate_67031_Content_3 = {
    Text = "Diş macununun uzun tüpten çıktığını, küçük kutudan değil, sen söylemedin mi?"
  },
  AvgCommunicate_67031_Content_4 = {
    Text = "Uzun tüpü kullandım ve şimdi ağzım yanıyor! Çok acı ve çok yakıcı!!"
