  AvgCommunicate_67032_Content_1 = {
    Text = "Ah yavrum, Kara Havuz çok soğuk. Hayatımın yavaşça tükendiğini hissedebiliyorum."
  },
  AvgCommunicate_67032_Content_10 = {
    Text = "Hmm... Ya beni hapseden cihazı biraz gevşetmeyi başardığımı söylersem?"
