  AvgCommunicate_67032_Option_9 = {
    Text = "Ne düşünüyorsun?"
  },
  AvgCommunicate_67033_Content_1 = {
    Text = "Ah, Watson, hayat çok sıkıcı."
  },
  AvgCommunicate_67033_Content_10 = {
    Text = "Yoksa ona gerçekten kaybettiğini söyleme?"
  },
  AvgCommunicate_67033_Content_11 = {
    Text = "Hayır, öyle değil. İkimiz de geri adım atmak istemiyorduk. Bahisler giderek yükseldi ve ikimiz de kızıl gözlü olduk."
  },
  AvgCommunicate_67033_Content_12 = {
    Text = "Sonra heyecanla yaşlı adam bir Gedik gösterdi ve ben de aslında başından beri hile yaptığını Keşfettim."
  },
  AvgCommunicate_67033_Content_13 = {
    Text = "Yani bu süre boyunca bir hileciye karşı galibiyetleri ve mağlubiyetleri eşit mi paylaşıyordun?"
  },
  AvgCommunicate_67033_Content_14 = {
    Text = "Evet, çok hayal kırıklığına uğradım. Daha da sinir bozucu olan şey, yaşlı adam utancından öfkeye kapılıp kavga etmek için üzerime atıldı."
  },
  AvgCommunicate_67033_Content_15 = {
    Text = "Aslında benim de tıpkı kendisi gibi bir hileci olduğumdan şüphelenmiş! Ne büyük hakaret."
  },
  AvgCommunicate_67033_Content_16 = {
    Text = "Sonunda ikimiz de Bahis Fang personeli tarafından dışarı atıldık. Düşmekten hâlâ kıçım ağrıyor. Ne kötü şans."
  },
  AvgCommunicate_67033_Content_17 = {
    Text = "Nedenini bilmiyorum ama bir türlü sempati duyamıyorum..."
  },
  AvgCommunicate_67033_Content_2 = {
    Text = "? Yine kumara gitmişsindir. Yine herkesin donunu mu aldın?"
  },
  AvgCommunicate_67033_Content_3 = {
    Text = "Bu sefer değil, gerçekten! Sadece her zamanki gibi biraz eğlenmek için Bahis Fang'ına gidecektim... öhöm."
  },
  AvgCommunicate_67033_Content_4 = {
    Text = "Sorun değil, devam et."
  },
  AvgCommunicate_67033_Content_5 = {
    Text = "Bahanelerinin geri kalanını da duyayım."
  },
  AvgCommunicate_67033_Content_6 = {
    Text = "Ah, sonra bugün aniden benimle eşit düzeyde boy ölçüşebilen bir Rakiple karşılaştım."
  },
  AvgCommunicate_67033_Content_7 = {
    Text = "O masaya katıldıktan sonra, o gösterişsiz yaşlı adamla galibiyetlerde ve mağlubiyetlerde Neredeyse eşit kaldım."
  },
  AvgCommunicate_67033_Content_8 = {
    Text = "Bu gerçekten şaşırtıcı. Senin şansını yenebilmek için gerçek bir uzman olmalı."
  },
  AvgCommunicate_67033_Content_9 = {
    Text = "Ben de tam öyle düşündüm! Bu yüzden tüm odağımı topladım ve onunla kumar oynamaya devam ettim. Hatta dimdik oturdum!"
  },
  AvgCommunicate_67033_Option_10 = {
    Text = "Yoksa ona gerçekten kaybettiğini söyleme?"
  },
  AvgCommunicate_67033_Option_13 = {
    Text = "Yani bu süre boyunca bir hileciye karşı galibiyetleri ve mağlubiyetleri eşit mi paylaşıyordun?"
  },
  AvgCommunicate_67033_Option_17 = {
    Text = "Nedenini bilmiyorum ama bir türlü sempati duyamıyorum..."
  },
  AvgCommunicate_67033_Option_2 = {
