    Text = "Koruyucu, merhaba."
  },
  AvgCommunicate_67034_Content_10 = {
    Text = "Öyle mi? O zaman bu kırık sınav kağıdını nasıl açıklıyorsun? Bu kadar temel konularda hata yapmak— bence doğru cevapları yüz kez yazmalısın."
