  AvgCommunicate_67034_Content_11 = {
    Text = "Yüz kez mi?! Hayır, lütfen... Dur, senin Erica olduğunu unutuyordum az kalsın!"
  },
  AvgCommunicate_67034_Content_12 = {
    Text = "Neden bu kadar gerçekçi Lanet okudun? Bunu bilerek mi yaptın?! Kötü değerlendirme bırakıyorum!!"
