  AvgCommunicate_67034_Content_13 = {Text = "Ramona."},
  AvgCommunicate_67034_Content_14 = {
    Text = "Anlaşıldı. Kişilik simülasyonu şuna geçiriliyor: Ramona."
  },
  AvgCommunicate_67034_Content_15 = {
    Text = "Partner, bir öğretmen az önce bana ödevlerinden birini teslim etmediğini söyledi?"
