  AvgCommunicate_67034_Content_16 = {
    Text = "Ha? Gerçekten mi? Tüm ödevlerimi yaptığımı açıkça hatırlıyorum..."
  },
  AvgCommunicate_67034_Content_17 = {
    Text = "Bu dikkatsiz alışkanlığını ne zaman düzelteceksin?"
  },
  AvgCommunicate_67034_Content_18 = {
    Text = "Boşver. Bundan sonra her gün yurduma gel. Günlük ödevlerini bitirene kadar seni denetleyeceğim, ondan sonra gidebilirsin. Ah, bir de cevap ya da kaynak araması yok."
  },
  AvgCommunicate_67034_Content_19 = {
    Text = "Ne?! Olmaz! Hiçbir kaynak olmadan ödevi nasıl yapayım?!"
  },
  AvgCommunicate_67034_Content_2 = {
    Text = "En yeni simüle edilmiş kişilik sistemini denemeye davetlisiniz. Bu sistem, görevler gerektirdiğinde, müsait olmayan üyeler adına iletişimi taklit edecek, davranış mantıklarını tahmin edecek ve daha fazlasını yapacaktır."
  },
  AvgCommunicate_67034_Content_20 = {
