  AvgCommunicate_67035_Content_3 = {
    Text = "Hadi ama, bu sefer gerçekten Oda Kapınızın yanında değildim!"
  },
  AvgCommunicate_67035_Content_4 = {
    Text = "Geçen seferki yardımınız sayesinde, eğitim odasındaki kum torbasının içinde uzun süre mutlu bir şekilde dayak yedim. Evdeymiş gibi hissettim—daha önce hiç bu kadar mutlu olmamıştım."
