    Text = "A-ama Leydi Pandia'ya söz verdim. Sözümden dönemem."
  },
  AvgCommunicate_67041_Content_13 = {
    Text = "Sorun değil, efendim. Kendimi koruyacak Güce sahibim!"
  },
  AvgCommunicate_67041_Content_14 = {
    Text = "Sen, ben... Boşver. Orada dikilmekte ısrar ediyorsan, bunu kaydet—asla onun Odasına girme."
  },
  AvgCommunicate_67041_Content_15 = {
    Text = "Tabii ki! Bir hanımefendinin Odasına asla girmem!"
  },
  AvgCommunicate_67041_Content_16 = {
    Text = "Ne derse desin, içeri girme. Bir şey olursa beni Çağır. Ha, bir de ne yaparsan yap, mumlarını koklama!"
  },
  AvgCommunicate_67041_Content_17 = {
    Text = "Bunu aklımda tutacağım, efendim. Ama mumları neden koklayamıyorum?"
  },
  AvgCommunicate_67041_Content_18 = {
    Text = "Sorma... Bunlar senin adına Kanımla ve gözyaşlarımla ödenen zor dersler..."
  },
  AvgCommunicate_67041_Content_2 = {
    Text = "Evet, doğru. Neden Pandia'nın Kapısı'nın önünde duruyorsun??"
  },
  AvgCommunicate_67041_Content_3 = {
    Text = "Ah, Pandia benden bunu yapmamı istedi. Çok önemli bir işi olduğunu söyledi ve kapısının Koruyucusu olmamı istedi."
  },
  AvgCommunicate_67041_Content_4 = {
