  },
  AvgCommunicate_67041_Content_5 = {
    Text = "Ha? Ama az önceki İfadesi çok ciddiydi ve elimi içtenlikle tutuyordu..."
  },
  AvgCommunicate_67041_Content_6 = {
    Text = "Tahmin edeyim—elini tuttu ve seni en güvenilir ve nazik Şövalye olarak adlandırdı."
  },
  AvgCommunicate_67041_Content_7 = {
    Text = "Bunu nasıl bildiniz, efendim?!"
  },
  AvgCommunicate_67041_Content_8 = {
