  AvgCommunicate_67042_Content_12 = {
    Text = "Aşk mumunu al ve benimle güzel vakit geçirmeye gel~"
  },
  AvgCommunicate_67042_Content_13 = {
    Text = "Beni kandırdın..."
  },
  AvgCommunicate_67042_Content_14 = {
    Text = "Nasıl olabilir ki? Bu karşılıklı rızaya dayanan tatlı bir sözleşme."
