  AvgCommunicate_67042_Content_3 = {
    Text = "O zaman gel, yurdun alt katındaki çöp kutusuna geri dönüştür."
  },
  AvgCommunicate_67042_Content_4 = {
    Text = "Bu kadar kalpsiz olma! En azından bir bak, sadece bir göz at!"
  },
  AvgCommunicate_67042_Content_5 = {
    Text = "Kapının önünün her gün hediyelerimle dolmasını istemezsin, değil mi?"
  },
  AvgCommunicate_67042_Content_6 = {
