  },
  AvgCommunicate_67042_Content_9 = {
    Text = "Nasıl? Bir kokla—güzel kokmuyor mu, tekrar tekrar koklamak istemiyor musun..."
  },
  AvgCommunicate_67042_Option_10 = {
    Text = "Güzel kokuyor gerçekten, çok eşsiz bir koku, ama neden biraz başım dönüyor..."
  },
  AvgCommunicate_67042_Option_13 = {
    Text = "Beni kandırdın..."
  },
  AvgCommunicate_67042_Option_2 = {
    Text = "Kapının önündeki sadece alıcı adı yazılı şu tuhaf kutuyu mu kastediyorsun?"
