  AvgCommunicate_67042_Option_6 = {
    Text = "Tamam, bir bakayım, sonra gelip çöpten alırsın."
  },
  AvgCommunicate_67043_Content_1 = {
    Text = "Mythag'da bu kadar uzun zaman geçirdikten sonra, birden çölün üzerindeki ayı özlediğimi fark ettim."
  },
  AvgCommunicate_67043_Content_10 = {
    Text = "Gel, birlikte yeni anılar yaratalım — çiçeklerin arasında, açık tarlalarda, Derin Deniz'i ve vadileri, şehirleri ve kırsalı görmek için."
  },
  AvgCommunicate_67043_Content_11 = {
    Text = "Her güzel yerde bize ait anılar bırakmak istiyorum. Yanımda kalacaksın, değil mi?"
  },
  AvgCommunicate_67043_Content_2 = {
    Text = "Demek sen de yurt özlemi çekiyorsun?"
  },
  AvgCommunicate_67043_Content_3 = {
    Text = "Yurt özleminden ziyade, belki de bir zamanlar insanlarla paylaştığım anıları — o yoğun duyguları hatırlıyorumdur."
  },
  AvgCommunicate_67043_Content_4 = {
    Text = "Bu kadar duygusal olmanı beklemiyordum."
  },
  AvgCommunicate_67043_Content_5 = {
    Text = "Ne? Kaygısız ve duygusuz biri olduğumu mu düşünüyorsun? Hayır, her insanı, her sıcak ve tatlı anıyı hatırlıyorum."
  },
  AvgCommunicate_67043_Content_6 = {
    Text = "Seninle olanlar da dahil."
  },
  AvgCommunicate_67043_Content_7 = {
    Text = "Onur mu duymalıyım yoksa kıskanmalı mıyım?"
  },
  AvgCommunicate_67043_Content_8 = {
    Text = "Seni böyle telaşlı görmek çok hoşuma gidiyor. Ne kadar tatlısın."
  },
  AvgCommunicate_67043_Content_9 = {
    Text = "Eski günler tadını çıkarmaya değer olsa da, bu gecenin neşesi hepsinden daha kıymetli."
  },
  AvgCommunicate_67043_Option_2 = {
    Text = "Demek sen de yurt özlemi çekiyorsun?"
  },
  AvgCommunicate_67043_Option_4 = {
    Text = "Bu kadar duygusal olmanı beklemiyordum."
  },
  AvgCommunicate_67043_Option_7 = {
    Text = "Onur mu duymalıyım yoksa kıskanmalı mıyım?"
  },
  AvgCommunicate_67044_Content_1 = {
    Text = "Son zamanlarda koleksiyonumu süslemek için bir dizi aksesuar tasarlıyorum."
  },
  AvgCommunicate_67044_Content_10 = {
    Text = "İstersen, özenle seçtiğim bu kolyeler senin olsun. Bu sefer hediyem."
  },
  AvgCommunicate_67044_Content_11 = {
    Text = "Denedikten sonra beğendiğin birini bulursan, lütfen bana mutlaka haber ver."
  },
  AvgCommunicate_67044_Content_12 = {
    Text = "Kafatasın henüz bana ait olmasa bile, onu taktığını görmek bile beni mutlu etmeye yeter."
  },
  AvgCommunicate_67044_Content_2 = {
    Text = "Seçebileceğim epey fazla stil var ve karar vermekte zorlanıyorum, bu yüzden senin tavsiyeni almak istedim."
  },
  AvgCommunicate_67044_Content_3 = {
    Text = "Koleksiyon mu?"
  },
  AvgCommunicate_67044_Content_4 = {
    Text = "Demek istemiyorsun ki..."
  },
  AvgCommunicate_67044_Content_5 = {
    Text = "Ah, değerli kafataslarım tabii ki."
  },
  AvgCommunicate_67044_Content_6 = {
    Text = "Birçok moda dergisine ve mücevher mağazası tasarımlarına göz attım."
  },
  AvgCommunicate_67044_Content_7 = {
    Text = "Her türlü kolyenin kendine has bir çekiciliği var, hatta niş choker stilleri bile mevcut. Çok zor bir seçim."
  },
  AvgCommunicate_67044_Content_8 = {
    Text = "Hmm... Bence koleksiyonun en benzersiz aksesuarları hak ediyor."
  },
  AvgCommunicate_67044_Content_9 = {
    Text = "Gerçekten mi? Bunu söylemeni duymak beni çok mutlu etti."
