  },
  AvgCommunicate_67045_Content_11 = {
    Text = "Fena bir öneri değil, ama onun gibi kurnaz birini kandırmak kolay değil."
  },
  AvgCommunicate_67045_Content_12 = {
    Text = "Düşününce, o tuhaf kafası Koleksiyonuma eklemeye oldukça değer. Ne yazık ki takas için bir fırsat yok. Ne üzücü."
  },
  AvgCommunicate_67045_Content_13 = {
    Text = "Umarım Ryker şu an hapşırmıyordur..."
  },
  AvgCommunicate_67045_Content_2 = {
    Text = "Hmm... Kafalar gerçekten alışverişe çıkıp bulabileceğin şeyler değil."
  },
  AvgCommunicate_67045_Content_3 = {
    Text = "Bu yüzden son zamanlarda Komite ile bir iş birliği kurdum. Onların kaçakları izlemesine yardım ediyorum, karşılığında bana idam edilen suçluların kafalarını gizlice sağlıyorlar."
  },
  AvgCommunicate_67045_Content_4 = {
    Text = "Bir yaşayan kişi karşılığında ölü bir kişinin kafası—her iki taraf için de iyi bir anlaşma."
