  },
  AvgCommunicate_67045_Content_6 = {
    Text = "Tabii ki resmi bir iş birliği değil, ama her yerde her zaman zeki insanlar bulunur."
  },
  AvgCommunicate_67045_Content_7 = {
    Text = "Londinium polisiyle de iletişime geçmeyi denedim ama onlar o köpek kafalı dedektife daha çok güveniyorlar."
  },
  AvgCommunicate_67045_Content_8 = {
