  AvgCommunicate_70487_Content_10 = {Text = "..."},
  AvgCommunicate_70487_Content_11 = {
    Text = "Ondan hoşlanmıyorum ve senden de hoşlanmıyorum. Ama o kendini beğenmiş Kar Dağı'ndan ve beni kullanmak ya da bana ihanet etmek isteyenlerden daha çok nefret ediyorum."
  },
  AvgCommunicate_70487_Content_12 = {
    Text = "Hepsi bu kadar."
  },
  AvgCommunicate_70487_Content_2 = {
    Text = "Kar Dağı'ndan döndükten sonra tedavi gördü ve yaraları çok iyi iyileşti."
  },
  AvgCommunicate_70487_Content_3 = {
    Text = "Kar Dağı'nı senin diğer versiyonundan duydum."
  },
  AvgCommunicate_70487_Content_4 = {
