  },
  AvgCommunicate_70492_Content_1 = {
    Text = "Yakında bir anma töreni düzenlemeyi planlıyorum, ancak canlı balık ve tekne konusunda biraz sıkıntım var."
  },
  AvgCommunicate_70492_Content_10 = {
