  AvgCommunicate_70493_Content_10 = {
    Text = "Hafızam Çözünme’ye uğrayacağı güne dek... senin yaptıklarını başkalarına da gururla Anlatacağım."
  },
  AvgCommunicate_70493_Content_11 = {
    Text = "Ama vasiyetini okurken, şu an, pişmanlık tüm düşüncelerimi ele geçiriyor."
  },
  AvgCommunicate_70493_Content_12 = {
