    Text = "Anderson'ın kalıntıları Heykeltıraşlar üyeleri tarafından tahrip edildi, bu yüzden eksiksiz bir insan figürü bir araya getirmek imkânsız hale geldi."
  },
  AvgCommunicate_70495_Content_10 = {
    Text = "Belki, bir gün biz de..."
  },
  AvgCommunicate_70495_Content_11 = {
    Text = "Dehşet hissedecek misin, Kıdemli William?"
  },
  AvgCommunicate_70495_Content_12 = {Text = "..."},
  AvgCommunicate_70495_Content_13 = {
    Text = "Belki bazı insanlar yaşamı ve ölümü aşabilir, ama ben değil."
  },
  AvgCommunicate_70495_Content_14 = {
    Text = "Ben her an dehşet içindeyim, %player%."
  },
  AvgCommunicate_70495_Content_15 = {
    Text = "Ama sende en ufak bir dehşet izi bile görmedim."
  },
  AvgCommunicate_70495_Content_16 = {
    Text = "Çünkü zamanım yok. Çünkü Çözünme tam karşımda."
  },
  AvgCommunicate_70495_Content_17 = {
    Text = "Nice kişi can verdi, ama ben hâlâ yaşıyorum."
  },
  AvgCommunicate_70495_Content_18 = {
    Text = "İster korku ister anma olsun, bir Mythag Müfettişinin bunun için durmaya hakkı yoktur."
  },
  AvgCommunicate_70495_Content_19 = {Text = "..."},
  AvgCommunicate_70495_Content_2 = {
    Text = "Zorla çıkarılan o Gümüşler de neredeyse tamamen yok edildi."
  },
  AvgCommunicate_70495_Content_20 = {
    Text = "Yeni bir görev geldi."
  },
  AvgCommunicate_70495_Content_21 = {
    Text = "Hayatta kalacağız, %player%. Çözünme çözümlenene dek."
  },
  AvgCommunicate_70495_Content_3 = {
    Text = "Atölyedeki laboratuvarı aradık ve yalnızca bunu bulduk."
  },
  AvgCommunicate_70495_Content_4 = {
    Text = "Gümüş Anahtar, Kimlik L-1463, Müfettiş Anderson'a ait—bir zamanlar ona aitti."
  },
  AvgCommunicate_70495_Content_5 = {
    Text = "Okul bu Gümüş Anahtar'ı ne yapacak...?"
  },
  AvgCommunicate_70495_Content_6 = {
    Text = "Geri dönüştürecek, yeniden şekillendirmek için Kara Havuz'a koyacak ve ardından gelecek yılki Anahtar Gömme Töreni'nde yeni Müfettişlere dağıtacak."
  },
  AvgCommunicate_70495_Content_7 = {
    Text = "Yeni Müfettişe eşlik edecek, sürekli en tehlikeli yerlere gidecek."
  },
  AvgCommunicate_70495_Content_8 = {
    Text = "O Müfettiş istifa edene ya da ölünceye kadar."
  },
  AvgCommunicate_70495_Content_9 = {
    Text = "Belki, bir gün biz de..."
  },
  AvgCommunicate_70495_Option_10 = {
    Text = "Dehşet hissedecek misin?"
  },
  AvgCommunicate_70495_Option_15 = {
    Text = "Senin dehşetini hiç hissetmedim."
  },
  AvgCommunicate_70495_Option_5 = {
    Text = "Okul bu Gümüş Anahtar'ı ne yapacak...?"
  },
  AvgCommunicate_70495_Option_9 = {
    Text = "Sonumuz Anderson gibi mi olacak?"
  },
  AvgCommunicate_70496_Content_1 = {
    Text = "Bu Aram halkının ayini... gerçekten de sarsıcı."
  },
  AvgCommunicate_70496_Content_10 = {
    Text = "Ben öyle biri miyim?"
  },
  AvgCommunicate_70496_Content_11 = {
    Text = "Sadece sordum, neden bu kadar gerginsin?"
  },
  AvgCommunicate_70496_Content_12 = {
    Text = "Böyle davranırsan kart masasında açık kitap gibi olursun. Zihinsel dayanıklılığını geliştirmen gerekiyor, {Male=Mr.,Female=Miss} Koruyucu."
  },
  AvgCommunicate_70496_Content_13 = {
    Text = "Kısacası, bu çölün sırları muhtemelen öngördüğümüzden çok daha karmaşık."
  },
  AvgCommunicate_70496_Content_14 = {
    Text = "Sonraki soruşturma fazlasında ekstra dikkat gerekecek."
  },
  AvgCommunicate_70496_Content_2 = {
    Text = "Aram kadınının davetini kabul edeceğini sanmıştım."
  },
  AvgCommunicate_70496_Content_3 = {Text = "..."},
  AvgCommunicate_70496_Content_4 = {
    Text = "Kalbinde benim nasıl bir suretim var, aslında merak ediyorum..."
  },
  AvgCommunicate_70496_Content_5 = {
    Text = "Genelde bu kadar büyüleyici olan Ryker'ın da kabullenemeyeceği şeyler olacağını hiç beklemezdim."
  },
  AvgCommunicate_70496_Content_6 = {
    Text = "Ne çiçekli ne şaraplı hikâyeler var; yalnızca en ilkel ve en vahşi arzular."
  },
  AvgCommunicate_70496_Content_7 = {
    Text = "Bu tür ayinler gerçekten de bana göre değil."
  },
  AvgCommunicate_70496_Content_8 = {
    Text = "Bu arada, tuhaf bir daveti kabul etmedin, değil mi?"
  },
  AvgCommunicate_70496_Content_9 = {
    Text = "N- tabii ki hayır... nasıl kabul edebilirim ki!"
  },
  AvgCommunicate_70496_Option_2 = {
    Text = "O Aram kadınının davetini kabul edeceğini sanmıştım."
  },
  AvgCommunicate_70496_Option_5 = {
    Text = "Senin de kabullenemeyeceğin şeyler olacağını hiç beklemezdim."
  },
  AvgCommunicate_70496_Option_9 = {
    Text = "N- tabii ki hayır... nasıl kabul edebilirim ki!"
  },
  AvgCommunicate_70497_Content_1 = {
    Text = "Merhaba, {Male=Bay,Female=Bayan} Koruyucu."
  },
  AvgCommunicate_70497_Content_2 = {
    Text = "Juliette’in oyuncaklarıyla oynarken eğlendin mi?"
  },
  AvgCommunicate_70497_Content_3 = {
    Text = "Sen... köstebek misin?!"
  },
  AvgCommunicate_70497_Content_4 = {
    Text = "Kim olduğumu daha erken anlayacağını sanmıştım. Ne yazık."
  },
  AvgCommunicate_70497_Content_5 = {
    Text = "Ama sorun değil; sonuçta bu sadece son oyun."
  },
  AvgCommunicate_70497_Content_6 = {
    Text = "Artık oyun bitmek üzere."
  },
  AvgCommunicate_70497_Content_7 = {
    Text = "Kaderde yazılı Yıkım gelmeden önce, merak ettiğim tek bir şey var."
  },
  AvgCommunicate_70497_Content_8 = {
    Text = "Kaos'un ebedi hakikati—utanmadan bahsettiğimiz cesur Koruyucu, Mythag'ın yiğit Kurtarıcısı—bununla gerçekten cesaretle yüzleşebilir mi?"
  },
  AvgCommunicate_70497_Option_3 = {
    Text = "Sen... köstebek misin?!"
  },
  AvgCommunicate_70498_Content_1 = {
    Text = "Ben aptal bir tüccar değilim, ama dikkatlice düşününce, zararlı bir anlaşma yaptığım anlaşılıyor…"
  },
  AvgCommunicate_70498_Content_10 = {
    Text = "Yalanlara karşı her zaman tetikte olmak, nitelikli bir iş kadınının temel özelliğidir."
  },
  AvgCommunicate_70498_Content_11 = {
    Text = "Peki... bu gerçekten Leydi Nergis'in gerçek yüzü mü?"
  },
  AvgCommunicate_70498_Content_12 = {
    Text = "Gerçeklikten daha pahalı bir bedel yoktur, küçük {Male=Mr.,Female=Miss} Koruyucu."
  },
  AvgCommunicate_70498_Content_13 = {
    Text = "Teşekkür ederim, Leydi Nergis."
  },
  AvgCommunicate_70498_Content_14 = {
    Text = "Az önce söylediklerim bir şakaydı. Senin gibi biri için gerçek benliğini açığa vurmanın ne anlama geldiğini biliyorum."
  },
  AvgCommunicate_70498_Content_15 = {
    Text = "Bu değerli bir hediye, onu iyi saklayacağım."
  },
  AvgCommunicate_70498_Content_16 = {
    Text = "Beni birkaç kelimeyle başından savabileceğini sanma, ufaklık."
  },
  AvgCommunicate_70498_Content_17 = {
    Text = "Karşılığında, senin de bana bir Hediye vermen gerekmez mi?"
  },
  AvgCommunicate_70498_Content_18 = {
    Text = "Yoksa çözüldüm mü...?"
  },
  AvgCommunicate_70498_Content_19 = {
    Text = "Leydi Nergis, ne istersiniz?"
  },
  AvgCommunicate_70498_Content_2 = {Text = "?"},
  AvgCommunicate_70498_Content_20 = {
    Text = "Madem gerçek hâlimi gördün, bana kendi gerçek benliğini ne zaman göstereceksin?"
  },
  AvgCommunicate_70498_Content_21 = {
    Text = "Gerçek benliğim mi? Ne demek istiyorsunuz... Pek anlayamadım, Leydi Nergis."
  },
  AvgCommunicate_70498_Content_22 = {
    Text = "Görünüşe göre Mythag sana henüz hiçbir şey söylememiş..."
  },
  AvgCommunicate_70498_Content_23 = {
    Text = "Zamanı henüz gelmedi. Endişelenme."
  },
  AvgCommunicate_70498_Content_24 = {
    Text = "Bugünkü anlaşmamızı unutma, ufaklık."
  },
  AvgCommunicate_70498_Content_25 = {
    Text = "Gerçek formunu ortaya koyacağın günü dört gözle bekliyorum."
  },
  AvgCommunicate_70498_Content_3 = {
    Text = "Arzuladığın kafayı zaten elde etmedin mi?"
  },
  AvgCommunicate_70498_Content_4 = {
    Text = "O canlı, kıpır kıpır gri madde denizi, koleksiyonundaki bir başka kıymetli parçaya dönüştü."
  },
  AvgCommunicate_70498_Content_5 = {
    Text = "Gerçekten de güzel bir başmış; bu ticaretin tamamen zararlı olduğu söylenemez."
  },
  AvgCommunicate_70498_Content_6 = {
    Text = "Yine de ödediğim bedel hâlâ biraz fazla yüksek."
  },
  AvgCommunicate_70498_Content_7 = {
    Text = "Bana gerçek hâlinden yalnızca bir kesit gösterdin..."
  },
  AvgCommunicate_70498_Content_8 = {
    Text = "Ve bunun gerçekten senin gerçek görünüşün olup olmadığını söylemek zor."
  },
  AvgCommunicate_70498_Content_9 = {
    Text = "Heh heh... Fena değil, küçük olan."
  },
  AvgCommunicate_70498_Option_11 = {
    Text = "Peki... bu gerçekten Leydi Nergis'in gerçek yüzü mü?"
  },
  AvgCommunicate_70498_Option_13 = {
    Text = "Teşekkür ederim, Leydi Nergis."
  },
  AvgCommunicate_70498_Option_18 = {
    Text = "Yoksa çözüldüm mü...?"
  },
  AvgCommunicate_70498_Option_2 = {
    Text = "Başı elde etmedin mi zaten?"
  },
  AvgCommunicate_70498_Option_21 = {
    Text = "Gerçek benliğim mi? Ne demek istiyor bu..."
  },
  AvgCommunicate_70498_Option_7 = {
    Text = "Az önce gerçek hâlinden bir kesit yakaladım sadece..."
  },
  AvgCommunicate_70499_Content_1 = {
    Text = "Muhalifleri ortadan kaldırarak Longbel ve Sözleşme'nin kısıtlarından kendini kurtardı. Bu engeller olmadan, sadece birkaç hafta içinde Londinium'un iş dünyasındaki en azılı avcıya dönüştü."
  },
  AvgCommunicate_70499_Content_10 = {
    Text = "Merak etmeyin, Profesör Dexter. Bir dahaki sefere size böyle tehlikeli şeyler yaptırmayacağız... Yani, en azından yapmamaya çalışacağız."
  },
  AvgCommunicate_70499_Content_11 = {
    Text = "Sorel'in bilincine gizlenmiş varlığın adının \"\"N\"\" olduğu anlaşılıyor. Onun hakkında bir şey biliyor musun?"
  },
  AvgCommunicate_70499_Content_12 = {
    Text = "Pek net değil. Ya bir dolandırıcıya ya da bir deliye benziyor, büyük ihtimalle ikisi birden."
  },
  AvgCommunicate_70499_Content_13 = {
    Text = "Ama ne kadar iğrenç olursa olsun, en azından bu herifin zevki var. Şarkı söyleyişinden anlaşılıyor."
  },
  AvgCommunicate_70499_Content_14 = {
    Text = "Bir dahaki sefere fırsat olursa mutlaka daha iyi tanışmalıyız. Belki bir iki kadeh de paylaşırız."
  },
  AvgCommunicate_70499_Content_15 = {
    Text = "...Tabii ki güvenli bir ortamda. Bu yaşlı kemiklerim artık hiçbir korkuya dayanamaz."
  },
  AvgCommunicate_70499_Content_2 = {
    Text = "Bence çok geçmeden Londinium'un tüm toprakları onun soyadını taşıyacak."
  },
  AvgCommunicate_70499_Content_3 = {
    Text = "Leydi Sorel, ne büyüleyici bir insan. Neyse ki Mythag onun tarafında."
  },
  AvgCommunicate_70499_Content_4 = {
    Text = "Bu meseleyi sizin yardımınıza borçluyum, Profesör Dexter."
  },
  AvgCommunicate_70499_Content_5 = {
    Text = "Şüpheliyi ortaya çıkarmamıza yardım ettiğin için teşekkürler; yoksa bu işi çözmemiz çok daha uzun sürecekti."
  },
  AvgCommunicate_70499_Content_6 = {
    Text = "Sadece bir beyefendinin görevlerini yerine getiriyorum."
  },
  AvgCommunicate_70499_Content_7 = {
    Text = "Bu, Ramona'nın öne sürdüğü bir teklifti. Babası olarak nasıl reddedebilirdim ki?"
  },
  AvgCommunicate_70499_Content_8 = {
    Text = "Yine de, bir dahaki sefere buna benzer bir şey olursa, biraz daha hızlı hareket edebilmeni umuyorum."
  },
  AvgCommunicate_70499_Content_9 = {
    Text = "O herifin bıçağı boynumdan beş santimetre uzaktayken ortaya çıkmayı beklemeyin; gerçekten korkutucu."
  },
  AvgCommunicate_70499_Option_10 = {
    Text = "Bir dahası olmayacak... Elimden geleni yapacağım."
  },
  AvgCommunicate_70499_Option_11 = {
    Text = "\"N\" hakkında bir şey biliyor musun?"
  },
  AvgCommunicate_70499_Option_4 = {
    Text = "Şüpheliyi ortaya çıkarmamıza yardım ettiğiniz için teşekkürler."
  },
  AvgCommunicate_70500_Content_1 = {
    Text = "Kafedeki sohbet oldukça keyifliydi, {Male=Mr.,Female=Miss} Koruyucu."
  },
  AvgCommunicate_70500_Content_10 = {
    Text = "Bu durum tekrar yaşanırsa ve diğerlerini kurtarmak için gerçek beni vurman gerekirse, yapar mısın?"
  },
  AvgCommunicate_70500_Content_11 = {
    Text = "Hımm... elbette."
  },
  AvgCommunicate_70500_Content_12 = {
    Text = "Merak etme, {Male=Mr.,Female=Miss} Koruyucu. Şans yine benden yana olacaktır."
  },
  AvgCommunicate_70500_Content_13 = {
    Text = "O an silahımda kesinlikle mermi olmazdı."
  },
  AvgCommunicate_70500_Content_14 = {
    Text = "Yüzde yetmiş hayır."
  },
  AvgCommunicate_70500_Content_2 = {
    Text = "Bir kumarbazın doğuşuna tanıklık etmek benim için bir onurdu."
  },
  AvgCommunicate_70500_Content_3 = {
    Text = "En sevdiğim kısım, kumarbazın her şeyini kaybedip ruhunun çalındığı andı."
  },
  AvgCommunicate_70500_Content_4 = {
    Text = "Ha... zaferler ve yenilgiler olur; hayat böyledir."
  },
  AvgCommunicate_70500_Content_5 = {
    Text = "Gördün mü? Bu sefer bir eli geri kazandık bile."
  },
  AvgCommunicate_70500_Content_6 = {
    Text = "Peki, bana sıktığın o mermi de bir kumar mıydı?"
  },
  AvgCommunicate_70500_Content_7 = {
    Text = "Bu nasıl olabilir? Kararımdan %70 emindim."
  },
  AvgCommunicate_70500_Content_8 = {
    Text = "Peki ya kalan yüzde otuz?"
  },
  AvgCommunicate_70500_Content_9 = {
    Text = "Kalan %30 diye bir şey yok. %70, %100 demektir."
  },
  AvgCommunicate_70500_Option_2 = {
    Text = "Bir kumarbazın doğuşuna tanıklık etmek onurdu."
  },
  AvgCommunicate_70500_Option_6 = {
    Text = "Peki, bana ateş etmen de bir kumar mıydı?"
  },
  AvgCommunicate_70500_Option_8 = {
    Text = "Peki ya kalan yüzde otuz?"
  },
  AvgCommunicate_70501_Content_1 = {
    Text = "Güzel görünüyor mu?"
  },
  AvgCommunicate_70501_Content_10 = {
    Text = "Ama... o heykel serisinin anlattığı hikâye fazlasıyla acımasız."
  },
  AvgCommunicate_70501_Content_11 = {
    Text = "Anladın demek, Koruyucu..."
