  AvgCommunicate_70501_Content_12 = {
    Text = "Tüm yaratım acımasızdır."
  },
  AvgCommunicate_70501_Content_13 = {
    Text = "Durağan sanat, canlı bir hayat kazanmasını tam da bu acımasızlığa borçludur."
  },
  AvgCommunicate_70501_Content_14 = {
    Text = "Yerinde olsam, böyle bir yaratım sürecini inanılmaz derecede zorlu bulurdum..."
  },
  AvgCommunicate_70501_Content_15 = {
    Text = "Ama sen farklısın, Sanga. Seçimini anlıyorum."
  },
  AvgCommunicate_70501_Content_16 = {
    Text = "\"Bayan Mercan'ın Ölümü\" gibi bir eser, senin peşinden koştuğun anlam."
  },
  AvgCommunicate_70501_Content_17 = {
    Text = "Sabırsızlanıyorum—o \"acımasızlığın\" oyduğun çizgilerde bir kez daha çiçek açmasını görmek için."
  },
  AvgCommunicate_70501_Content_18 = {Text = "..."},
  AvgCommunicate_70501_Content_19 = {
    Text = "O kaba saba insanlar gibi sanatımın daha \"normal\" olmasını önereceğini düşünmüştüm."
  },
  AvgCommunicate_70501_Content_2 = {
    Text = "Ne... yüzüm mü?"
  },
  AvgCommunicate_70501_Content_20 = {
    Text = "Bu sözler benim için çok şey ifade ediyor... Teşekkür ederim, {Male=Mr.,Female=Miss} Koruyucu."
  },
  AvgCommunicate_70501_Content_21 = {
    Text = "Bir ödül olarak sana küçük bir sır vereyim: Morpheus'a girdiğinde tam yanında duruyordum."
  },
  AvgCommunicate_70501_Content_22 = {
    Text = "Tüm o savunmasız ifadelerini—her birini tek tek oydum. Tıpatıp · aynısı."
  },
  AvgCommunicate_70501_Content_23 = {
    Text = "Vaktin olduğunda küçük sergi salonumu ziyarete gel~"
  },
  AvgCommunicate_70501_Content_24 = {
    Text = "Sanga! Sana elli Fang vereceğim, lütfen şu Heykelleri at..."
  },
  AvgCommunicate_70501_Content_25 = {
    Text = "Canlı ama \"acımasız\" dediğin sanat. Öyle değil mi, Koruyucu?"
  },
  AvgCommunicate_70501_Content_3 = {
    Text = "Rüya'da gördüğün heykel, tabii ki."
  },
  AvgCommunicate_70501_Content_4 = {
    Text = "Bedenin hatları doğal bir uyum taşır, ancak durağanlığın ebedi güzelliğinden yoksundur ve tema ile yaratıcı vizyon açısından eksiktir—heykel eserleriyle kıyaslanamaz."
  },
  AvgCommunicate_70501_Content_5 = {
    Text = "Artık çok az kişi o heykel setini görmüş durumda. Senin değerlendirmeni öğrenmek istiyorum..."
  },
  AvgCommunicate_70501_Content_6 = {
    Text = "Ne... senin heykellerin mi?"
  },
  AvgCommunicate_70501_Content_7 = {
    Text = "Elbette. O heykel serisini şu an çok az kişi gördü. Değerlendirmeni merak ediyorum..."
  },
  AvgCommunicate_70501_Content_8 = {
    Text = "Şimdiye kadar gördüğüm en güzel heykel serisi bu."
  },
  AvgCommunicate_70501_Content_9 = {
    Text = "Çizgiler durağan olsa da, canlı varlıkların bile sahip olmadığı bir dinamizmi ve canlılığı yakalıyorlar."
  },
  AvgCommunicate_70501_Option_14 = {
    Text = "Seçimini anlıyorum"
  },
  AvgCommunicate_70501_Option_2 = {
    Text = "Yüzün mü?"
  },
  AvgCommunicate_70501_Option_24 = {Text = "Asla!!!"},
  AvgCommunicate_70501_Option_6 = {
    Text = "Heykellerin mi?"
  },
  AvgCommunicate_70501_Option_8 = {
    Text = "Güzel... ve acımasız."
  },
  AvgCommunicate_70502_Content_1 = {
    Text = "Sıkıcı. Sıkıcı, sıkıcı!"
  },
  AvgCommunicate_70502_Content_10 = {
    Text = "Bana defalarca hatırlattığın gibi, Londinium'da kölelik yasak. Bu barbar diyar..."
  },
  AvgCommunicate_70502_Content_11 = {
    Text = "Seni dinlemekten ve onlara sadece labirentin içinde emir vermekten başka çarem yok."
  },
  AvgCommunicate_70502_Content_12 = {
    Text = "Arenada dövüşme şekilleri tam hatırladığım gibi!"
  },
  AvgCommunicate_70502_Content_13 = {
    Text = "Demek Labirent bunun için kullanılıyor..."
  },
  AvgCommunicate_70502_Content_14 = {
    Text = "Aynen öyle, aynen öyle! Gerçekten heyecan verici!"
  },
  AvgCommunicate_70502_Content_15 = {
    Text = "Hadi, gidip izleyelim! Bu sana bahşedebileceğim en büyük onur!"
  },
  AvgCommunicate_70502_Content_16 = {
    Text = "Tabii, neden olmasın? Tarih hakkında daha fazla şey öğrenmek güzel olurdu..."
  },
  AvgCommunicate_70502_Content_17 = {
    Text = "Uvhash muhtemelen arenanı çok beğenirdi. Onu da davet etmeye ne dersin?"
  },
  AvgCommunicate_70502_Content_18 = {
    Text = "Hayır! O şeytanı uzak tut!!!"
