  AvgCommunicate_80102_Content_11 = {
    Text = "...Gerçekten mi?"
  },
  AvgCommunicate_80102_Content_12 = {
    Text = "Tabii ki. Sonuçta ben sadece bir psikoloğum."
  },
  AvgCommunicate_80102_Content_2 = {
    Text = "Bence senin kişisel bir psikiyatriste ihtiyacın var."
  },
  AvgCommunicate_80102_Content_3 = {
    Text = "...Bunun gereksiz olduğunu hissediyorum."
  },
  AvgCommunicate_80102_Content_4 = {
