  AvgCommunicate_80102_Option_6 = {
    Text = "...Öyle mi?"
  },
  AvgCommunicate_80104_Content_1 = {
    Text = "Bana o raporu gönderdiğin için teşekkür ederim."
  },
  AvgCommunicate_80104_Content_10 = {
    Text = "O dünyaya geri dönmenin mümkün olup olmadığına gelince, yalnızca Doll: Cehennem ve benim gücüme güvenmek açıkça yeterli değil."
  },
  AvgCommunicate_80104_Content_11 = {
    Text = "Yani benim gücüme mi ihtiyacın var...? Anlıyorum."
  },
  AvgCommunicate_80104_Content_12 = {
