  },
  AvgCommunicate_80104_Content_15 = {
    Text = "Saha görevindeyim... sinyal zayıf... sonra devam ederiz..."
  },
  AvgCommunicate_80104_Content_16 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_17 = {Text = "%player%?"},
  AvgCommunicate_80104_Content_18 = {
    Text = "Heh, hâlâ orada olduğunu biliyorum. Ama sorun değil, daha bolca zamanımız var."
  },
  AvgCommunicate_80104_Content_2 = {
    Text = "Bu, böcek türleri hakkındaki raporumun kısa bir versiyonu. Üzerinde gizli bir şey yok, bu yüzden rahatça saklayabilirsin."
