  },
  AvgCommunicate_80104_Content_5 = {
    Text = "Bu bir hediye, ödül değil."
  },
  AvgCommunicate_80104_Content_6 = {
    Text = "Topraktan Yeniden Doğuş’un için tebrikler ve beni seçtiğin için teşekkür ederim."
