  AvgCommunicate_80104_Content_8 = {
    Text = "Öyle düşünebilirsin."
  },
  AvgCommunicate_80104_Content_9 = {
    Text = "Koruyucu olarak, Uyandırıcılar ile benim müttefik olduğumuza inanmak istiyorum, düşman değil."
