  AvgCommunicate_81323_Content_1 = {
    Text = "Velinimetim, bana yeni bir çalışma kitabını ne zaman vereceksiniz?"
  },
  AvgCommunicate_81323_Content_10 = {
    Text = "Anlıyorum. O halde, bana tavsiye edebileceğiniz başka öğretmenler var mı?"
