  AvgCommunicate_81323_Content_11 = {
    Text = "Yoksa kendi kendime çalışır ve elimden gelenin en iyisini yaparım."
  },
  AvgCommunicate_81323_Content_12 = {
    Text = "Var, ama... tam olarak en dengeli kişi sayılmaz..."
  },
  AvgCommunicate_81323_Content_13 = {
    Text = "Sorun değil. Korkmuyorum."
  },
  AvgCommunicate_81323_Content_14 = {
    Text = "Korkan ben olacağım! Şey, eğer gidip Winkle'ı bulursam... hmm, muhtemelen önce o çıldırır."
  },
  AvgCommunicate_81323_Content_15 = {
    Text = "Çıldırmak mı? Bu Usta Winkle'ın bir tür rahatsızlığı mı var?"
  },
  AvgCommunicate_81323_Content_16 = {
    Text = "Şey hayır... yani, YOK diyemem ama... Ah, boş ver! Önce sana öğrenmenin temel bir gerçeğini öğreteyim!"
  },
  AvgCommunicate_81323_Content_17 = {
    Text = "Pekâlâ, iyilikseverim, kulak kesildim."
  },
  AvgCommunicate_81323_Content_18 = {
    Text = "Basitçe söyleyeyim... her şeyi sorgulamayı bırak!!!"
  },
  AvgCommunicate_81323_Content_19 = {
    Text = "Nasıl olur, velinimetim? Anlamıyorum... yeterince soru sormazsam, bir konuyu gerçekten nasıl öğrenebilirim ki..?"
  },
  AvgCommunicate_81323_Content_2 = {
    Text = "Son iki kitaba gelince, onları baştan sona okudum ve toplamda 107 soru notu çıkardım; boş zamanınızda bana rehberlik etmenizi umuyorum."
  },
  AvgCommunicate_81323_Content_20 = {
    Text = "Bunların hepsinden yorulmadın mı?! Senin bu azimli tavrınla, neye el atsan başarırsın..."
  },
  AvgCommunicate_81323_Content_21 = {
    Text = "Teşekkür ederim, velinimetim. İlgimi çeken şeyleri öğrenme fırsatına sahip olduğum için gerçekten çok şanslıyım."
  },
  AvgCommunicate_81323_Content_22 = {
