  },
  AvgCommunicate_81323_Content_23 = {
    Text = "Peki, beni yeni öğretmenle ne zaman tanıştırabilirsin? Çok fazla soru sormamaya çalışacağım."
  },
  AvgCommunicate_81323_Content_24 = {
    Text = "Şey... 100 yerine sadece 97 soru sorsam olur mu?"
