  },
  AvgCommunicate_81323_Content_4 = {
    Text = "Gerçekten çok özür dilerim."
  },
  AvgCommunicate_81323_Content_6 = {
    Text = "Sana ödevlerimi vermemeliydi. İnsan kendi işlerini kendi halletmeli..."
  },
  AvgCommunicate_81323_Content_7 = {
    Text = "Lütfen, daha fazlasını isteme! Bu böyle devam ederse her gece kabus görürüm!!"
  },
  AvgCommunicate_81323_Content_8 = {
    Text = "Ah...özür dilerim. Velinimetimi bu kadar rahatsız ettiğimin farkında değildim. Çok dikkatsiz davranmışım."
  },
  AvgCommunicate_81323_Content_9 = {
