  AvgCommunicate_81324_Content_11 = {
    Text = "Aynen öyle! Bir düşün. Senden o iki ödevi yapmanı istediğimde, seni bedava iş gücü olarak mı kullanıyordum, yoksa sana yeni bir şey öğrenme fırsatı mı veriyordum?"
