  },
  AvgCommunicate_81324_Content_14 = {
    Text = "Demek öyleymiş. Anlaşılan yanlış anlamışım; sadece ödevlerinde sana yardım etmemi istediğini sanmıştım."
  },
  AvgCommunicate_81324_Content_16 = {
    Text = "Ahaha... Şey, bir daha düşünelim. Bir eylemi birine yardım etmek amacıyla, içtenlikle yardım etmek amacıyla gerçekleştirdiğimizde, bu etik bir eylem olarak kabul edilebilir."
  },
  AvgCommunicate_81324_Content_17 = {
    Text = "Öte yandan, birini tamamen bir araç olarak görmek kesinlikle etik dışı olurdu."
  },
  AvgCommunicate_81324_Content_18 = {
    Text = "Sanırım şimdi anlıyorum. Tıpkı Fener'in beni ve Pollux'u duygularımızı hiçe sayarak kurban olarak kullanması gibi. Yaptıkları etik dışıydı."
  },
  AvgCommunicate_81324_Content_19 = {
    Text = "Aynen, aynen! Mükemmel anladın!"
  },
  AvgCommunicate_81324_Content_2 = {
    Text = "Daha önce ödevin kişinin bilgisini sınamak ve pekiştirmek için kullanıldığını söylemiştin. Eğer bilgi tam olarak öğrenildiyse, ödevi kimin yaptığı önemli değilmiş."
  },
  AvgCommunicate_81324_Content_20 = {
    Text = "Anladım, velinimetim, sen gerçekten etik bir insansın! O halde lütfen bana birkaç ödev daha ver. Özenle tamamlayıp danışmak için geri geleceğim!"
