    Text = "Ne büyülü bir kutu, velinimetim. Bu gerçekten bir tür büyü ya da ritüel dizisiyle çalışmıyor mu?"
  },
  AvgCommunicate_81325_Content_10 = {
    Text = "Tam olarak değil... Sadece bu iki disiplin şu anda ilerleme kaydediyor ve birçok bilim insanı bu çalışmaları genişletip derinleştirerek yeni bilgiler üretiyor."
  },
  AvgCommunicate_81325_Content_11 = {
