  },
  AvgCommunicate_81325_Content_12 = {
    Text = "Anlıyorum. Sürekli gelişen bilgi... gerçekten muhteşem."
  },
  AvgCommunicate_81325_Content_13 = {
    Text = "Biz fener yazıtlarını çalışırken tek bir kelimeyi bile değiştiremeyiz; içerik sabit kalmalı, tekrar edilmeli ve sonsuza dek değişmemelidir."
  },
  AvgCommunicate_81325_Content_14 = {
