  },
  AvgCommunicate_81325_Content_2 = {
    Text = "Hayır, bu tamamen Gümüş çip teknolojisi. Ve hatırlatmak isterim, iletişim cihazı pahalıydı, bu yüzden lütfen parçalarına ayırma."
  },
  AvgCommunicate_81325_Content_20 = {
