  },
  AvgCommunicate_84107_Content_12 = {
    Text = "Evet. Madem bu seçimi yaptım, sorumluluğunu almalıyım."
  },
  AvgCommunicate_84107_Content_13 = {
    Text = "Bundan sonra, bu tatil boyunca akademide hiçbir kaza olmamasını sağlamak için her gece devriye gezeceğim."
  },
  AvgCommunicate_84107_Content_14 = {
    Text = "Koruyucu, şimdilik burada duralım. İşe geri dönmem gerek."
  },
  AvgCommunicate_84107_Content_2 = {
    Text = "...Daha yeni başlamadı mı?"
  },
  AvgCommunicate_84107_Content_4 = {
    Text = "Sadece sırada gelen için hazırlanıyorum."
  },
  AvgCommunicate_84107_Content_5 = {
    Text = "Akademi haritası güncellendi, Saat ayarlandı ve bayraklarla bayrak direkleri düzenlendi."
  },
  AvgCommunicate_84107_Content_6 = {
    Text = "Her gün bunların bakımını yapmaya devam edeceğim, böylece her an işe başlayabilelim."
  },
  AvgCommunicate_84107_Content_7 = {
    Text = "...Öğle yemeği saatini düzenlemek için bu kadar hazırlık gerekiyor mu?"
  },
  AvgCommunicate_84107_Content_8 = {
    Text = "Elbette. Hangi yemekhane en popüler, hangi akademide en çok öğrenci var ve hangi öğrenciler yemekhaneye önce gitmek istiyor; bunların hepsi tüm güzergâh planlamasını etkiler."
  },
  AvgCommunicate_84107_Content_9 = {
    Text = "Hangi çiçekliği yeni başıboş kedi yuva edinmiş, öğrencilerin hangi alanı ezerek yeni bir patika oluşturmuş, hangi yolun bakıma ihtiyacı var..."
  },
  AvgCommunicate_84107_Option_11 = {
    Text = "...Anlıyorum."
  },
  AvgCommunicate_84107_Option_2 = {
    Text = "...Daha yeni başlamadı mı?"
  },
  AvgCommunicate_84107_Option_7 = {
    Text = "Bu kadar hazırlık gerekiyor mu?"
  },
  AvgCommunicate_84108_Content_1 = {
    Text = "Koruyucu, geçen seferki olay için çok özür dilerim."
  },
  AvgCommunicate_84108_Content_10 = {
    Text = "Ama denizde olmadığımız için, koşullara göre bazı düzenlemeler yaptım."
  },
  AvgCommunicate_84108_Content_11 = {
    Text = "Bu düzenlemeler acaba... kendini bana kelepçelemek mi..."
  },
  AvgCommunicate_84108_Content_12 = {
    Text = "Evet. Bu şekilde, bende bir sorun olursa, hemen fark edip müdahale edebilirsin."
  },
  AvgCommunicate_84108_Content_13 = {
    Text = "...Reddedebilir miyim?"
  },
  AvgCommunicate_84108_Content_14 = {
    Text = "Elbette reddetmekte özgürsün."
  },
  AvgCommunicate_84108_Content_15 = {
    Text = "Ama şu an kapının önündeyim."
  },
  AvgCommunicate_84108_Content_2 = {
    Text = "…Uykusuzluğunun Aziz Elmo Ateşi'nin kontrolden çıkmasına neden olduğu zamanı mı kastediyorsun?"
  },
  AvgCommunicate_84108_Content_3 = {
    Text = "Doll: Cehennem beni zamanında bayıltmış olsa da, yine de bir suçluluk duygusu hissediyorum."
  },
  AvgCommunicate_84108_Content_4 = {
    Text = "Uzun süre düşündüm ve cezalandırılmayı hak ettiğim sonucuna vardım."
  },
  AvgCommunicate_84108_Content_5 = {
    Text = "Buna gerçekten gerek yok. Geçen seferki olay ciddi bir sonuca yol açmadı."
  },
  AvgCommunicate_84108_Content_6 = {
    Text = "Hayır, hatalar cezayla karşılanmalıdır. Kurallar böyledir."
  },
  AvgCommunicate_84108_Content_7 = {
    Text = "Kelepçenin bir ucunu zaten kendime taktım. Diğer uç için senin işbirliğin gerekiyor."
  },
  AvgCommunicate_84108_Content_8 = {
    Text = "Benim işbirliğim mi?"
  },
  AvgCommunicate_84108_Content_9 = {
    Text = "Normalde, bir gemide hata yapanlar ayaklarından zincire vurulur ve güvertede birkaç saat güneşin altında bırakılır."
  },
  AvgCommunicate_84108_Option_11 = {
    Text = "Bu düzenlemeler acaba..."
  },
  AvgCommunicate_84108_Option_13 = {
    Text = "...Reddedebilir miyim?"
  },
  AvgCommunicate_84108_Option_2 = {Text = "Yani..."},
  AvgCommunicate_84108_Option_5 = {
    Text = "Buna gerçekten gerek yok."
  },
  AvgCommunicate_84108_Option_8 = {
    Text = "Benim işbirliğim mi?"
  },
  AvgCommunicate_84109_Content_1 = {
    Text = "Koruyucu, teşekkür ederim."
  },
  AvgCommunicate_84109_Content_10 = {Text = "..."},
  AvgCommunicate_84109_Content_11 = {
    Text = "Aslında..."
  },
  AvgCommunicate_84109_Content_12 = {
    Text = "Aslında mı? Neden birden bu kadar çekingen konuşuyorsun? Bu sana hiç benzemiyor."
  },
  AvgCommunicate_84109_Content_13 = {
    Text = "Aslında denizcilik müzelerini ziyaret etmemize gerek yok. Sadece bir \"rahatlama\" anı yaşamak da yeterli."
  },
  AvgCommunicate_84109_Content_14 = {
    Text = "Normal \"rahatlama\" derken ne kastettiğini tam olarak anlayamasam da, seninle birlikteyken derin bir huzur hissediyorum."
  },
  AvgCommunicate_84109_Content_15 = {
    Text = "Huzurlu bir denizde olmak gibi hissettiriyor—ne fırtına var ne de fırtınayla karşılaşma ihtimali. Sadece rotayı takip edip varış noktasına güvenle ulaşmam yeterli."
  },
  AvgCommunicate_84109_Content_16 = {
    Text = "...Bu benzetmeyi takip etmek biraz zor olsa da, ne demek istediğini kabaca anlıyorum."
  },
  AvgCommunicate_84109_Content_17 = {
    Text = "Gelecekte birlikte birçok farklı yeri keşfedebiliriz. Dünya çok geniş; okyanusun ötesinde pek çok güzel manzara var."
  },
  AvgCommunicate_84109_Content_18 = {
    Text = "...Anlıyorum. Deneyeceğim."
  },
  AvgCommunicate_84109_Content_19 = {
    Text = "Gidip göreceğim... okyanustan farklı olan güzel manzaraları."
  },
  AvgCommunicate_84109_Content_2 = {
    Text = "Bu ani teşekkür neden?"
  },
  AvgCommunicate_84109_Content_3 = {
    Text = "Londra Denizcilik Müzesi'ne yaptığım bu gezide çok şey öğrendim."
  },
  AvgCommunicate_84109_Content_4 = {
    Text = "Sergilenen deniz saatleri, elle çizilmiş haritalar ve seyir defteri parçaları, hepsi seyrüsefer becerilerimi geliştirmeme yardımcı olacak."
  },
  AvgCommunicate_84109_Content_5 = {
    Text = "Bunların hepsini bir sonraki Uzun Yolculuk’ta kullanacağım; böylece Herkes’in sağ salim limana dönmesini sağlayacağım."
  },
  AvgCommunicate_84109_Content_6 = {
    Text = "Hatırladığım kadarıyla o gün Londra Denizcilik Müzesi'ne gitme amacımız \"rahatlama\" olması gerekiyordu..."
  },
  AvgCommunicate_84109_Content_7 = {
    Text = "Boş ver. Sen mutlu olduktan sonra."
  },
  AvgCommunicate_84109_Content_8 = {
    Text = "Evet, çok mutluyum ve umarım gelecekte de sık sık birlikte dışarı çıkıp rahatlayabiliriz."
  },
  AvgCommunicate_84109_Content_9 = {
    Text = "Sorun değil. Londra'da ziyaret edebileceğimiz başka denizcilik müzeleri var mı bir bakayım."
  },
  AvgCommunicate_84109_Option_12 = {
    Text = "Gerçekten mi?"
  },
  AvgCommunicate_84109_Option_16 = {
    Text = "...Ne karmaşık bir benzetme."
  },
  AvgCommunicate_84109_Option_2 = {
    Text = "Bu ani teşekkür neden?"
  },
  AvgCommunicate_84109_Option_6 = {Text = "...?"},
  AvgCommunicate_84109_Option_9 = {
    Text = "Sorun değil."
  },
  AvgCommunicate_84110_Content_1 = {
    Text = "Bir sonraki kafein malzemelerini önceden gönderebilir misin, {Male=Mr.,Female=Miss} Koruyucu?"
  },
  AvgCommunicate_84110_Content_10 = {
    Text = "Bekle, bu daha ne kadar saçma olabilir ki!"
  },
  AvgCommunicate_84110_Content_11 = {
    Text = "Winkle şimdi nerede?"
  },
  AvgCommunicate_84110_Content_12 = {
    Text = "Tam burada, iletim cihazı üzerinde deneyler yapıyor, @2<AvgCommunicateConfuseColor.Light> enerjisinin ışık enerjisine dönüştürülüp dönüştürülemeyeceğini test ediyor."
  },
  AvgCommunicate_84110_Content_13 = {
    Text = "Neden reddetmiyorsun?"
  },
  AvgCommunicate_84110_Content_14 = {
    Text = "Neden reddedeyim? Yolculara hizmet etmek görevlerimden biri."
  },
  AvgCommunicate_84110_Content_15 = {Text = "..."},
  AvgCommunicate_84110_Content_16 = {
    Text = "Şimdi geçiyorum. Winkle'ı benim için tut."
  },
  AvgCommunicate_84110_Content_17 = {
    Text = "Anlaşıldı. Ölüm pahasına da olsa emrinizi yerine getireceğim."
  },
  AvgCommunicate_84110_Content_2 = {
    Text = "Winkle yine senin payını mı aldı?"
  },
  AvgCommunicate_84110_Content_3 = {
    Text = "Kesin konuşmak gerekirse, \"alınmadı,\" daha çok o yolcuya ben verdim."
  },
  AvgCommunicate_84110_Content_4 = {
    Text = "...Yine \"bir dahaki sefere yolculuğa katılacağım\" bahanesiyle mi?"
  },
  AvgCommunicate_84110_Content_5 = {
    Text = "Ben yalnızca görevimi yerine getiriyorum. Yolculara hizmet etmek de sorumluluklarımdan biri."
  },
  AvgCommunicate_84110_Content_6 = {
    Text = "...Malzeme talebi onaylandı. Bu son sefer."
  },
  AvgCommunicate_84110_Content_7 = {
    Text = "Bu arada, Winkle hâlâ göğsünüzden @2 çıkarmaya çalışıyor mu son zamanlarda?"
  },
  AvgCommunicate_84110_Content_8 = {
    Text = "Artık hayır; bu yolcu araştırma yöntemlerini değiştirdi."
  },
  AvgCommunicate_84110_Content_9 = {
    Text = "Örneğin, @2<AvgCommunicateConfuseColor.Light> şiddetini bir darbe akımı ölçerle test etmek, @2<AvgCommunicateConfuseColor.Light> tayf çizgilerini bir prizmayla taramak, @2<AvgCommunicateConfuseColor.Light> ile sinir lifleri arasındaki bağlantıyı doğrulamak için bir insan test platformu kullanmak..."
  },
  AvgCommunicate_84110_Option_10 = {
    Text = "Bekle, bu daha ne kadar saçma olabilir ki!"
  },
  AvgCommunicate_84110_Option_13 = {
    Text = "Neden reddetmiyorsun?"
  },
  AvgCommunicate_84110_Option_15 = {Text = "..."},
  AvgCommunicate_84110_Option_2 = {
    Text = "Winkle yine senin payını mı aldı?"
  },
  AvgCommunicate_84110_Option_4 = {
    Text = "Yine, sebebi de..."
  },
  AvgCommunicate_84110_Option_6 = {
    Text = "Tedarik talebi onaylandı..."
  },
  AvgCommunicate_94500_Content_1 = {
    Text = "Tanıştırmanız sayesinde, Lord Ogier ile tanıştıktan sonra o da bizi daha fazla arkadaşla tanıştırdı."
  },
  AvgCommunicate_94500_Content_10 = {
    Text = "Lord Ogier ayrıca bir şövalyenin eğitiminin bundan çok daha karmaşık ve yorucu olduğunu söyledi. Görünüşe göre, hikayelerde anlatıldığı gibi, her şövalye gerçekten saygıdeğer bir insanmış."
  },
  AvgCommunicate_94500_Content_11 = {
    Text = "Gerçekten de Ogier, tüm Uyandırıcılar arasında eğitimde en çalışkan olanıdır!"
  },
  AvgCommunicate_94500_Content_12 = {
    Text = "Ayrıca Eğitmen Alva'nın engeline rağmen bizimle tamamen aynı eğitimi yaptığını fark ettik."
  },
  AvgCommunicate_94500_Content_13 = {
    Text = "Başlangıçta Eğitmen Alva'nın da bir şövalye olduğunu düşünmüştük, ama eskiden asker olduğunu söyledi. Askerliğin ne tür bir meslek olduğunu bilmiyorum, ama şövalyelik kadar saygıdeğer olmalı."
  },
  AvgCommunicate_94500_Content_14 = {
    Text = "Askerler ülkeleri için savaşan insanlardır, bu yüzden onları bir tür şövalye olarak düşünebilirsiniz. Ancak şövalyelerin katı ahlak kurallarıyla karşılaştırıldığında, bir askerin eylemleri her zaman adaleti temsil etmez."
  },
  AvgCommunicate_94500_Content_15 = {
    Text = "Alva bunu ancak ordudan ayrıldıktan sonra fark etti. Belki de şu anki hayatı onun için daha huzurlu."
  },
  AvgCommunicate_94500_Content_16 = {
    Text = "Anlıyorum. Bir şövalyenin gücü değil, adalet ruhunu temsil ettiğini kastediyorsun. Eğitmen Alva ve hatta senin gibi insanlar, hepiniz bir şövalyenin ruhuna sahipsiniz."
  },
  AvgCommunicate_94500_Content_18 = {
    Text = "Çok güzel söylenmiş olsa da, neden bu kadar utandırıyor beni...?"
  },
  AvgCommunicate_94500_Content_2 = {
    Text = "Bu harika bir haber! Sizin adınıza gerçekten mutluyum."
  },
  AvgCommunicate_94500_Content_3 = {
    Text = "Birçok Uyandırıcı ile tanıştık ve gerçekten de dediğiniz gibi, çoğu cana yakın insanlar."
  },
  AvgCommunicate_94500_Content_4 = {
    Text = "Buraya ilk geldiğimde başkalarına karşı ne kadar temkinli ve şüpheci olduğumu düşündüğümde oldukça utanıyorum."
  },
  AvgCommunicate_94500_Content_5 = {
    Text = "Aslında sorun yok. Sonuçta dikkatli olmanız gereken epeyce insan var..."
  },
  AvgCommunicate_94500_Content_6 = {
    Text = "Castor ve ben şu anda Lord Ogier ile birlikte Eğitmen Alva'nın eğitim kursuna katılıyoruz."
  },
  AvgCommunicate_94500_Content_7 = {
    Text = "Lord Ogier'in dövüş duruşu gerçekten göz kamaştırıcı, ama kendisi övgü almaya alışkın değilmiş gibi görünüyor. Ne kadar mütevazı bir insan."
  },
  AvgCommunicate_94500_Content_8 = {
    Text = "Ha ha, Ogier sadece kolay utanır. Onunla normal konuşun yeter."
  },
  AvgCommunicate_94500_Content_9 = {
    Text = "Anlıyorum. Castor ve ben kilisede hiç dövüş eğitimi almadık; bu kadar ağır egzersiz gerçekten yorucu. Ama Lord Ogier bunu her gün yaptığını söylüyor. Ne inanılmaz bir azim."
  },
  AvgCommunicate_94500_Option_11 = {
    Text = "Gerçekten de Ogier, tüm Uyandırıcılar arasında eğitimde en çalışkan olanıdır!"
  },
  AvgCommunicate_94500_Option_14 = {
    Text = "Sanırım öyle..."
  },
  AvgCommunicate_94500_Option_2 = {
    Text = "Bu harika bir haber! Sizin adınıza gerçekten mutluyum."
  },
  AvgCommunicate_94500_Option_5 = {
    Text = "Aslında sorun yok. Sonuçta dikkatli olmanız gereken epeyce insan var..."
  },
  AvgCommunicate_94500_Option_8 = {
    Text = "Ogier sadece çabuk utanan biridir."
  },
  AvgCommunicate_94501_Content_1 = {
    Text = "Saygıdeğer Velinimetim, Castor ve benim için bu evi özenle hazırladığınız için teşekkür ederim."
  },
  AvgCommunicate_94501_Content_10 = {
    Text = "Castor o kadar hoşuna gitti ki günde beş kez yüzünü yıkıyordu, ama ben müdahale ettikten sonra üçe düştü."
  },
  AvgCommunicate_94501_Content_12 = {
    Text = "Yüzünü çok sık yıkamak cildine zarar verir!"
  },
  AvgCommunicate_94501_Content_13 = {
    Text = "Ama bir dakika, daha önce bunları hiç kullanmamış mıydınız? Fener Kilisesi'nin bu kadar sade olduğunu bilmiyordum."
  },
  AvgCommunicate_94501_Content_14 = {
    Text = "Gerçekten kullanmamıştık, ama bu kilisenin sadeliğinden değil. İkiz İlahiler olarak, her zaman arzularımızı dizginlememiz ve ruhani eğitimimize odaklanmamız gerekiyordu."
  },
  AvgCommunicate_94501_Content_15 = {
    Text = "Bu tür teknoloji ürünleriyle neredeyse hiç temasımız olmadı. Günlük rutinlerimiz ve yemeklerimiz birçok katı kuralla yönetiliyordu."
  },
  AvgCommunicate_94501_Content_16 = {
    Text = "Kıyafetlerimiz ve yemeklerimiz genel olarak lüks olsa da, yemek saatleri dışında bir şey yiyemezdik ve uyanma vakti geldiğinde hemen odadan çıkmamız gerekirdi."
  },
  AvgCommunicate_94501_Content_17 = {
    Text = "Çocukken, erken kalkmak zorunda olmadığım ve bütün gün istediğimi yiyebildiğim bir günü sık sık hayal ederdim."
  },
  AvgCommunicate_94501_Content_18 = {
    Text = "Son birkaç gündür, öğleden sonra koridordan yiyecek taşıyan genç bir kız gördüm defalarca. Görünüşe göre hayalini kurduğum yaşam burada zaten sıradan bir şey."
  },
  AvgCommunicate_94501_Content_19 = {
    Text = "Ah, o büyük ihtimalle Murphy'dir, küçük keklerini almaya gidiyordur... Geçmişteki hayatınız gerçekten çok yorucu görünüyor."
  },
  AvgCommunicate_94501_Content_2 = {
    Text = "Castor eve özel olarak bir yatak eklendiğinden bahsettiğinde, bunun senin düşünceli bir jestin olduğunu hemen anladım."
  },
  AvgCommunicate_94501_Content_20 = {
    Text = "Artık her şey geride kaldı. O hatalar ve çarpıtmalar geçmişte kalacak. Yeni bir başlangıçla doğru yola çıkacağız ve buna tanıklık etmeni rica ediyoruz."
  },
  AvgCommunicate_94501_Content_21 = {
    Text = "Çok naziksiniz. Herhangi bir sorunuz olursa bana bildirmeniz yeterli. Sadece tavrınız bile sizi bazı diğer Uyandırıcılardan sayısız kat daha güven verici kılıyor!"
  },
  AvgCommunicate_94501_Content_3 = {
    Text = "Kilise sarayında aynı odayı paylaşarak büyüdük ve burada kural olarak herkesin ayrı odasının olduğunu duyduğumuzda oldukça endişelendik."
  },
  AvgCommunicate_94501_Content_4 = {
    Text = "İhtiyaçlarımızı bu kadar titizlikle gözettiğini görünce, Leydi Thais'in sana sığınmamızı önermesinin ne kadar doğru olduğunu gerçekten anlıyorum."
  },
  AvgCommunicate_94501_Content_5 = {
    Text = "Haha, önemli değil, gerçekten. Geldiğinizden beri rahat edebildiniz mi?"
  },
  AvgCommunicate_94501_Content_6 = {
    Text = "Senin ilgin sayesinde her şey yolunda. Buradaki odalar bir hizmetçi odası kadar küçük olsa da tamamen döşenmiş durumda ve alıştıktan sonra oldukça sıcak ve rahat hissettiriyor."
  },
  AvgCommunicate_94501_Content_7 = {
    Text = "Ahaha, öyle mi? Şey, iyi o zaman, iyi..."
  },
  AvgCommunicate_94501_Content_8 = {
    Text = "Hizmet edilmeden yaşamayı yavaş yavaş öğrendik; lütfen bizim için endişelenme. Aslında bu, ikimizin de yıllardır hayalini kurduğu bir şeydi."
  },
  AvgCommunicate_94501_Content_9 = {
    Text = "Odada sağlanan yüz temizleyicisi gerçekten harika—talimatlara göre kullanıldığında bulut gibi köpükler çıkarıyor. Ve diş macununun tadı çok ferahlatıcı!"
  },
  AvgCommunicate_94501_Option_19 = {
    Text = "Ah, o büyük ihtimalle Murphy'dir, küçük keklerini almaya gidiyordur..."
  },
  AvgCommunicate_94501_Option_21 = {
    Text = "Çok naziksiniz."
  },
  AvgCommunicate_94501_Option_5 = {
    Text = "Ah, hiç önemli değil."
  },
  AvgCommunicate_94501_Option_7 = {
    Text = "Ahaha, öyle mi? Şey, iyi o zaman, iyi..."
  },
  AvgCommunicate_94502_Content_1 = {
    Text = "Rahatsız ettiğim için özür dilerim, ancak bir tanıştırma için küçük bir ricada bulunabilir miyim?"
  },
  AvgCommunicate_94502_Content_10 = {
    Text = "Ah! O Ogier ve Lotan olmalı."
  },
  AvgCommunicate_94502_Content_11 = {
    Text = "Ogier... İsmi not ettim. O genç adamın duruşu öyle onurlu ve kahramancaydı ki, gerçekten kalbimizi fethetti. Castor ve ben yaklaşmak istedik ama çabucak geçip gittiler."
  },
  AvgCommunicate_94502_Content_12 = {
    Text = "Yatakhaneye döndükten sonra o şövalyeyi düşünmekten kendimizi alamadık, ama nasıl iletişim kuracağımızı bilemedik. Bu yüzden sizi tanıştırmanız için ricaya geldik, umarız tanışmamızı sağlamak için zaman ve emek ayırabilirsiniz."
  },
  AvgCommunicate_94502_Content_13 = {
    Text = "Anlıyorum. Açıkçası, bu kadar resmi olmanıza gerek yok. Ogier çok iyi kalpli bir insandır. Ona sormanız yeterli, arkadaşınız olmaktan memnuniyet duyar."
  },
  AvgCommunicate_94502_Content_14 = {
    Text = "Gerçek bir şövalye için gerçekten takdire değer—böyle bir geniş görüşlülük övgüye değer, bir zamanlar düşman olan bizim gibileri kabul etmeye istekli olması."
  },
